import { sql } from '@/lib/neon';
/**
 * Customer Statement Detail API
 * GET /api/accounting/customer-statement-detail?client_id=UUID
 * Returns full transaction-level statement with running balance
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';


// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const clientId = req.query.client_id as string;
  if (!clientId) {
    return apiResponse.badRequest(res, 'client_id is required');
  }

  try {
    // Get client info
    const clientRows = (await sql`
      SELECT id, company_name, email, phone FROM clients WHERE id = ${clientId}::UUID
    `) as Row[];
    if (clientRows.length === 0) {
      return apiResponse.notFound(res, 'Client', clientId);
    }
    const client = clientRows[0];

    // Get invoices
    const invoices = (await sql`
      SELECT id, invoice_number, invoice_date, reference, total_amount, status
      FROM customer_invoices
      WHERE client_id = ${clientId}::UUID AND status != 'cancelled'
      ORDER BY invoice_date
    `) as Row[];

    // Get confirmed payments — includes both allocated and unallocated (bank-sourced)
    const payments = (await sql`
      SELECT cp.id, cp.payment_number, cp.payment_date, cp.bank_reference,
        COALESCE(SUM(cpa.amount_allocated), cp.total_amount) AS amount_allocated
      FROM customer_payments cp
      LEFT JOIN customer_payment_allocations cpa ON cpa.payment_id = cp.id
      WHERE cp.client_id = ${clientId}::UUID AND cp.status IN ('confirmed', 'reconciled')
      GROUP BY cp.id, cp.payment_number, cp.payment_date, cp.bank_reference, cp.total_amount
    `) as Row[];

    // Get approved customer credit notes
    const creditNotes = (await sql`
      SELECT id, credit_note_number, credit_date, reason, total_amount
      FROM credit_notes
      WHERE client_id = ${clientId}::UUID AND type = 'customer' AND status = 'approved'
    `) as Row[];

    // Normalize date to YYYY-MM-DD regardless of input format
    const toISODate = (val: unknown): string => {
      if (!val) return '1970-01-01';
      if (val instanceof Date) return val.toISOString().split('T')[0] ?? '1970-01-01';
      const s = String(val);
      if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.split('T')[0] ?? '1970-01-01';
      const d = new Date(s);
      return isNaN(d.getTime()) ? '1970-01-01' : (d.toISOString().split('T')[0] ?? '1970-01-01');
    };

    // Build transaction list
    interface Transaction {
      id: number | string;
      date: string;
      type: 'invoice' | 'payment' | 'credit_note';
      reference: string;
      description: string;
      debit: number;
      credit: number;
      balance: number;
    }

    const transactions: Transaction[] = [];

    for (const inv of invoices) {
      transactions.push({
        id: inv.id,
        date: toISODate(inv.invoice_date),
        type: 'invoice',
        reference: String(inv.invoice_number),
        description: inv.reference ? String(inv.reference) : '',
        debit: Number(inv.total_amount),
        credit: 0,
        balance: 0,
      });
    }

    for (const pmt of payments) {
      transactions.push({
        id: pmt.id,
        date: toISODate(pmt.payment_date),
        type: 'payment',
        reference: String(pmt.payment_number),
        description: pmt.bank_reference ? String(pmt.bank_reference) : '',
        debit: 0,
        credit: Number(pmt.amount_allocated),
        balance: 0,
      });
    }

    for (const cn of creditNotes) {
      transactions.push({
        id: cn.id,
        date: toISODate(cn.credit_date),
        type: 'credit_note',
        reference: String(cn.credit_note_number),
        description: cn.reason ? String(cn.reason) : '',
        debit: 0,
        credit: Number(cn.total_amount),
        balance: 0,
      });
    }

    // Sort chronologically, invoices before payments on same date
    transactions.sort((a, b) => {
      if (a.date !== b.date) return a.date < b.date ? -1 : 1;
      const typeOrder: Record<string, number> = { invoice: 0, credit_note: 1, payment: 2 };
      return (typeOrder[a.type] ?? 9) - (typeOrder[b.type] ?? 9);
    });

    // Calculate running balance
    let runningBalance = 0;
    let totalInvoiced = 0;
    let totalPaid = 0;
    let totalCredits = 0;

    for (const txn of transactions) {
      runningBalance += txn.debit - txn.credit;
      txn.balance = runningBalance;
      totalInvoiced += txn.debit;
      if (txn.type === 'payment') totalPaid += txn.credit;
      if (txn.type === 'credit_note') totalCredits += txn.credit;
    }

    return apiResponse.success(res, {
      client: {
        id: String(client.id),
        name: String(client.company_name),
        email: client.email ? String(client.email) : null,
        phone: client.phone ? String(client.phone) : null,
      },
      transactions,
      summary: {
        totalInvoiced,
        totalPaid,
        totalCredits,
        balance: runningBalance,
      },
    });
  } catch (err) {
    log.error('Failed to fetch customer statement detail', { clientId, error: err, module: 'accounting' });
    return apiResponse.databaseError(res, err, 'Failed to fetch customer statement');
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Supplier Statement Detail API
 * GET /api/accounting/supplier-statement-detail?supplier_id=UUID
 * Returns full transaction history (invoices, payments, returns) with running balance
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { log } from '@/lib/logger';

interface Transaction {
  id: number;
  date: string;
  type: 'invoice' | 'payment' | 'debit_note';
  reference: string;
  description: string;
  debit: number;
  credit: number;
  balance: number;
}

export default withCompany(withErrorHandler(async (req: NextApiRequest, res: NextApiResponse) => {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || '', ['GET']);

  const { supplier_id } = req.query;
  if (!supplier_id) return apiResponse.badRequest(res, 'supplier_id is required');

  try {
    // Get supplier info
    const supplierRows = await sql`
      SELECT id, name, email, phone FROM suppliers WHERE id = ${Number(supplier_id)}
    `;
    if (supplierRows.length === 0) return apiResponse.notFound(res, 'Supplier', supplier_id as string);
    const supplier = supplierRows[0] as { id: number; name: string; email: string | null; phone: string | null };

    // Get invoices
    const invoices = await sql`
      SELECT id, invoice_number as reference, invoice_date as date,
        total_amount as amount, amount_paid, notes as description
      FROM supplier_invoices
      WHERE supplier_id = ${Number(supplier_id)}
        AND status NOT IN ('cancelled', 'draft')
      ORDER BY invoice_date ASC
    `;

    // Get payments
    const payments = await sql`
      SELECT sp.id, sp.payment_number as reference, sp.payment_date as date,
        sp.total_amount as amount, sp.description
      FROM supplier_payments sp
      WHERE sp.supplier_id = ${Number(supplier_id)}
        AND sp.status NOT IN ('cancelled', 'draft')
      ORDER BY sp.payment_date ASC
    `;

    // Get debit notes (supplier returns)
    const returns = await sql`
      SELECT cn.id, cn.credit_note_number as reference, cn.credit_date as date,
        cn.total_amount as amount, cn.reason as description
      FROM credit_notes cn
      WHERE cn.supplier_id = ${Number(supplier_id)}
        AND cn.type = 'supplier'
        AND cn.status NOT IN ('cancelled', 'draft')
      ORDER BY cn.credit_date ASC
    `;

    // Normalize date to YYYY-MM-DD regardless of input format
    const toISODate = (val: unknown): string => {
      if (!val) return '1970-01-01';
      if (val instanceof Date) return val.toISOString().split('T')[0] ?? '1970-01-01';
      const s = String(val);
      if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.split('T')[0] ?? '1970-01-01';
      const d = new Date(s);
      return isNaN(d.getTime()) ? '1970-01-01' : (d.toISOString().split('T')[0] ?? '1970-01-01');
    };

    // Merge into chronological transactions
    const transactions: Transaction[] = [];

    for (const inv of invoices as { id: number; reference: string; date: string; amount: number; description: string }[]) {
      transactions.push({
        id: inv.id,
        date: toISODate(inv.date),
        type: 'invoice',
        reference: inv.reference || '-',
        description: inv.description || 'Supplier Invoice',
        debit: Number(inv.amount),
        credit: 0,
        balance: 0,
      });
    }

    for (const pmt of payments as { id: number; reference: string; date: string; amount: number; description: string }[]) {
      transactions.push({
        id: pmt.id,
        date: toISODate(pmt.date),
        type: 'payment',
        reference: pmt.reference || '-',
        description: pmt.description || 'Payment',
        debit: 0,
        credit: Number(pmt.amount),
        balance: 0,
      });
    }

    for (const ret of returns as { id: number; reference: string; date: string; amount: number; description: string }[]) {
      transactions.push({
        id: ret.id,
        date: toISODate(ret.date),
        type: 'debit_note',
        reference: ret.reference || '-',
        description: ret.description || 'Debit Note',
        debit: 0,
        credit: Number(ret.amount),
        balance: 0,
      });
    }

    // Sort chronologically, invoices before payments on same date
    transactions.sort((a, b) => {
      if (a.date !== b.date) return a.date < b.date ? -1 : 1;
      const typeOrder: Record<string, number> = { invoice: 0, debit_note: 1, payment: 2 };
      return (typeOrder[a.type] ?? 9) - (typeOrder[b.type] ?? 9);
    });

    // Calculate running balance
    let running = 0;
    for (const txn of transactions) {
      running += txn.debit - txn.credit;
      txn.balance = running;
    }

    const totalInvoiced = transactions.reduce((s, t) => s + t.debit, 0);
    const totalPaid = transactions.filter(t => t.type === 'payment').reduce((s, t) => s + t.credit, 0);
    const totalReturns = transactions.filter(t => t.type === 'debit_note').reduce((s, t) => s + t.credit, 0);

    return apiResponse.success(res, {
      supplier,
      transactions,
      summary: {
        totalInvoiced,
        totalPaid,
        totalReturns,
        balance: totalInvoiced - totalPaid - totalReturns,
      },
    });
  } catch (err) {
    log.error('Supplier statement detail failed', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to load supplier statement');
  }
}));

/**
 * Debtors Manager API
 * GET /api/accounting/debtors-manager
 *
 * Query params:
 *   ?customerId=UUID      → returns DebtorInvoice[] for that customer
 *   ?daysOverdue=30       → filters overdue invoices to >= N days
 *   (no params)           → returns { summary, stats, overdueInvoices }
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getDebtorsSummary,
  getDebtorDetail,
  getOverdueInvoices,
  getCollectionStats,
} from '@/modules/accounting/services/debtorsManagerService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET']);
  }

  try {
    const { customerId, daysOverdue } = req.query;

    // Detail view — invoices for a single customer
    if (customerId) {
      const detail = await getDebtorDetail(String(customerId));
      return apiResponse.success(res, detail);
    }

    // Full dashboard — summary + stats + overdue list
    const minDays = daysOverdue ? Number(daysOverdue) : undefined;

    const [summary, stats, overdueInvoices] = await Promise.all([
      getDebtorsSummary(),
      getCollectionStats(),
      getOverdueInvoices(minDays),
    ]);

    return apiResponse.success(res, { summary, stats, overdueInvoices });
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to load debtors data';
    log.error('debtors-manager API error', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Dunning Communications API
 * GET: List dunning communications (optionally filter by client_id)
 * POST: Create a new dunning communication
 * PUT: Update status (e.g. mark as sent)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

export default withCompany(withErrorHandler(async (req: NextApiRequest, res: NextApiResponse) => {
  switch (req.method) {
    case 'GET': {
      const { client_id, status: filterStatus, limit: limitStr } = req.query;
      const rowLimit = Math.min(parseInt(limitStr as string, 10) || 100, 500);

      if (client_id) {
        const rows = (await sql`
          SELECT dc.*, c.company_name as client_name,
                 u.first_name || ' ' || u.last_name as created_by_name
          FROM dunning_communications dc
          JOIN clients c ON c.id = dc.client_id
          LEFT JOIN users u ON u.id = dc.created_by
          WHERE dc.client_id = ${client_id as string}
          ORDER BY dc.created_at DESC
          LIMIT ${rowLimit}
        `) as Row[];
        return apiResponse.success(res, rows);
      }

      if (filterStatus) {
        const rows = (await sql`
          SELECT dc.*, c.company_name as client_name,
                 u.first_name || ' ' || u.last_name as created_by_name
          FROM dunning_communications dc
          JOIN clients c ON c.id = dc.client_id
          LEFT JOIN users u ON u.id = dc.created_by
          WHERE dc.status = ${filterStatus as string}
          ORDER BY dc.created_at DESC
          LIMIT ${rowLimit}
        `) as Row[];
        return apiResponse.success(res, rows);
      }

      const rows = (await sql`
        SELECT dc.*, c.company_name as client_name,
               u.first_name || ' ' || u.last_name as created_by_name
        FROM dunning_communications dc
        JOIN clients c ON c.id = dc.client_id
        LEFT JOIN users u ON u.id = dc.created_by
        ORDER BY dc.created_at DESC
        LIMIT ${rowLimit}
      `) as Row[];
      return apiResponse.success(res, rows);
    }

    case 'POST': {
      const {
        client_id, type = 'reminder', level = 1,
        subject, body, total_overdue = 0,
        invoices_included = [], sent_via = 'email', sent_to
      } = req.body;

      if (!client_id || !subject || !body) {
        return apiResponse.badRequest(res, 'client_id, subject, and body are required');
      }

      const userId = (req as NextApiRequest & { user?: { id: string } }).user?.id || null;

      const rows = (await sql`
        INSERT INTO dunning_communications (
          client_id, type, level, subject, body, total_overdue,
          invoices_included, sent_via, sent_to, status, created_by
        ) VALUES (
          ${client_id}, ${type}, ${level}, ${subject}, ${body},
          ${total_overdue}, ${invoices_included}, ${sent_via},
          ${sent_to || null}, 'draft', ${userId}
        )
        RETURNING *
      `) as Row[];

      log.info('Dunning communication created', { client_id, type, level }, 'accounting');
      return apiResponse.success(res, rows[0], 'Communication created', 201);
    }

    case 'PUT': {
      const { id, status: newStatus, sent_at } = req.body;
      if (!id) return apiResponse.badRequest(res, 'id is required');

      const rows = (await sql`
        UPDATE dunning_communications
        SET status = COALESCE(${newStatus || null}, status),
            sent_at = COALESCE(${sent_at || null}, sent_at)
        WHERE id = ${id}
        RETURNING *
      `) as Row[];
      if (rows.length === 0) return apiResponse.notFound(res, 'Communication', id);
      return apiResponse.success(res, rows[0]);
    }

    default:
      return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'PUT']);
  }
}));

/**
 * Approval Requests API
 * GET  — list requests (optional ?status=pending)
 * POST — create request or decide on request
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import {
  listRequests, requestApproval, decideRequest, checkApproval, getPendingCount,
  type ApprovalStatus,
} from '@/modules/accounting/services/approvalService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    const status = req.query.status as ApprovalStatus | undefined;

    if (req.query.action === 'check') {
      const { documentType, documentId, amount } = req.query;
      if (!documentType || !documentId) {
        return apiResponse.badRequest(res, 'documentType and documentId are required');
      }
      const result = await checkApproval(
        documentType as any,
        documentId as string,
        Number(amount) || 0
      );
      return apiResponse.success(res, result);
    }

    if (req.query.action === 'count') {
      const count = await getPendingCount();
      return apiResponse.success(res, { count });
    }

    const requests = await listRequests(status);
    return apiResponse.success(res, { items: requests });
  }

  if (req.method === 'POST') {
    const { action } = req.body;

    if (action === 'request') {
      const { ruleId, documentType, documentId, documentReference, amount } = req.body;
      if (!ruleId || !documentType || !documentId) {
        return apiResponse.badRequest(res, 'ruleId, documentType, and documentId are required');
      }
      const request = await requestApproval({
        ruleId, documentType, documentId, documentReference, amount, requestedBy: userId,
      });
      return apiResponse.success(res, request);
    }

    if (action === 'approve' || action === 'reject') {
      const { requestId, notes } = req.body;
      if (!requestId) return apiResponse.badRequest(res, 'requestId is required');
      const decision = action === 'approve' ? 'approved' : 'rejected';
      const result = await decideRequest(requestId, decision, userId, notes);
      return apiResponse.success(res, result);
    }

    return apiResponse.badRequest(res, 'Invalid action. Use: request, approve, reject');
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Approval Rules API
 * GET  — list all rules
 * POST — create a new rule
 * PUT  — update a rule
 * DELETE — delete a rule
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
