/**
 * Approval Requests API
 * GET  — list requests (optional ?status=pending)
 * POST — create request or decide on request
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import {
  listRequests, requestApproval, decideRequest, checkApproval, getPendingCount,
  type ApprovalStatus,
} from '@/modules/accounting/services/approvalService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    const status = req.query.status as ApprovalStatus | undefined;

    if (req.query.action === 'check') {
      const { documentType, documentId, amount } = req.query;
      if (!documentType || !documentId) {
        return apiResponse.badRequest(res, 'documentType and documentId are required');
      }
      const result = await checkApproval(
        documentType as any,
        documentId as string,
        Number(amount) || 0
      );
      return apiResponse.success(res, result);
    }

    if (req.query.action === 'count') {
      const count = await getPendingCount();
      return apiResponse.success(res, { count });
    }

    const requests = await listRequests(status);
    return apiResponse.success(res, { items: requests });
  }

  if (req.method === 'POST') {
    const { action } = req.body;

    if (action === 'request') {
      const { ruleId, documentType, documentId, documentReference, amount } = req.body;
      if (!ruleId || !documentType || !documentId) {
        return apiResponse.badRequest(res, 'ruleId, documentType, and documentId are required');
      }
      const request = await requestApproval({
        ruleId, documentType, documentId, documentReference, amount, requestedBy: userId,
      });
      return apiResponse.success(res, request);
    }

    if (action === 'approve' || action === 'reject') {
      const { requestId, notes } = req.body;
      if (!requestId) return apiResponse.badRequest(res, 'requestId is required');
      const decision = action === 'approve' ? 'approved' : 'rejected';
      const result = await decideRequest(requestId, decision, userId, notes);
      return apiResponse.success(res, result);
    }

    return apiResponse.badRequest(res, 'Invalid action. Use: request, approve, reject');
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Approval Rules API
 * GET  — list all rules
 * POST — create a new rule
 * PUT  — update a rule
 * DELETE — delete a rule
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { listRules, createRule, updateRule, deleteRule } from '@/modules/accounting/services/approvalService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    const rules = await listRules();
    return apiResponse.success(res, { items: rules });
  }

  if (req.method === 'POST') {
    const { name, documentType, conditionField, conditionOperator, conditionValue, approverRole } = req.body;
    if (!name || !documentType) {
      return apiResponse.badRequest(res, 'name and documentType are required');
    }
    const rule = await createRule({ name, documentType, conditionField, conditionOperator, conditionValue, approverRole });
    return apiResponse.success(res, rule);
  }

  if (req.method === 'PUT') {
    const { id, ...updates } = req.body;
    if (!id) return apiResponse.badRequest(res, 'id is required');
    const rule = await updateRule(id, updates);
    return apiResponse.success(res, rule);
  }

  if (req.method === 'DELETE') {
    const id = req.query.id as string || req.body.id;
    if (!id) return apiResponse.badRequest(res, 'id is required');
    await deleteRule(id);
    return apiResponse.success(res, { deleted: true });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST', 'PUT', 'DELETE']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Document Capture API
 * POST /api/accounting/document-capture  — Upload PDF, extract data, save
 * GET  /api/accounting/document-capture  — List captured documents
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import formidable from 'formidable';
import fs from 'fs';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import { extractFromPdf } from '@/modules/accounting/services/ocrService';
import type { CapturedDocument } from '@/modules/accounting/types/documentCapture.types';

export const config = {
  api: { bodyParser: false },
};

const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

function parseForm(req: NextApiRequest): Promise<{ fields: formidable.Fields; files: formidable.Files }> {
  return new Promise((resolve, reject) => {
    const form = formidable({
      maxFileSize: MAX_FILE_SIZE,
      keepExtensions: true,
      filter: (part) => {
        // Only accept PDF files
        return part.mimetype === 'application/pdf' || part.mimetype === null || part.mimetype === undefined;
      },
    });
    form.parse(req, (err, fields, files) => {
      if (err) reject(err);
      else resolve({ fields, files });
    });
  });
}

function mapRow(row: Record<string, unknown>): CapturedDocument {
  return {
    id: row.id as string,
    fileName: row.file_name as string,
    fileType: row.file_type as string,
    fileSize: row.file_size as number | null,
    documentType: row.document_type as string | null,
    extractedData: row.extracted_data ? (typeof row.extracted_data === 'string' ? JSON.parse(row.extracted_data as string) : row.extracted_data) : null,
    vendorName: row.vendor_name as string | null,
    documentDate: row.document_date ? new Date(row.document_date as string).toISOString().split('T')[0]! : null,
    referenceNumber: row.reference_number as string | null,
    totalAmount: row.total_amount !== null && row.total_amount !== undefined ? parseFloat(String(row.total_amount)) : null,
    vatAmount: row.vat_amount !== null && row.vat_amount !== undefined ? parseFloat(String(row.vat_amount)) : null,
    status: (row.status as CapturedDocument['status']) || 'pending',
    matchedInvoiceId: row.matched_invoice_id as string | null,
    matchedBankTxId: row.matched_bank_tx_id as string | null,
    notes: row.notes as string | null,
    uploadedBy: row.uploaded_by as string | null,
    createdAt: new Date(row.created_at as string).toISOString(),
  };
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') return handleGet(req, res);
  if (req.method === 'POST') return handlePost(req, res);
  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

/** GET — List captured documents */
async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const status = req.query.status as string | undefined;
  const page = Math.max(1, parseInt(String(req.query.page || '1'), 10));
  const pageSize = Math.min(100, Math.max(1, parseInt(String(req.query.pageSize || '25'), 10)));
  const offset = (page - 1) * pageSize;

  let rows: Record<string, unknown>[];
  let countResult: Record<string, unknown>[];

  if (status) {
    rows = await sql`
      SELECT * FROM captured_documents
      WHERE status = ${status}
      ORDER BY created_at DESC
      LIMIT ${pageSize} OFFSET ${offset}
    ` as Record<string, unknown>[];

    countResult = await sql`
      SELECT COUNT(*)::int AS total FROM captured_documents WHERE status = ${status}
    ` as Record<string, unknown>[];
  } else {
    rows = await sql`
      SELECT * FROM captured_documents
      ORDER BY created_at DESC
      LIMIT ${pageSize} OFFSET ${offset}
    ` as Record<string, unknown>[];

    countResult = await sql`
      SELECT COUNT(*)::int AS total FROM captured_documents
    ` as Record<string, unknown>[];
  }

  const total = (countResult[0]?.total as number) || 0;
  const documents = rows.map(r => mapRow(r));

  return apiResponse.paginated(res, documents, { page, pageSize, total });
}

/** POST — Upload a PDF, extract data, save to captured_documents */
async function handlePost(req: NextApiRequest, res: NextApiResponse) {
  const user = (req as NextApiRequest & { user: { id: string } }).user;
  let tempFilePath: string | null = null;

  try {
    const { files } = await parseForm(req);

    const fileField = files.file;
    const file = Array.isArray(fileField) ? fileField[0] : fileField;

    if (!file) {
      return apiResponse.badRequest(res, 'No file uploaded. Please select a PDF file.');
    }

    tempFilePath = file.filepath;
    const mimeType = file.mimetype || '';

    if (mimeType !== 'application/pdf') {
      return apiResponse.badRequest(res, `Only PDF files are supported. Received: ${mimeType}`);
    }

    if (file.size > MAX_FILE_SIZE) {
      return apiResponse.badRequest(res, `File too large. Maximum size: ${MAX_FILE_SIZE / (1024 * 1024)}MB`);
    }

    // Validate PDF magic bytes
    const buffer = await fs.promises.readFile(file.filepath);
    const hex = buffer.subarray(0, 4).toString('hex').toUpperCase();
    if (!hex.startsWith('25504446')) {
      return apiResponse.badRequest(res, 'File does not appear to be a valid PDF');
    }

    log.info('Starting document capture extraction', {
      fileName: file.originalFilename,
      fileSize: file.size,
    }, 'document-capture');

    // Extract data from PDF
    const extracted = await extractFromPdf(buffer);

    // Save to database
    const fileName = file.originalFilename || `capture_${Date.now()}.pdf`;

    const [row] = await sql`
      INSERT INTO captured_documents (
        file_name, file_type, file_size, document_type,
        extracted_data, vendor_name, document_date, reference_number,
        total_amount, vat_amount, status, uploaded_by
      ) VALUES (
        ${fileName},
        'pdf',
        ${file.size},
        ${extracted.documentType},
        ${JSON.stringify(extracted)}::jsonb,
        ${extracted.vendorName},
        ${extracted.date ? extracted.date : null}::date,
        ${extracted.referenceNumber},
        ${extracted.totalAmount},
        ${extracted.vatAmount},
        'pending',
        ${user?.id || null}::uuid
      )
      RETURNING *
    ` as Record<string, unknown>[];

    log.info('Document captured successfully', {
      id: row?.id,
      confidence: extracted.confidence,
      documentType: extracted.documentType,
    }, 'document-capture');

    return apiResponse.created(res, {
      document: mapRow(row as Record<string, unknown>),
      extracted,
    });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    log.error('Document capture failed', { error: msg }, 'document-capture');

    if (msg.includes('maxFileSize')) {
      return apiResponse.badRequest(res, `File too large. Maximum size: ${MAX_FILE_SIZE / (1024 * 1024)}MB`);
    }

    return apiResponse.internalError(res, err, `Document capture failed: ${msg}`);
  } finally {
    if (tempFilePath) {
      await fs.promises.unlink(tempFilePath).catch((e) =>
        log.debug('Temp file cleanup failed', { error: e instanceof Error ? e.message : 'unknown' }, 'document-capture')
      );
    }
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Document Capture Action API
 * POST /api/accounting/document-capture-action
 *   { id, action: 'confirm' | 'match_bank_tx' | 'reject', data?: {...} }
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import type { CapturedDocumentAction, CapturedDocument } from '@/modules/accounting/types/documentCapture.types';

function mapRow(row: Record<string, unknown>): CapturedDocument {
  return {
    id: row.id as string,
    fileName: row.file_name as string,
    fileType: row.file_type as string,
    fileSize: row.file_size as number | null,
    documentType: row.document_type as string | null,
    extractedData: row.extracted_data ? (typeof row.extracted_data === 'string' ? JSON.parse(row.extracted_data as string) : row.extracted_data) : null,
    vendorName: row.vendor_name as string | null,
    documentDate: row.document_date ? new Date(row.document_date as string).toISOString().split('T')[0]! : null,
    referenceNumber: row.reference_number as string | null,
    totalAmount: row.total_amount !== null && row.total_amount !== undefined ? parseFloat(String(row.total_amount)) : null,
    vatAmount: row.vat_amount !== null && row.vat_amount !== undefined ? parseFloat(String(row.vat_amount)) : null,
    status: (row.status as CapturedDocument['status']) || 'pending',
    matchedInvoiceId: row.matched_invoice_id as string | null,
    matchedBankTxId: row.matched_bank_tx_id as string | null,
    notes: row.notes as string | null,
    uploadedBy: row.uploaded_by as string | null,
    createdAt: new Date(row.created_at as string).toISOString(),
  };
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  const { id, action, data } = req.body as {
    id: string;
    action: CapturedDocumentAction;
    data?: Record<string, unknown>;
  };

  if (!id || !action) {
    return apiResponse.badRequest(res, 'Missing required fields: id, action');
  }

  if (!['confirm', 'match_bank_tx', 'reject'].includes(action)) {
    return apiResponse.badRequest(res, 'Invalid action. Allowed: confirm, match_bank_tx, reject');
  }

  // Verify document exists
  const [existing] = await sql`
    SELECT * FROM captured_documents WHERE id = ${id}::uuid
  ` as Record<string, unknown>[];

  if (!existing) {
    return apiResponse.notFound(res, 'Captured document', id);
  }

  try {
    if (action === 'confirm') {
      return handleConfirm(res, id, data);
    }

    if (action === 'match_bank_tx') {
      return handleMatchBankTx(res, id, data);
    }

    if (action === 'reject') {
      return handleReject(res, id, data);
    }

    return apiResponse.badRequest(res, 'Unknown action');
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    log.error('Document capture action failed', { error: msg, action, id }, 'document-capture');
    return apiResponse.internalError(res, err, `Action failed: ${msg}`);
  }
}

/** Confirm — mark as reviewed, optionally update extracted fields */
async function handleConfirm(
  res: NextApiResponse,
  id: string,
  data?: Record<string, unknown>,
) {
  const updates: Record<string, unknown> = {};
  if (data?.vendorName !== undefined) updates.vendor_name = data.vendorName;
  if (data?.documentDate !== undefined) updates.document_date = data.documentDate;
  if (data?.referenceNumber !== undefined) updates.reference_number = data.referenceNumber;
  if (data?.totalAmount !== undefined) updates.total_amount = data.totalAmount;
  if (data?.vatAmount !== undefined) updates.vat_amount = data.vatAmount;
  if (data?.documentType !== undefined) updates.document_type = data.documentType;
  if (data?.notes !== undefined) updates.notes = data.notes;

  const [row] = await sql`
    UPDATE captured_documents
    SET status = 'reviewed',
        vendor_name = COALESCE(${(updates.vendor_name as string) || null}, vendor_name),
        document_date = COALESCE(${(updates.document_date as string) || null}::date, document_date),
        reference_number = COALESCE(${(updates.reference_number as string) || null}, reference_number),
        total_amount = COALESCE(${updates.total_amount !== undefined ? Number(updates.total_amount) : null}::numeric, total_amount),
        vat_amount = COALESCE(${updates.vat_amount !== undefined ? Number(updates.vat_amount) : null}::numeric, vat_amount),
        document_type = COALESCE(${(updates.document_type as string) || null}, document_type),
        notes = COALESCE(${(updates.notes as string) || null}, notes)
    WHERE id = ${id}::uuid
    RETURNING *
  ` as Record<string, unknown>[];

  log.info('Document confirmed', { id }, 'document-capture');
  return apiResponse.success(res, mapRow(row as Record<string, unknown>), 'Document confirmed');
}

/** Match to bank transaction */
async function handleMatchBankTx(
  res: NextApiResponse,
  id: string,
  data?: Record<string, unknown>,
) {
  const bankTxId = data?.bankTxId as string;
  if (!bankTxId) {
    return apiResponse.badRequest(res, 'bankTxId is required for match_bank_tx action');
  }

  // Verify bank transaction exists
  const [bankTx] = await sql`
    SELECT id FROM bank_transactions WHERE id = ${bankTxId}::uuid
  ` as Record<string, unknown>[];

  if (!bankTx) {
    return apiResponse.notFound(res, 'Bank transaction', bankTxId);
  }

  const [row] = await sql`
    UPDATE captured_documents
    SET status = 'matched',
        matched_bank_tx_id = ${bankTxId}::uuid
    WHERE id = ${id}::uuid
    RETURNING *
  ` as Record<string, unknown>[];

  log.info('Document matched to bank transaction', { id, bankTxId }, 'document-capture');
  return apiResponse.success(res, mapRow(row as Record<string, unknown>), 'Document matched to bank transaction');
}

/** Reject — mark as rejected */
async function handleReject(
  res: NextApiResponse,
  id: string,
  data?: Record<string, unknown>,
) {
  const notes = (data?.notes as string) || null;

  const [row] = await sql`
    UPDATE captured_documents
    SET status = 'rejected',
        notes = COALESCE(${notes}, notes)
    WHERE id = ${id}::uuid
    RETURNING *
  ` as Record<string, unknown>[];

  log.info('Document rejected', { id }, 'document-capture');
  return apiResponse.success(res, mapRow(row as Record<string, unknown>), 'Document rejected');
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Accounting Documents API
 * GET  /api/accounting/documents?entity_type=...&entity_id=...  — List documents (direct + cross-linked)
 * POST /api/accounting/documents  (multipart form-data)          — Upload document
 * DELETE /api/accounting/documents?id=...                        — Soft-delete document
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import formidable from 'formidable';
import fs from 'fs';
import { vfStorage } from '@/services/vfStorageAdapter';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import type {
  ProcurementDocument,
  LinkedDocument,
  AccountingEntityType,
  AccountingDocumentType,
} from '@/types/procurement/document.types';

export const config = {
  api: { bodyParser: false },
};

const VALID_ENTITY_TYPES: AccountingEntityType[] = [
  'supplier_invoice',
  'supplier_payment',
  'customer_invoice',
  'customer_payment',
  'credit_note',
];

const VALID_DOCUMENT_TYPES: AccountingDocumentType[] = [
  'proof_of_payment',
  'bank_statement',
  'remittance_advice',
  'credit_note_doc',
  'invoice',
  'receipt',
  'other',
];

const ALLOWED_MIME_TYPES = [
  'application/pdf',
  'image/jpeg',
  'image/png',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
];

const MAX_FILE_SIZE = 20 * 1024 * 1024; // 20MB

function validateMagicBytes(buffer: Buffer): boolean {
  if (buffer.length < 4) return false;
  const hex = buffer.subarray(0, 8).toString('hex').toUpperCase();
  if (hex.startsWith('FFD8FF')) return true;   // JPEG
  if (hex.startsWith('89504E47')) return true;  // PNG
  if (hex.startsWith('25504446')) return true;  // PDF
  if (hex.startsWith('504B0304')) return true;  // ZIP (docx/xlsx)
  return false;
}

function parseForm(req: NextApiRequest): Promise<{ fields: formidable.Fields; files: formidable.Files }> {
  return new Promise((resolve, reject) => {
    const form = formidable({ maxFileSize: MAX_FILE_SIZE, keepExtensions: true });
    form.parse(req, (err, fields, files) => {
      if (err) reject(err);
      else resolve({ fields, files });
    });
  });
}

function mapRow(row: Record<string, unknown>, source: 'direct' | 'linked' = 'direct', linkReason?: string): LinkedDocument {
  return {
    id: row.id as string,
    entityType: row.entity_type as string,
    entityId: row.entity_id as string,
    documentType: row.document_type as AccountingDocumentType,
    documentName: row.document_name as string,
    fileUrl: row.file_url as string,
    filePath: (row.file_path as string) || undefined,
    fileSize: (row.file_size as number) || undefined,
    mimeType: (row.mime_type as string) || undefined,
    uploadedBy: row.uploaded_by as string,
    uploadedByName: (row.uploaded_by_name as string) || undefined,
    uploadedAt: new Date(row.uploaded_at as string).toISOString(),
    notes: (row.notes as string) || undefined,
    isActive: row.is_active as boolean,
    source,
    linkReason,
  };
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const user = (req as NextApiRequest & { user: { id: string; name: string; email: string } }).user;

  if (req.method === 'GET') return handleGet(req, res);
  if (req.method === 'POST') return handlePost(req, res, user);
  if (req.method === 'DELETE') return handleDelete(req, res);

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'DELETE']);
}

/** GET — List direct + cross-linked documents for an accounting entity */
async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const entityType = req.query.entity_type as string;
  const entityId = req.query.entity_id as string;

  if (!entityType || !entityId) {
    return apiResponse.badRequest(res, 'Missing required query params: entity_type, entity_id');
  }

  if (!VALID_ENTITY_TYPES.includes(entityType as AccountingEntityType)) {
    return apiResponse.badRequest(res, `Invalid entity_type. Allowed: ${VALID_ENTITY_TYPES.join(', ')}`);
  }

  // Direct documents
  const directRows = await sql`
    SELECT * FROM procurement_documents
    WHERE entity_type = ${entityType}
      AND entity_id = ${entityId}::uuid
      AND is_active = true
    ORDER BY uploaded_at DESC
  `;

  // Cross-linked documents (via document_links)
  const linkedRows = await sql`
    SELECT pd.*, dl.link_reason
    FROM document_links dl
    JOIN procurement_documents pd ON pd.id = dl.document_id
    WHERE dl.linked_entity_type = ${entityType}
      AND dl.linked_entity_id = ${entityId}::uuid
      AND pd.is_active = true
    ORDER BY pd.uploaded_at DESC
  `;

  const results: LinkedDocument[] = [
    ...directRows.map(r => mapRow(r as Record<string, unknown>, 'direct')),
    ...linkedRows.map(r => mapRow(r as Record<string, unknown>, 'linked', (r as Record<string, unknown>).link_reason as string)),
  ];

  return apiResponse.success(res, results);
}

/** POST — Upload a document to an accounting entity */
async function handlePost(
  req: NextApiRequest,
  res: NextApiResponse,
  user: { id: string; name: string; email: string }
) {
  let tempFilePath: string | null = null;

  try {
    const { fields, files } = await parseForm(req);

    const entityType = (Array.isArray(fields.entity_type) ? fields.entity_type[0] : fields.entity_type) as string;
    const entityId = (Array.isArray(fields.entity_id) ? fields.entity_id[0] : fields.entity_id) as string;
    const documentType = ((Array.isArray(fields.document_type) ? fields.document_type[0] : fields.document_type) || 'other') as string;
    const notes = (Array.isArray(fields.notes) ? fields.notes[0] : fields.notes) as string | undefined;

    if (!entityType || !entityId) {
      return apiResponse.badRequest(res, 'Missing required fields: entity_type, entity_id');
    }
    if (!VALID_ENTITY_TYPES.includes(entityType as AccountingEntityType)) {
      return apiResponse.badRequest(res, `Invalid entity_type. Allowed: ${VALID_ENTITY_TYPES.join(', ')}`);
    }
    if (!VALID_DOCUMENT_TYPES.includes(documentType as AccountingDocumentType)) {
      return apiResponse.badRequest(res, `Invalid document_type. Allowed: ${VALID_DOCUMENT_TYPES.join(', ')}`);
    }

    const fileField = files.file;
    const file = Array.isArray(fileField) ? fileField[0] : fileField;
    if (!file) {
      return apiResponse.badRequest(res, 'No file uploaded');
    }

    tempFilePath = file.filepath;

    if (!ALLOWED_MIME_TYPES.includes(file.mimetype || '')) {
      return apiResponse.badRequest(res, `File type not allowed: ${file.mimetype}. Allowed: PDF, JPEG, PNG, DOCX, XLSX`);
    }
    if (file.size > MAX_FILE_SIZE) {
      return apiResponse.badRequest(res, 'File too large. Maximum size: 20MB');
    }

    const buffer = await fs.promises.readFile(file.filepath);
    if (!validateMagicBytes(buffer)) {
      return apiResponse.badRequest(res, 'File content does not match declared type');
    }

    // Upload to VF Storage: accounting/{entity_type}/{entityId}_{filename}
    const fileName = file.originalFilename || `document_${Date.now()}`;
    const storageName = `${entityId}_${fileName}`;
    const result = await vfStorage.uploadFile(buffer, 'accounting', entityType, storageName);

    // Insert DB record
    const [row] = await sql`
      INSERT INTO procurement_documents (
        entity_type, entity_id, document_type, document_name,
        file_url, file_path, file_size, mime_type,
        uploaded_by, uploaded_by_name, notes
      ) VALUES (
        ${entityType}, ${entityId}::uuid, ${documentType}, ${fileName},
        ${result.url}, ${result.path}, ${file.size}, ${file.mimetype || ''},
        ${user.email}, ${user.name}, ${notes || null}
      )
      RETURNING *
    `;

    const docId = (row as Record<string, unknown>).id as string;

    // Auto-link: if supplier_invoice, create cross-links to PO/GRN
    if (entityType === 'supplier_invoice') {
      await autoLinkSupplierInvoice(docId, entityId);
    }

    log.info('Accounting document uploaded', {
      data: { entityType, entityId, documentType, fileName },
    }, 'accounting-docs');

    return apiResponse.created(res, mapRow(row as Record<string, unknown>, 'direct'));
  } catch (error) {
    const errMsg = error instanceof Error ? error.message : String(error);
    log.error('Accounting document upload error', { error }, 'accounting-docs');
    return apiResponse.internalError(res, error, `Failed to upload document: ${errMsg}`);
  } finally {
    if (tempFilePath) {
      await fs.promises.unlink(tempFilePath).catch((e) =>
        log.debug('Temp file cleanup failed', { error: e instanceof Error ? e.message : 'unknown' }, 'accounting')
      );
    }
  }
}

/**
 * Auto-link a newly uploaded supplier_invoice doc to related PO/GRN,
 * and create reverse links so existing PO/GRN docs appear on the invoice.
 */
async function autoLinkSupplierInvoice(docId: string, invoiceId: string) {
  try {
    // Look up FK references on the invoice
    const [invoice] = await sql`
      SELECT purchase_order_id, grn_id
      FROM sage_supplier_invoices
      WHERE id = ${invoiceId}::uuid
    `;

    if (!invoice) return;

    const poId = invoice.purchase_order_id as string | null;
    const grnId = invoice.grn_id as string | null;

    // Forward links: this doc -> PO/GRN
    if (poId) {
      await sql`
        INSERT INTO document_links (document_id, linked_entity_type, linked_entity_id, link_reason)
        VALUES (${docId}::uuid, 'purchase_order', ${poId}::uuid, 'po_invoice_link')
        ON CONFLICT (document_id, linked_entity_type, linked_entity_id) DO NOTHING
      `;
    }
    if (grnId) {
      await sql`
        INSERT INTO document_links (document_id, linked_entity_type, linked_entity_id, link_reason)
        VALUES (${docId}::uuid, 'goods_receipt_note', ${grnId}::uuid, 'grn_invoice_link')
        ON CONFLICT (document_id, linked_entity_type, linked_entity_id) DO NOTHING
      `;
    }

    // Reverse links: existing PO/GRN docs -> this invoice
    if (poId) {
      const poDocs = await sql`
        SELECT id FROM procurement_documents
        WHERE entity_type = 'purchase_order' AND entity_id = ${poId}::uuid AND is_active = true
      `;
      for (const doc of poDocs) {
        await sql`
          INSERT INTO document_links (document_id, linked_entity_type, linked_entity_id, link_reason)
          VALUES (${(doc as Record<string, unknown>).id as string}::uuid, 'supplier_invoice', ${invoiceId}::uuid, 'po_invoice_link')
          ON CONFLICT (document_id, linked_entity_type, linked_entity_id) DO NOTHING
        `;
      }
    }
    if (grnId) {
      const grnDocs = await sql`
        SELECT id FROM procurement_documents
        WHERE entity_type = 'goods_receipt_note' AND entity_id = ${grnId}::uuid AND is_active = true
      `;
      for (const doc of grnDocs) {
        await sql`
          INSERT INTO document_links (document_id, linked_entity_type, linked_entity_id, link_reason)
          VALUES (${(doc as Record<string, unknown>).id as string}::uuid, 'supplier_invoice', ${invoiceId}::uuid, 'grn_invoice_link')
          ON CONFLICT (document_id, linked_entity_type, linked_entity_id) DO NOTHING
        `;
      }
    }
  } catch (err) {
    log.warn('Auto-link supplier invoice docs failed (non-fatal)', { error: err }, 'accounting-docs');
  }
}

/** DELETE — Soft-delete a document */
async function handleDelete(req: NextApiRequest, res: NextApiResponse) {
  const id = req.query.id as string;
  if (!id) {
    return apiResponse.badRequest(res, 'Missing required query param: id');
  }

  const [row] = await sql`
    UPDATE procurement_documents
    SET is_active = false
    WHERE id = ${id}::uuid AND is_active = true
    RETURNING id
  `;

  if (!row) {
    return apiResponse.notFound(res, 'Document', id);
  }

  log.info('Accounting document soft-deleted', { data: { id } }, 'accounting-docs');
  return apiResponse.success(res, { id: row.id, deleted: true });
}

export default withCompany(handler);

/**
 * Item Adjustments API
 * GET  — list stock items with current quantities
 * POST — create stock adjustment (increase/decrease)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const rows = await sql`
        SELECT id, item_code, name AS item_name, uom, category,
          qty_available AS current_quantity, standard_cost
        FROM stock_items WHERE is_active = true ORDER BY name
      `;
      return apiResponse.success(res, rows);
    } catch (err) {
      log.error('Failed to fetch items for adjustments', { error: err });
      return apiResponse.badRequest(res, 'Failed to fetch items');
    }
  }

  if (req.method === 'POST') {
    try {
      const { itemId, adjustmentType, quantity, reason, date } = req.body as {
        itemId?: string;
        adjustmentType?: 'increase' | 'decrease';
        quantity?: number;
        reason?: string;
        date?: string;
      };

      if (!itemId) return apiResponse.badRequest(res, 'itemId is required');
      if (!adjustmentType || !['increase', 'decrease'].includes(adjustmentType)) {
        return apiResponse.badRequest(res, 'adjustmentType must be increase or decrease');
      }
      if (!quantity || Number(quantity) <= 0) return apiResponse.badRequest(res, 'quantity must be positive');
      if (!reason) return apiResponse.badRequest(res, 'reason is required');

      const [item] = await sql`
        SELECT id, name, qty_available FROM stock_items WHERE id = ${itemId}
      `;
      if (!item) return apiResponse.notFound(res, 'Stock item', itemId);

      const currentQty = Number(item.qty_available || 0);
      const qty = Number(quantity);
      const newQty = adjustmentType === 'increase' ? currentQty + qty : currentQty - qty;

      if (newQty < 0) {
        return apiResponse.badRequest(res, `Cannot decrease by ${qty} — current qty is ${currentQty}`);
      }

      await sql`UPDATE stock_items SET qty_available = ${newQty} WHERE id = ${itemId}`;

      log.info('Stock item adjusted', { itemId, adjustmentType, quantity: qty, newQty });

      return apiResponse.success(res, {
        itemId,
        adjustmentType,
        quantity: qty,
        previousQuantity: currentQty,
        newQuantity: newQty,
      });
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Adjustment failed';
      log.error('Item adjustment failed', { error: err });
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withCompany(handler);

/**
 * Item Opening Balances API
 * GET  — list active stock items with current qty and cost
 * POST — set opening balances (quantity + unit cost)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const rows = await sql`
        SELECT id, item_code, name, category, uom, qty_available, standard_cost, list_price
        FROM stock_items WHERE is_active = true ORDER BY name
      `;
      return apiResponse.success(res, rows);
    } catch (err) {
      log.error('Failed to fetch items for opening balances', { error: err });
      return apiResponse.badRequest(res, 'Failed to fetch items');
    }
  }

  if (req.method === 'POST') {
    try {
      const { items } = req.body as {
        items?: { itemId: string; quantity: number; unitCost: number }[];
      };

      if (!items || !Array.isArray(items) || items.length === 0) {
        return apiResponse.badRequest(res, 'items array is required');
      }

      for (const entry of items) {
        if (!entry.itemId || entry.quantity == null || entry.unitCost == null) {
          return apiResponse.badRequest(res, 'Each entry needs itemId, quantity, and unitCost');
        }
      }

      for (const entry of items) {
        await sql`
          UPDATE stock_items
          SET qty_available = ${Number(entry.quantity)},
              standard_cost = ${Number(entry.unitCost)}
          WHERE id = ${entry.itemId}
        `;
      }

      log.info('Item opening balances set', { count: items.length });
      return apiResponse.success(res, { updated: items.length });
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to set opening balances';
      log.error('Item opening balances failed', { error: err });
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withCompany(handler);

/**
 * Item Pricing API
 * GET — list active stock items with prices
 * PUT — bulk update selling prices
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const rows = await sql`
        SELECT id, item_code, name, category, uom, list_price, standard_cost, qty_available
        FROM stock_items WHERE is_active = true ORDER BY name
      `;
      return apiResponse.success(res, rows);
    } catch (err) {
      log.error('Failed to fetch item pricing', { error: err });
      return apiResponse.badRequest(res, 'Failed to fetch item pricing');
    }
  }

  if (req.method === 'PUT') {
    try {
      const { updates } = req.body as {
        updates?: { itemId: string; sellingPrice: number }[];
      };

      if (!updates || !Array.isArray(updates) || updates.length === 0) {
        return apiResponse.badRequest(res, 'updates array is required');
      }

      for (const u of updates) {
        if (!u.itemId || u.sellingPrice == null || Number(u.sellingPrice) < 0) {
          return apiResponse.badRequest(res, 'Each entry needs itemId and non-negative sellingPrice');
        }
      }

      for (const u of updates) {
        await sql`UPDATE stock_items SET list_price = ${Number(u.sellingPrice)} WHERE id = ${u.itemId}`;
      }

      log.info('Selling prices updated', { count: updates.length });
      return apiResponse.success(res, { updated: updates.length });
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to update prices';
      log.error('Item pricing update failed', { error: err });
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PUT']);
}

