/**
 * Year-End Export API
 * GET — export fiscal year summaries as CSV
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';

function csvCell(v: string): string { return `"${String(v || '').replace(/"/g, '""')}"`; }

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  try {
    const rows = await sql`
      SELECT fiscal_year, MIN(start_date) AS start_date, MAX(end_date) AS end_date,
        CASE WHEN COUNT(*) FILTER (WHERE status = 'open') > 0 THEN 'open' ELSE 'closed' END AS status
      FROM fiscal_periods
      GROUP BY fiscal_year
      ORDER BY fiscal_year DESC
    `;

    const csvLines = [
      'Year,Start Date,End Date,Status',
      ...rows.map((r: Record<string, unknown>) => [
        csvCell(String(r.fiscal_year)),
        csvCell(String(r.start_date)),
        csvCell(String(r.end_date)),
        csvCell(String(r.status)),
      ].join(',')),
    ];

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="year-end-${new Date().toISOString().split('T')[0]}.csv"`);
    return res.status(200).send(csvLines.join('\n'));
  } catch (err) {
    log.error('Year-end export failed', { error: err });
    return apiResponse.badRequest(res, 'Failed to export year-end data');
  }
}

export default withCompany(handler);

/**
 * Asset Depreciation API
 * POST — run monthly depreciation for all eligible assets
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, withRole, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { postAssetDepreciationToGL } from '@/modules/accounting/services/glCrossModuleHooks';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!, ['POST']);

  const userId = String(req.user.id);

  // Find assets eligible for depreciation:
  // - Status = available or assigned (active assets)
  // - Has purchase_price and useful_life_years
  // - current_book_value > salvage_value
  const assets = (await sql`
    SELECT id, asset_number, name, purchase_price, useful_life_years,
           salvage_value, current_book_value, accumulated_depreciation
    FROM assets
    WHERE status IN ('available', 'assigned', 'in_maintenance')
      AND purchase_price IS NOT NULL
      AND purchase_price > 0
      AND useful_life_years IS NOT NULL
      AND useful_life_years > 0
      AND COALESCE(current_book_value, purchase_price) > COALESCE(salvage_value, 0)
  `) as Row[];

  let processed = 0;
  let skipped = 0;
  const results: { assetNumber: string; amount: number; entryId: string | null }[] = [];

  for (const asset of assets) {
    const purchasePrice = Number(asset.purchase_price);
    const salvageValue = Number(asset.salvage_value || 0);
    const usefulLifeYears = Number(asset.useful_life_years);
    const bookValue = Number(asset.current_book_value ?? purchasePrice);

    // Straight-line monthly depreciation
    const annualDepreciation = (purchasePrice - salvageValue) / usefulLifeYears;
    const monthlyDepreciation = Math.round((annualDepreciation / 12) * 100) / 100;

    // Don't depreciate below salvage value
    const maxDepreciation = Math.max(0, bookValue - salvageValue);
    const amount = Math.min(monthlyDepreciation, maxDepreciation);

    if (amount < 0.01) { skipped++; continue; }

    const entryId = await postAssetDepreciationToGL(String(asset.id), amount, userId);
    results.push({ assetNumber: String(asset.asset_number), amount, entryId });
    processed++;
  }

  log.info('Depreciation run completed', { processed, skipped, total: assets.length }, 'accounting');

  return apiResponse.success(res, {
    processed,
    skipped,
    total: assets.length,
    results,
  });
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withRole('admin')(withErrorHandler(handler as any)));

/**
 * Depreciation Export API
 * GET — export depreciable assets as CSV
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';

function csvCell(v: string): string { return `"${String(v || '').replace(/"/g, '""')}"`; }

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  try {
    const proto = req.headers['x-forwarded-proto'] || 'http';
    const host = req.headers.host || 'localhost:3004';
    const baseUrl = `${proto}://${host}`;
    const assetRes = await fetch(`${baseUrl}/api/assets?status=available,assigned,in_maintenance&limit=500`, {
      headers: { cookie: req.headers.cookie || '' },
    });
    const assetJson = await assetRes.json();
    const assets = (assetJson.data?.items || assetJson.data?.assets || assetJson.data || [])
      .filter((a: Record<string, unknown>) => Number(a.purchase_price) > 0 && Number(a.useful_life_years) > 0);

    const csvLines = [
      'Asset Number,Name,Purchase Price,Book Value,Accum Depreciation,Useful Life (yrs),Salvage Value,Monthly Depreciation',
      ...assets.map((a: Record<string, unknown>) => {
        const pp = Number(a.purchase_price);
        const sv = Number(a.salvage_value || 0);
        const uly = Number(a.useful_life_years);
        const monthly = Math.round(((pp - sv) / uly / 12) * 100) / 100;
        return [
          csvCell(String(a.asset_number)),
          csvCell(String(a.name)),
          pp.toFixed(2),
          Number(a.current_book_value ?? pp).toFixed(2),
          Number(a.accumulated_depreciation || 0).toFixed(2),
          String(uly),
          sv.toFixed(2),
          monthly.toFixed(2),
        ].join(',');
      }),
    ];

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="depreciation-${new Date().toISOString().split('T')[0]}.csv"`);
    return res.status(200).send(csvLines.join('\n'));
  } catch (err) {
    log.error('Depreciation export failed', { error: err });
    return apiResponse.badRequest(res, 'Failed to export depreciation data');
  }
}

export default withCompany(handler);

/**
