/**
 * DRC VAT Export API
 * GET — export DRC VAT history as CSV
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';

function csvCell(v: string): string { return `"${String(v || '').replace(/"/g, '""')}"`; }

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  try {
    // Load VAT rate from settings (default 15%)
    let vatRate = 0.15;
    try {
      const settingRows = await sql`SELECT value FROM app_settings WHERE key = 'vat_rate'`;
      if (settingRows[0]?.value) {
        const rate = Number(settingRows[0].value);
        if (rate > 0 && rate < 1) vatRate = rate;
      }
    } catch { /* use default */ }

    const rows = await sql`
      SELECT si.invoice_number, s.company_name AS supplier_name,
        si.total_amount, si.invoice_date,
        COALESCE(si.total_amount * ${vatRate}, 0) AS vat_amount
      FROM supplier_invoices si
      JOIN suppliers s ON s.id = si.supplier_id
      WHERE si.is_drc = true
      ORDER BY si.invoice_date DESC
    `;

    const csvLines = [
      'Invoice,Supplier,Date,Amount (excl),VAT (15%)',
      ...rows.map((r: Record<string, unknown>) => [
        csvCell(String(r.invoice_number)),
        csvCell(String(r.supplier_name)),
        csvCell(String(r.invoice_date)),
        Number(r.total_amount || 0).toFixed(2),
        Number(r.vat_amount || 0).toFixed(2),
      ].join(',')),
    ];

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="drc-vat-${new Date().toISOString().split('T')[0]}.csv"`);
    return res.status(200).send(csvLines.join('\n'));
  } catch (err) {
    log.error('DRC VAT export failed', { error: err });
    return apiResponse.badRequest(res, 'Failed to export DRC VAT data');
  }
}

export default withCompany(handler);

/**
 * VAT Adjustments API
 * GET  — list VAT adjustments
 * POST — create VAT adjustment
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getVATAdjustments,
  createVATAdjustment,
} from '@/modules/accounting/services/vatAdjustmentService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    const { status, limit, offset } = req.query;
    const result = await getVATAdjustments({
      status: status as string,
      limit: limit ? Number(limit) : undefined,
      offset: offset ? Number(offset) : undefined,
    });
    return apiResponse.success(res, result);
  }

  if (req.method === 'POST') {
    const userId = req.user.id;
    try {
      const item = await createVATAdjustment(req.body, userId);
      return apiResponse.success(res, item);
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Create failed';
      log.error('VAT adjustment create failed', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, msg);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * VAT Adjustment Actions API
 * POST — approve, cancel
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  approveVATAdjustment,
  cancelVATAdjustment,
} from '@/modules/accounting/services/vatAdjustmentService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  try {
    const { action, id } = req.body;
    const userId = req.user.id;
    if (!action || !id) return apiResponse.badRequest(res, 'action and id are required');

    switch (action) {
      case 'approve': {
        const item = await approveVATAdjustment(id, userId);
        return apiResponse.success(res, item);
      }
      case 'cancel':
        await cancelVATAdjustment(id);
        return apiResponse.success(res, { status: 'cancelled' });
      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : 'Action failed';
    log.error('VAT adjustment action failed', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, msg);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

