/**
 * Item Listing Report API
 * GET: Master list of all stock items with details
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

export default withAuth(async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);

  try {
    const category = req.query.category as string | undefined;
    const search = req.query.search as string | undefined;
    const format = req.query.format as string;

    let rows;
    if (category && search) {
      const like = `%${search}%`;
      rows = await sql`
        SELECT id, item_code, name, description, category, uom,
          list_price, standard_cost, qty_available, is_active
        FROM stock_items
        WHERE category = ${category} AND (name ILIKE ${like} OR item_code ILIKE ${like})
        ORDER BY name
      `;
    } else if (category) {
      rows = await sql`
        SELECT id, item_code, name, description, category, uom,
          list_price, standard_cost, qty_available, is_active
        FROM stock_items WHERE category = ${category}
        ORDER BY name
      `;
    } else if (search) {
      const like = `%${search}%`;
      rows = await sql`
        SELECT id, item_code, name, description, category, uom,
          list_price, standard_cost, qty_available, is_active
        FROM stock_items WHERE name ILIKE ${like} OR item_code ILIKE ${like}
        ORDER BY name
      `;
    } else {
      rows = await sql`
        SELECT id, item_code, name, description, category, uom,
          list_price, standard_cost, qty_available, is_active
        FROM stock_items ORDER BY name
      `;
    }

    const data = rows.map(r => ({
      id: r.id,
      itemCode: r.item_code || '',
      name: r.name,
      description: r.description || '',
      category: r.category || 'uncategorized',
      uom: r.uom || '',
      sellingPrice: Number(r.list_price || 0),
      costPrice: Number(r.standard_cost || 0),
      qtyOnHand: Number(r.qty_available || 0),
      isActive: r.is_active,
    }));

    if (format === 'csv') {
      const header = 'Item Code,Name,Description,Category,UOM,Selling Price,Cost Price,Qty On Hand,Active';
      const csvRows = data.map(r =>
        `"${r.itemCode}","${r.name}","${r.description}","${r.category}","${r.uom}",${r.sellingPrice.toFixed(2)},${r.costPrice.toFixed(2)},${r.qtyOnHand},${r.isActive}`
      );
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', 'attachment; filename="item-listing.csv"');
      return res.send([header, ...csvRows].join('\n'));
    }

    return apiResponse.success(res, data);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    log.error('Item listing report error', { error: message });
    return apiResponse.badRequest(res, 'Failed to generate item listing');
  }
});

/**
 * Item Movement Report API
 * GET: Stock movement log (in/out/adjustments) per item with running balance
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

export default withAuth(async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);

  try {
    const from = (req.query.from as string) || new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0];
    const to = (req.query.to as string) || new Date().toISOString().split('T')[0];
    const itemId = req.query.item_id as string | undefined;
    const format = req.query.format as string;

    // Get GRN (goods received) as stock IN
    let grnRows;
    if (itemId) {
      grnRows = await sql`
        SELECT g.delivery_date AS move_date, 'GRN' AS move_type,
          g.grn_number AS reference, si.name AS item_name, si.item_code,
          gi.quantity_received AS qty_in, 0 AS qty_out
        FROM goods_receipt_items gi
        JOIN goods_receipt_notes g ON g.id = gi.grn_id
        JOIN stock_items si ON si.id = gi.stock_item_id
        WHERE gi.stock_item_id = ${itemId}
          AND g.delivery_date >= ${from} AND g.delivery_date <= ${to}
      `;
    } else {
      grnRows = await sql`
        SELECT g.delivery_date AS move_date, 'GRN' AS move_type,
          g.grn_number AS reference, si.name AS item_name, si.item_code,
          gi.quantity_received AS qty_in, 0 AS qty_out
        FROM goods_receipt_items gi
        JOIN goods_receipt_notes g ON g.id = gi.grn_id
        JOIN stock_items si ON si.id = gi.stock_item_id
        WHERE g.delivery_date IS NOT NULL
          AND g.delivery_date >= ${from} AND g.delivery_date <= ${to}
      `;
    }

    // No sales rows — customer_invoice_items don't link to stock_items
    const salesRows: typeof grnRows = [];

    // Merge and sort by date
    const allMoves = [...grnRows, ...salesRows].sort((a, b) =>
      new Date(a.move_date).getTime() - new Date(b.move_date).getTime()
    );

    let runningBalance = 0;
    const data = allMoves.map(r => {
      const qtyIn = Number(r.qty_in || 0);
      const qtyOut = Number(r.qty_out || 0);
      runningBalance += qtyIn - qtyOut;
      return {
        date: r.move_date instanceof Date ? r.move_date.toISOString().split('T')[0] : String(r.move_date || '').split('T')[0],
        type: r.move_type,
        reference: r.reference || '',
        itemName: r.item_name,
        itemCode: r.item_code || '',
        qtyIn,
        qtyOut,
        balance: runningBalance,
      };
    });

    if (format === 'csv') {
      const header = 'Date,Type,Reference,Item Code,Item,Qty In,Qty Out,Balance';
      const csvRows = data.map(r =>
        `${r.date},"${r.type}","${r.reference}","${r.itemCode}","${r.itemName}",${r.qtyIn},${r.qtyOut},${r.balance}`
      );
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', `attachment; filename="item-movement-${from}-${to}.csv"`);
      return res.send([header, ...csvRows].join('\n'));
    }

    return apiResponse.success(res, data);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    log.error('Item movement report error', { error: message });
    return apiResponse.badRequest(res, 'Failed to generate report');
  }
});

/**
 * Item Quantities Report API
 * GET: Current on-hand quantities per item with min stock alerts
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

export default withAuth(async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);

  try {
    const format = req.query.format as string;
    const lowStockOnly = req.query.low_stock === 'true';

    const rows = await sql`
      SELECT id, item_code, name, category, uom, qty_available,
        COALESCE(min_stock_level, 0) AS min_stock_level
      FROM stock_items
      WHERE is_active = true
      ORDER BY name
    `;

    let data = rows.map(r => ({
      id: r.id,
      itemCode: r.item_code || '',
      name: r.name,
      category: r.category || 'uncategorized',
      uom: r.uom || '',
      qtyOnHand: Number(r.qty_available || 0),
      minLevel: Number(r.min_stock_level || 0),
      lowStock: Number(r.min_stock_level || 0) > 0 && Number(r.qty_available || 0) <= Number(r.min_stock_level || 0),
    }));

    if (lowStockOnly) {
      data = data.filter(r => r.lowStock);
    }

    if (format === 'csv') {
      const header = 'Item Code,Name,Category,UOM,Qty On Hand,Min Level,Low Stock';
      const csvRows = data.map(r =>
        `"${r.itemCode}","${r.name}","${r.category}","${r.uom}",${r.qtyOnHand},${r.minLevel},${r.lowStock ? 'Yes' : 'No'}`
      );
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', 'attachment; filename="item-quantities.csv"');
      return res.send([header, ...csvRows].join('\n'));
    }

    return apiResponse.success(res, data);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    log.error('Item quantities report error', { error: message });
    return apiResponse.badRequest(res, 'Failed to generate report');
  }
});

/**
 * Item Valuation Report API
 * GET: Current stock value (qty x cost) by item, totals by category
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

export default withAuth(async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);

  try {
    const format = req.query.format as string;
    const category = req.query.category as string | undefined;

    let rows;
    if (category) {
      rows = await sql`
        SELECT id, item_code, name, category, uom, qty_available, standard_cost,
          (COALESCE(qty_available, 0) * COALESCE(standard_cost, 0)) AS stock_value
        FROM stock_items
        WHERE is_active = true AND category = ${category}
        ORDER BY stock_value DESC
      `;
    } else {
      rows = await sql`
        SELECT id, item_code, name, category, uom, qty_available, standard_cost,
          (COALESCE(qty_available, 0) * COALESCE(standard_cost, 0)) AS stock_value
        FROM stock_items
        WHERE is_active = true
        ORDER BY stock_value DESC
      `;
    }

    const data = rows.map(r => ({
      id: r.id,
      itemCode: r.item_code || '',
      name: r.name,
      category: r.category || 'uncategorized',
      uom: r.uom || '',
      qtyOnHand: Number(r.qty_available || 0),
      costPrice: Number(r.standard_cost || 0),
      stockValue: Number(r.stock_value || 0),
    }));

    if (format === 'csv') {
      const header = 'Item Code,Name,Category,UOM,Qty On Hand,Unit Cost,Stock Value';
      const csvRows = data.map(r =>
        `"${r.itemCode}","${r.name}","${r.category}","${r.uom}",${r.qtyOnHand},${r.costPrice.toFixed(2)},${r.stockValue.toFixed(2)}`
      );
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', 'attachment; filename="item-valuation.csv"');
      return res.send([header, ...csvRows].join('\n'));
    }

    return apiResponse.success(res, data);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    log.error('Item valuation report error', { error: message });
    return apiResponse.badRequest(res, 'Failed to generate report');
  }
});

/**
 * Purchases by Item Report API
 * GET: Purchase analysis grouped by item for a date range
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

export default withAuth(async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);

  try {
    const from = (req.query.from as string) || new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0];
    const to = (req.query.to as string) || new Date().toISOString().split('T')[0];
    const format = req.query.format as string;

    const rows = await sql`
      SELECT
        si.id, si.item_code, si.name, si.category,
        COUNT(DISTINCT poi.purchase_order_id)::int AS po_count,
        COALESCE(SUM(poi.quantity_ordered), 0)::numeric AS qty_ordered,
        COALESCE(SUM(poi.quantity_ordered * poi.unit_price), 0)::numeric AS total_cost
      FROM purchase_order_items poi
      JOIN purchase_orders po ON po.id = poi.purchase_order_id
      JOIN stock_items si ON si.id = poi.stock_item_id
      WHERE po.order_date >= ${from}
        AND po.order_date <= ${to}
      GROUP BY si.id, si.item_code, si.name, si.category
      ORDER BY total_cost DESC
    `;

    const data = rows.map(r => ({
      id: r.id,
      itemCode: r.item_code || '',
      name: r.name,
      category: r.category || '',
      poCount: Number(r.po_count),
      qtyOrdered: Number(r.qty_ordered),
      totalCost: Number(r.total_cost),
      avgCost: Number(r.qty_ordered) > 0 ? Number(r.total_cost) / Number(r.qty_ordered) : 0,
    }));

    if (format === 'csv') {
      const header = 'Item Code,Name,Category,PO Count,Qty Ordered,Total Cost,Avg Cost';
      const csvRows = data.map(r =>
        `"${r.itemCode}","${r.name}","${r.category}",${r.poCount},${r.qtyOrdered},${r.totalCost.toFixed(2)},${r.avgCost.toFixed(2)}`
      );
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', `attachment; filename="purchases-by-item-${from}-${to}.csv"`);
      return res.send([header, ...csvRows].join('\n'));
    }

    return apiResponse.success(res, data);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    log.error('Purchases by item report error', { error: message });
    return apiResponse.badRequest(res, 'Failed to generate report');
  }
});

/**
 * Purchases by Supplier Report API
 * GET: Returns purchase summary grouped by supplier for a date range
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse, ErrorCode } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

export default withAuth(async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET']);

  try {
    const from = (req.query.from as string) || new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0];
    const to = (req.query.to as string) || new Date().toISOString().split('T')[0];
    const format = req.query.format as string;

    const rows = await sql`
      SELECT
        si.supplier_id,
        s.company_name AS supplier_name,
        COUNT(si.id)::int AS invoice_count,
        COALESCE(SUM(si.total_amount), 0)::numeric AS total_purchases,
        COALESCE(SUM(si.amount_paid), 0)::numeric AS payments_made,
        COALESCE(SUM(si.total_amount - si.amount_paid), 0)::numeric AS outstanding
      FROM supplier_invoices si
      JOIN suppliers s ON s.id = si.supplier_id
      WHERE si.invoice_date >= ${from}
        AND si.invoice_date <= ${to}
        AND si.status != 'cancelled'
      GROUP BY si.supplier_id, s.company_name
      ORDER BY total_purchases DESC
    `;

    const data = rows.map(r => ({
      supplierId: r.supplier_id,
      supplierName: r.supplier_name,
      invoiceCount: Number(r.invoice_count),
      totalPurchases: Number(r.total_purchases),
      paymentsMade: Number(r.payments_made),
