/**
 * SARS Compliance Calendar API
 * GET ?year=YYYY — get compliance calendar with upcoming deadlines
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getComplianceCalendarWithDB } from '@/modules/accounting/services/sarsService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  try {
    const year = req.query.year ? Number(req.query.year) : undefined;
    const events = await getComplianceCalendarWithDB(year);
    return apiResponse.success(res, { events });
  } catch (err) {
    log.error('Failed to get compliance calendar', { error: err }, 'sars-api');
    return apiResponse.badRequest(res, 'Failed to load compliance calendar');
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

/**
 * SARS EMP201 API
 * GET  ?from=YYYY-MM-DD&to=YYYY-MM-DD — generate EMP201 data for period
 * POST { periodStart, periodEnd }     — save as draft submission
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  generateEMP201,
  saveDraftSubmission,
} from '@/modules/accounting/services/sarsService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    const from = req.query.from as string;
    const to = req.query.to as string;

    if (!from || !to) {
      return apiResponse.badRequest(res, 'from and to query parameters are required (YYYY-MM-DD)');
    }

    try {
      const emp201 = await generateEMP201(from, to);
      return apiResponse.success(res, emp201);
    } catch (err) {
      log.error('Failed to generate EMP201', { error: err }, 'sars-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed to generate EMP201');
    }
  }

  if (req.method === 'POST') {
    const { periodStart, periodEnd } = req.body;

    if (!periodStart || !periodEnd) {
      return apiResponse.badRequest(res, 'periodStart and periodEnd are required');
    }

    try {
      const emp201 = await generateEMP201(periodStart, periodEnd);
      const submission = await saveDraftSubmission(
        'EMP201',
        periodStart,
        periodEnd,
        emp201 as unknown as Record<string, unknown>,
        userId
      );
      return apiResponse.created(res, submission, 'EMP201 draft saved');
    } catch (err) {
      log.error('Failed to save EMP201 draft', { error: err }, 'sars-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed to save draft');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

/**
 * SARS Submissions API
 * GET  — list all submissions (optional ?type=VAT201)
 * POST { id, action: 'mark_submitted', reference } — mark as submitted
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  listSubmissions,
  markSubmitted,
  getSubmission,
} from '@/modules/accounting/services/sarsService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const formType = req.query.type as string | undefined;
      const submissions = await listSubmissions(formType);
      return apiResponse.success(res, { items: submissions });
    } catch (err) {
      log.error('Failed to list submissions', { error: err }, 'sars-api');
      return apiResponse.badRequest(res, 'Failed to list submissions');
    }
  }

  if (req.method === 'POST') {
    const { id, action, reference } = req.body;

    if (!id || !action) {
      return apiResponse.badRequest(res, 'id and action are required');
    }

    if (action === 'mark_submitted') {
      if (!reference) {
        return apiResponse.badRequest(res, 'reference is required when marking as submitted');
      }

      try {
        const submission = await markSubmitted(id, reference);
        return apiResponse.success(res, submission, 'Submission marked as submitted');
      } catch (err) {
        log.error('Failed to mark submission', { error: err }, 'sars-api');
        return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed');
      }
    }

    if (action === 'get') {
      try {
        const submission = await getSubmission(id);
        if (!submission) {
          return apiResponse.notFound(res, 'Submission', id);
        }
        return apiResponse.success(res, submission);
      } catch (err) {
        log.error('Failed to get submission', { error: err }, 'sars-api');
        return apiResponse.badRequest(res, 'Failed to retrieve submission');
      }
    }

    return apiResponse.badRequest(res, `Unknown action: ${action}`);
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

/**
 * SARS VAT201 API
 * GET  ?from=YYYY-MM-DD&to=YYYY-MM-DD — generate VAT201 data for period
 * POST { periodStart, periodEnd }     — save as draft submission
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  generateVAT201,
  saveDraftSubmission,
} from '@/modules/accounting/services/sarsService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    const from = req.query.from as string;
    const to = req.query.to as string;

    if (!from || !to) {
      return apiResponse.badRequest(res, 'from and to query parameters are required (YYYY-MM-DD)');
    }

    try {
      const vat201 = await generateVAT201(from, to);
      return apiResponse.success(res, vat201);
    } catch (err) {
      log.error('Failed to generate VAT201', { error: err }, 'sars-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed to generate VAT201');
    }
  }

  if (req.method === 'POST') {
    const { periodStart, periodEnd } = req.body;

    if (!periodStart || !periodEnd) {
      return apiResponse.badRequest(res, 'periodStart and periodEnd are required');
    }

    try {
      const vat201 = await generateVAT201(periodStart, periodEnd);
      const submission = await saveDraftSubmission(
        'VAT201',
        periodStart,
        periodEnd,
        vat201 as unknown as Record<string, unknown>,
        userId
      );
      return apiResponse.created(res, submission, 'VAT201 draft saved');
    } catch (err) {
      log.error('Failed to save VAT201 draft', { error: err }, 'sars-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed to save draft');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

