-- ──────────────────────────────────────────────────────────────────────────────
-- STEP 3: Set NOT NULL constraints
-- ──────────────────────────────────────────────────────────────────────────────

ALTER TABLE gl_accounts ALTER COLUMN company_id SET NOT NULL;
