import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ────────────────────────────────────────────────────────────────────

export interface Company {
  id: string;
  name: string;
  tradingName: string | null;
  registrationNumber: string | null;
  vatNumber: string | null;
  taxNumber: string | null;
  addressLine1: string | null;
  addressLine2: string | null;
  city: string | null;
  province: string | null;
  postalCode: string | null;
  country: string;
  phone: string | null;
  email: string | null;
  website: string | null;
  logoUrl: string | null;
  bankName: string | null;
  bankAccountNumber: string | null;
  bankBranchCode: string | null;
  bankAccountType: string;
  financialYearStart: number;
  vatPeriod: string;
  defaultCurrency: string;
  isActive: boolean;
  createdAt: string;
}

export interface CompanyUser {
  companyId: string;
  companyName: string;
  role: string;
  isDefault: boolean;
}

// ── Company CRUD ─────────────────────────────────────────────────────────────

export async function listCompanies(): Promise<Company[]> {
  const rows = (await sql`SELECT * FROM companies WHERE is_active = true ORDER BY name`) as Row[];
  return rows.map(mapCompany);
}

export async function getCompany(id: string): Promise<Company | null> {
  const rows = (await sql`SELECT * FROM companies WHERE id = ${id}::UUID`) as Row[];
  return rows[0] ? mapCompany(rows[0]) : null;
}

export async function createCompany(input: {
  name: string;
  tradingName?: string;
  registrationNumber?: string;
  vatNumber?: string;
  taxNumber?: string;
  email?: string;
  phone?: string;
}, userId: string): Promise<Company> {
  const rows = (await sql`
    INSERT INTO companies (name, trading_name, registration_number, vat_number, tax_number, email, phone)
    VALUES (${input.name}, ${input.tradingName || null}, ${input.registrationNumber || null},
            ${input.vatNumber || null}, ${input.taxNumber || null}, ${input.email || null}, ${input.phone || null})
    RETURNING *
  `) as Row[];

  // Auto-assign creator as owner
  await sql`
    INSERT INTO company_users (company_id, user_id, role, is_default)
    VALUES (${rows[0].id}::UUID, ${userId}::UUID, 'owner', false)
  `;

  log.info('Company created', { id: rows[0].id, name: input.name }, 'accounting');
  return mapCompany(rows[0]);
}

export async function updateCompany(id: string, input: Partial<{
  name: string;
  tradingName: string;
  registrationNumber: string;
  vatNumber: string;
  taxNumber: string;
  addressLine1: string;
  addressLine2: string;
  city: string;
  province: string;
  postalCode: string;
  phone: string;
  email: string;
  website: string;
  bankName: string;
  bankAccountNumber: string;
  bankBranchCode: string;
  financialYearStart: number;
  vatPeriod: string;
}>): Promise<Company> {
  const rows = (await sql`
    UPDATE companies SET
      name = COALESCE(${input.name ?? null}, name),
      trading_name = COALESCE(${input.tradingName ?? null}, trading_name),
      registration_number = COALESCE(${input.registrationNumber ?? null}, registration_number),
      vat_number = COALESCE(${input.vatNumber ?? null}, vat_number),
      tax_number = COALESCE(${input.taxNumber ?? null}, tax_number),
      address_line1 = COALESCE(${input.addressLine1 ?? null}, address_line1),
      address_line2 = COALESCE(${input.addressLine2 ?? null}, address_line2),
      city = COALESCE(${input.city ?? null}, city),
      province = COALESCE(${input.province ?? null}, province),
      postal_code = COALESCE(${input.postalCode ?? null}, postal_code),
      phone = COALESCE(${input.phone ?? null}, phone),
      email = COALESCE(${input.email ?? null}, email),
      website = COALESCE(${input.website ?? null}, website),
      bank_name = COALESCE(${input.bankName ?? null}, bank_name),
      bank_account_number = COALESCE(${input.bankAccountNumber ?? null}, bank_account_number),
      bank_branch_code = COALESCE(${input.bankBranchCode ?? null}, bank_branch_code),
      financial_year_start = COALESCE(${input.financialYearStart ?? null}, financial_year_start),
      vat_period = COALESCE(${input.vatPeriod ?? null}, vat_period),
      updated_at = NOW()
    WHERE id = ${id}::UUID RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Company ${id} not found`);
  return mapCompany(rows[0]);
}

// ── User-Company ─────────────────────────────────────────────────────────────

export async function getUserCompanies(userId: string): Promise<CompanyUser[]> {
  const rows = (await sql`
    SELECT cu.company_id, c.name AS company_name, cu.role, cu.is_default
    FROM company_users cu
    JOIN companies c ON c.id = cu.company_id
    WHERE cu.user_id = ${userId}::UUID AND c.is_active = true
    ORDER BY cu.is_default DESC, c.name ASC
  `) as Row[];
  return rows.map((r: Row) => ({
    companyId: r.company_id,
    companyName: r.company_name,
    role: r.role,
    isDefault: r.is_default,
  }));
}

export async function setDefaultCompany(userId: string, companyId: string): Promise<void> {
  await sql`UPDATE company_users SET is_default = false WHERE user_id = ${userId}::UUID`;
  await sql`UPDATE company_users SET is_default = true WHERE user_id = ${userId}::UUID AND company_id = ${companyId}::UUID`;
}

export async function addUserToCompany(companyId: string, userId: string, role = 'user'): Promise<void> {
  await sql`
    INSERT INTO company_users (company_id, user_id, role)
    VALUES (${companyId}::UUID, ${userId}::UUID, ${role})
    ON CONFLICT (company_id, user_id) DO UPDATE SET role = ${role}
  `;
}

export async function removeUserFromCompany(companyId: string, userId: string): Promise<void> {
  await sql`DELETE FROM company_users WHERE company_id = ${companyId}::UUID AND user_id = ${userId}::UUID`;
}

// ── Mapper ───────────────────────────────────────────────────────────────────

function mapCompany(r: Row): Company {
  return {
    id: r.id,
    name: r.name,
    tradingName: r.trading_name,
    registrationNumber: r.registration_number,
    vatNumber: r.vat_number,
    taxNumber: r.tax_number,
    addressLine1: r.address_line1,
    addressLine2: r.address_line2,
    city: r.city,
    province: r.province,
    postalCode: r.postal_code,
    country: r.country,
    phone: r.phone,
    email: r.email,
    website: r.website,
    logoUrl: r.logo_url,
    bankName: r.bank_name,
    bankAccountNumber: r.bank_account_number,
    bankBranchCode: r.bank_branch_code,
    bankAccountType: r.bank_account_type,
    financialYearStart: r.financial_year_start,
    vatPeriod: r.vat_period,
    defaultCurrency: r.default_currency,
    isActive: r.is_active,
    createdAt: r.created_at,
  };
}

/**
 * Company-scoped authentication middleware.
 * Wraps withAuth and adds company context from X-Company-Id header
 * or the user's default company.
 */

import type { NextApiRequest, NextApiResponse, NextApiHandler } from 'next';
import { sql } from '@/lib/neon';
import { withAuth, type AuthenticatedNextApiRequest } from './middleware';
import { log } from '@/lib/logger';

export interface CompanyApiRequest extends AuthenticatedNextApiRequest {
  companyId: string;
  companyRole: string;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type CompanyHandler = (req: NextApiRequest, res: NextApiResponse<any>) => any;

/**
 * Middleware that requires authentication AND resolves the active company.
 *
 * Company resolution order:
 * 1. X-Company-Id request header (set by frontend CompanyContext)
 * 2. User's default company (is_default = true in company_users)
 * 3. First company the user belongs to
 *
 * Attaches companyId and companyRole to the request object.
 */
export function withCompany(handler: CompanyHandler): NextApiHandler {
  return withAuth(async (req: NextApiRequest, res: NextApiResponse) => {
    try {
      const authReq = req as AuthenticatedNextApiRequest;
      const userId = authReq.user.id;

      // 1. Try X-Company-Id header
      const companyId = req.headers['x-company-id'] as string | undefined;

      if (companyId) {
        // Validate user has access to this specific company
        const access = await sql`
          SELECT role FROM company_users
          WHERE user_id = ${userId} AND company_id = ${companyId}::UUID
          LIMIT 1
        `;

        if (access.length === 0) {
          return res.status(403).json({
            success: false,
            error: { code: 'FORBIDDEN', message: 'You do not have access to this company' },
          });
        }

        (req as CompanyApiRequest).companyId = companyId;
        (req as CompanyApiRequest).companyRole = access[0]!.role as string;
        return handler(req, res);
      }

      // 2. Fall back to user's default or first company
      const companies = await sql`
        SELECT company_id, role, is_default
        FROM company_users
        WHERE user_id = ${userId}
        ORDER BY is_default DESC, created_at ASC
        LIMIT 1
      `;

      if (companies.length === 0) {
        return res.status(400).json({
          success: false,
          error: { code: 'NO_COMPANY', message: 'No company assigned. Please contact an administrator.' },
        });
      }

      (req as CompanyApiRequest).companyId = companies[0]!.company_id as string;
      (req as CompanyApiRequest).companyRole = companies[0]!.role as string;
      return handler(req, res);
    } catch (error) {
      log.error('Company middleware error', error instanceof Error ? { message: error.message } : { error }, 'CompanyMiddleware');
      return res.status(500).json({
        success: false,
        error: { code: 'COMPANY_ERROR', message: 'Failed to resolve company context' },
      });
    }
  });
}

import {
  createContext,
  useContext,
  useEffect,
  useState,
  useCallback,
  ReactNode,
} from 'react';
import { useAuth } from './AuthContext';

const STORAGE_KEY = 'isaflow_active_company';

export interface Company {
  id: string;
  name: string;
  tradingName?: string;
  registrationNumber?: string;
  vatNumber?: string;
  taxNumber?: string;
  addressLine1?: string;
  addressLine2?: string;
  city?: string;
  province?: string;
  postalCode?: string;
  country?: string;
  phone?: string;
  email?: string;
  website?: string;
  logoUrl?: string;
  logoData?: string;
  bankName?: string;
  bankAccountNumber?: string;
  bankBranchCode?: string;
  bankAccountType?: string;
  financialYearStart?: number;
  vatPeriod?: string;
  defaultCurrency?: string;
  isActive?: boolean;
}

export interface CompanyUser {
  companyId: string;
  companyName: string;
  role: string;
  isDefault: boolean;
}

interface CompanyContextType {
  activeCompany: Company | null;
  companies: CompanyUser[];
  loading: boolean;
  companyRole: string | null;
  switchCompany: (companyId: string) => Promise<void>;
}

const CompanyContext = createContext<CompanyContextType | undefined>(undefined);

export function CompanyProvider({ children }: { children: ReactNode }) {
  const { user, isAuthenticated } = useAuth();
  const [activeCompany, setActiveCompany] = useState<Company | null>(null);
  const [companies, setCompanies] = useState<CompanyUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [companyRole, setCompanyRole] = useState<string | null>(null);

  const loadCompanyDetails = useCallback(async (companyId: string) => {
    try {
      const res = await fetch(`/api/accounting/companies?id=${companyId}`, {
        credentials: 'include',
      });
      if (res.ok) {
        const data = await res.json();
        const c = data.data;
        if (c) {
          const company: Company = {
            id: c.id,
            name: c.name,
            tradingName: c.trading_name || c.tradingName,
            registrationNumber: c.registration_number || c.registrationNumber,
            vatNumber: c.vat_number || c.vatNumber,
            taxNumber: c.tax_number || c.taxNumber,
            addressLine1: c.address_line1 || c.addressLine1,
            addressLine2: c.address_line2 || c.addressLine2,
            city: c.city,
            province: c.province,
            postalCode: c.postal_code || c.postalCode,
            country: c.country,
            phone: c.phone,
            email: c.email,
            website: c.website,
            logoUrl: c.logo_url || c.logoUrl,
            logoData: c.logo_data || c.logoData,
            bankName: c.bank_name || c.bankName,
            bankAccountNumber: c.bank_account_number || c.bankAccountNumber,
            bankBranchCode: c.bank_branch_code || c.bankBranchCode,
            bankAccountType: c.bank_account_type || c.bankAccountType,
            financialYearStart: c.financial_year_start || c.financialYearStart,
            vatPeriod: c.vat_period || c.vatPeriod,
            defaultCurrency: c.default_currency || c.defaultCurrency,
            isActive: c.is_active ?? c.isActive ?? true,
          };
          setActiveCompany(company);
          localStorage.setItem(STORAGE_KEY, JSON.stringify({ id: company.id, name: company.name }));
          return company;
        }
      }
    } catch {
      // Failed to load company details
    }
    return null;
  }, []);

  const loadUserCompanies = useCallback(async () => {
    if (!isAuthenticated) {
      setLoading(false);
      return;
    }

    try {
      const res = await fetch('/api/accounting/companies?action=user-companies', {
        credentials: 'include',
      });

      if (!res.ok) {
        setLoading(false);
        return;
      }

      const data = await res.json();
      const list: CompanyUser[] = (data.data || []).map((c: Record<string, unknown>) => ({
        companyId: c.companyId || c.company_id,
        companyName: c.companyName || c.company_name,
        role: c.role,
        isDefault: c.isDefault ?? c.is_default ?? false,
      }));

      setCompanies(list);

      if (list.length === 0) {
        setLoading(false);
        return;
      }

      // Determine which company to activate
      let targetId: string | null = null;

      // 1. Check localStorage
      try {
        const stored = localStorage.getItem(STORAGE_KEY);
        if (stored) {
          const { id } = JSON.parse(stored);
          if (id && list.some((c: CompanyUser) => c.companyId === id)) {
            targetId = id;
          }
        }
      } catch {
        // Invalid stored data
      }

      // 2. Fall back to default company
      if (!targetId) {
        const defaultCompany = list.find((c: CompanyUser) => c.isDefault) ?? list[0];
        targetId = defaultCompany?.companyId ?? null;
      }

      if (!targetId) {
        setLoading(false);
        return;
      }

      // Set the role
      const match = list.find((c: CompanyUser) => c.companyId === targetId);
      if (match) setCompanyRole(match.role);

      await loadCompanyDetails(targetId);
    } catch {
      // Network error
    } finally {
      setLoading(false);
    }
  }, [isAuthenticated, loadCompanyDetails]);

  useEffect(() => {
    loadUserCompanies();
  }, [loadUserCompanies]);

  const switchCompany = useCallback(async (companyId: string) => {
    setLoading(true);
    const match = companies.find(c => c.companyId === companyId);
    if (match) setCompanyRole(match.role);
    await loadCompanyDetails(companyId);
    setLoading(false);

    // Set as default on the server
    try {
      await fetch('/api/accounting/companies', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ action: 'set-default', companyId }),
      });
    } catch {
      // Non-critical
    }
  }, [companies, loadCompanyDetails]);

  const value: CompanyContextType = {
    activeCompany,
    companies,
    loading,
    companyRole,
    switchCompany,
  };

  return <CompanyContext.Provider value={value}>{children}</CompanyContext.Provider>;
}

export function useCompany() {
  const context = useContext(CompanyContext);
  if (context === undefined) {
    throw new Error('useCompany must be used within a CompanyProvider');
  }
  return context;
}

import { useState, useRef, useEffect } from 'react';
import { Building2, ChevronDown, Check, Plus } from 'lucide-react';
import { useCompany } from '@/contexts/CompanyContext';

export function CompanySwitcher() {
  const { activeCompany, companies, switchCompany, loading } = useCompany();
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  // Close on outside click
  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  if (loading || !activeCompany) {
    return (
      <div className="flex items-center gap-2 px-3 py-1.5 rounded-lg bg-gray-100 dark:bg-gray-800 animate-pulse">
        <div className="w-6 h-6 rounded bg-gray-300 dark:bg-gray-700" />
        <div className="w-24 h-4 rounded bg-gray-300 dark:bg-gray-700 hidden sm:block" />
      </div>
    );
  }

  return (
    <div ref={ref} className="relative">
      <button
        onClick={() => setOpen(!open)}
        className="flex items-center gap-2 px-3 py-1.5 rounded-lg bg-gray-100 dark:bg-gray-800 hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors border border-gray-200 dark:border-gray-700"
      >
        {/* Company logo or fallback icon */}
        {activeCompany.logoData ? (
          <img
            src={activeCompany.logoData}
            alt={activeCompany.name}
            className="w-6 h-6 rounded object-contain"
          />
        ) : (
          <div className="w-6 h-6 rounded bg-teal-600 flex items-center justify-center flex-shrink-0">
            <Building2 className="w-3.5 h-3.5 text-white" />
          </div>
        )}

        <span className="text-sm font-medium text-gray-900 dark:text-white truncate max-w-[140px] hidden sm:block">
          {activeCompany.tradingName || activeCompany.name}
        </span>

        <ChevronDown className={`w-3.5 h-3.5 text-gray-500 transition-transform ${open ? 'rotate-180' : ''}`} />
      </button>

      {/* Dropdown */}
      {open && companies.length > 0 && (
        <div className="absolute top-full left-0 mt-1 w-72 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl shadow-xl z-50 overflow-hidden">
          <div className="px-3 py-2 border-b border-gray-100 dark:border-gray-700">
            <p className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">
              Switch Company
            </p>
          </div>

          <div className="max-h-64 overflow-y-auto py-1">
            {companies.map((c) => {
              const isActive = c.companyId === activeCompany.id;
              return (
                <button
                  key={c.companyId}
                  onClick={() => {
                    if (!isActive) {
                      void switchCompany(c.companyId);
                    }
                    setOpen(false);
                  }}
                  className={`w-full flex items-center gap-3 px-3 py-2.5 text-left transition-colors ${
                    isActive
                      ? 'bg-teal-50 dark:bg-teal-900/20'
                      : 'hover:bg-gray-50 dark:hover:bg-gray-700/50'
                  }`}
                >
                  <div className="w-8 h-8 rounded-lg bg-gray-100 dark:bg-gray-700 flex items-center justify-center flex-shrink-0">
                    <Building2 className={`w-4 h-4 ${isActive ? 'text-teal-600' : 'text-gray-500'}`} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className={`text-sm font-medium truncate ${
                      isActive ? 'text-teal-700 dark:text-teal-400' : 'text-gray-900 dark:text-white'
                    }`}>
                      {c.companyName}
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-400 capitalize">{c.role}</p>
                  </div>
                  {isActive && <Check className="w-4 h-4 text-teal-600 flex-shrink-0" />}
                </button>
              );
            })}
          </div>

          <div className="border-t border-gray-100 dark:border-gray-700 p-2">
            <a
              href="/accounting/company-settings"
              className="flex items-center gap-2 px-3 py-2 text-sm text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-50 dark:hover:bg-gray-700/50 rounded-lg transition-colors"
              onClick={() => setOpen(false)}
            >
              <Plus className="w-4 h-4" />
              <span>Manage Companies</span>
            </a>
          </div>
        </div>
      )}
    </div>
  );
}

