                  <Tooltip
                    contentStyle={{ backgroundColor: 'var(--ff-bg-secondary)', border: '1px solid var(--ff-border-light)', borderRadius: '8px', color: 'var(--ff-text-primary)' }}
                    formatter={(value) => [fmtCurrency(Number(value)), '']}
