            <p className="text-sm text-[var(--ff-text-secondary)]">AP invoices, matching & approvals</p>
          </div>
          <ArrowRight className="h-4 w-4 text-[var(--ff-text-tertiary)] group-hover:text-orange-500 transition-colors" />
