                  </button>
                );
              })}
            </nav>
          </div>
        </div>

        {/* Tab Content */}
        <div className="p-6">
          {activeTab === 'overview' && <OverviewTab />}
          {activeTab === 'chart-of-accounts' && <ChartOfAccountsTab />}
          {activeTab === 'journal-entries' && <JournalEntriesTab />}
          {activeTab === 'fiscal-periods' && <FiscalPeriodsTab />}
          {activeTab === 'reports' && <ReportsTab />}
        </div>
      </div>
    </AppLayout>
  );
}

