/**
 * Accounting Adjustments Page
 * Phase 1 Sage Alignment: Customer & supplier balance adjustments
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import { SlidersHorizontal, Plus, Check, Loader2 } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

interface Adjustment {
  id: string; adjustmentNumber: string; entityType: string; entityId: string;
  entityName?: string; adjustmentType: string; amount: number; reason: string;
  adjustmentDate: string; status: string;
}
interface Entity { id: string; company_name: string }

const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

const STATUS_BADGE: Record<string, string> = {
  draft: 'bg-gray-500/10 text-gray-400',
  approved: 'bg-teal-500/10 text-teal-400',
  cancelled: 'bg-red-500/10 text-red-400',
};

export default function AdjustmentsPage() {
  const router = useRouter();
  const entityType = (router.query.type as string) || 'customer';
  const [items, setItems] = useState<Adjustment[]>([]);
  const [entities, setEntities] = useState<Entity[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [busy, setBusy] = useState('');
  const [error, setError] = useState('');
  const [form, setForm] = useState({ entityId: '', adjustmentType: 'debit', amount: '', reason: '' });

  const load = useCallback(async () => {
    setLoading(true);
    const res = await apiFetch(`/api/accounting/adjustments?entityType=${entityType}`, { credentials: 'include' });
    const json = await res.json();
    setItems(json.data?.items || []);
    setLoading(false);
  }, [entityType]);

  useEffect(() => { load(); }, [load]);
  useEffect(() => {
    const url = entityType === 'supplier' ? '/api/suppliers' : '/api/clients';
    fetch(url, { credentials: 'include' }).then(r => r.json()).then(res => {
      const d = res.data || res;
      setEntities(Array.isArray(d) ? d : d.clients || d.suppliers || []);
    });
  }, [entityType]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(''); setBusy('new');
    try {
      const res = await apiFetch('/api/accounting/adjustments', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ entityType, entityId: form.entityId, adjustmentType: form.adjustmentType, amount: Number(form.amount), reason: form.reason }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      setShowForm(false);
      setForm({ entityId: '', adjustmentType: 'debit', amount: '', reason: '' });
      await load();
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
    finally { setBusy(''); }
  };

  const approve = async (id: string) => {
    setBusy(id);
    await apiFetch('/api/accounting/adjustments-action', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      credentials: 'include', body: JSON.stringify({ action: 'approve', id }),
    });
    await load(); setBusy('');
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-amber-500/10"><SlidersHorizontal className="h-6 w-6 text-amber-500" /></div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">{entityType === 'supplier' ? 'Supplier' : 'Customer'} Adjustments</h1>
            </div>
            <button onClick={() => setShowForm(!showForm)} className="inline-flex items-center gap-2 px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 text-sm font-medium">
              <Plus className="h-4 w-4" /> New Adjustment
            </button>
          </div>
          <div className="flex gap-2 mt-3">
            <button onClick={() => router.push('/accounting/adjustments?type=customer')} className={`px-4 py-2 rounded text-sm ${entityType === 'customer' ? 'bg-amber-600 text-white' : 'text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'}`}>Customer</button>
            <button onClick={() => router.push('/accounting/adjustments?type=supplier')} className={`px-4 py-2 rounded text-sm ${entityType === 'supplier' ? 'bg-amber-600 text-white' : 'text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'}`}>Supplier</button>
          </div>
        </div>

        <div className="p-6 space-y-4">
          {error && <div className="p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">{error}</div>}

          {showForm && (
            <form onSubmit={handleSubmit} className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6 space-y-4">
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">New {entityType === 'supplier' ? 'Supplier' : 'Customer'} Adjustment</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <select value={form.entityId} onChange={e => setForm(f => ({ ...f, entityId: e.target.value }))} className="ff-select" required>
                  <option value="">Select {entityType === 'supplier' ? 'Supplier' : 'Client'} *</option>
                  {entities.map(e => <option key={e.id} value={e.id}>{e.company_name}</option>)}
                </select>
                <select value={form.adjustmentType} onChange={e => setForm(f => ({ ...f, adjustmentType: e.target.value }))} className="ff-select">
                  <option value="debit">Debit (Increase Balance)</option>
                  <option value="credit">Credit (Decrease Balance)</option>
                </select>
                <input type="number" step="0.01" min="0.01" value={form.amount} onChange={e => setForm(f => ({ ...f, amount: e.target.value }))} className="ff-input" placeholder="Amount *" required />
                <input value={form.reason} onChange={e => setForm(f => ({ ...f, reason: e.target.value }))} className="ff-input" placeholder="Reason *" required />
              </div>
              <div className="flex justify-end gap-2">
                <button type="button" onClick={() => setShowForm(false)} className="px-4 py-2 text-sm text-[var(--ff-text-secondary)]">Cancel</button>
                <button type="submit" disabled={busy === 'new'} className="px-6 py-2 bg-amber-600 text-white rounded-lg text-sm font-medium disabled:opacity-50">
                  {busy === 'new' ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Create Adjustment'}
                </button>
              </div>
            </form>
          )}

          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
            <table className="w-full text-sm">
              <thead><tr className="border-b border-[var(--ff-border-light)] text-left text-[var(--ff-text-secondary)]">
                <th className="px-4 py-3">ADJ Number</th><th className="px-4 py-3">{entityType === 'supplier' ? 'Supplier' : 'Client'}</th>
                <th className="px-4 py-3">Type</th><th className="px-4 py-3 text-right">Amount</th>
                <th className="px-4 py-3">Reason</th><th className="px-4 py-3">Status</th><th className="px-4 py-3">Actions</th>
              </tr></thead>
              <tbody>
                {loading && <tr><td colSpan={7} className="px-4 py-8 text-center text-[var(--ff-text-tertiary)]">Loading...</td></tr>}
                {!loading && items.length === 0 && <tr><td colSpan={7} className="px-4 py-8 text-center text-[var(--ff-text-tertiary)]">No adjustments</td></tr>}
                {items.map(item => (
                  <tr key={item.id} className="border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-primary)]/50">
                    <td className="px-4 py-3 text-[var(--ff-text-primary)] font-medium">{item.adjustmentNumber}</td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{item.entityName || '—'}</td>
                    <td className="px-4 py-3"><span className={`px-2 py-0.5 rounded text-xs font-medium ${item.adjustmentType === 'debit' ? 'bg-blue-500/10 text-blue-400' : 'bg-orange-500/10 text-orange-400'}`}>{item.adjustmentType}</span></td>
                    <td className="px-4 py-3 text-right text-[var(--ff-text-primary)]">{fmt(item.amount)}</td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)] truncate max-w-[200px]">{item.reason}</td>
                    <td className="px-4 py-3"><span className={`px-2 py-0.5 rounded text-xs font-medium ${STATUS_BADGE[item.status] || ''}`}>{item.status}</span></td>
                    <td className="px-4 py-3">
                      {item.status === 'draft' && (
                        <button onClick={() => approve(item.id)} disabled={busy === item.id} className="p-1 text-teal-400 hover:text-teal-300" title="Approve">
                          {busy === item.id ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />}
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Approval Workflows — Manage rules and pending approval requests
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import {
import { apiFetch } from '@/lib/apiFetch';
  Shield, CheckCircle2, XCircle, Clock, Loader2, Plus, Trash2, AlertCircle,
} from 'lucide-react';

function formatCurrency(amount: number): string {
  return 'R ' + Math.abs(amount).toLocaleString('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

interface ApprovalRule {
  id: string;
  name: string;
  documentType: string;
  conditionField: string;
  conditionOperator: string;
  conditionValue: number;
  approverRole: string;
  isActive: boolean;
}

interface ApprovalRequest {
  id: string;
  ruleName?: string;
  documentType: string;
  documentId: string;
  documentReference: string | null;
  amount: number | null;
  status: string;
  requestedByName?: string;
  requestedAt: string;
  decidedByName?: string;
  decidedAt: string | null;
  decisionNotes: string | null;
}

const DOC_TYPE_LABELS: Record<string, string> = {
  customer_invoice: 'Customer Invoice',
  supplier_invoice: 'Supplier Invoice',
  payment: 'Payment',
  journal_entry: 'Journal Entry',
  credit_note: 'Credit Note',
};

const STATUS_STYLES: Record<string, string> = {
  pending: 'bg-amber-500/20 text-amber-500',
  approved: 'bg-teal-500/20 text-teal-500',
  rejected: 'bg-red-500/20 text-red-500',
  cancelled: 'bg-gray-500/20 text-gray-500',
};

export default function ApprovalsPage() {
  const [tab, setTab] = useState<'pending' | 'rules' | 'history'>('pending');
  const [requests, setRequests] = useState<ApprovalRequest[]>([]);
  const [rules, setRules] = useState<ApprovalRule[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [deciding, setDeciding] = useState<string | null>(null);

  const fetchData = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const [reqRes, rulesRes] = await Promise.all([
        fetch(tab === 'pending' ? '/api/accounting/approval-requests?status=pending' : '/api/accounting/approval-requests'),
        apiFetch('/api/accounting/approval-rules'),
      ]);
      if (!reqRes.ok || !rulesRes.ok) throw new Error('Failed to load');
      const reqJson = await reqRes.json();
      const rulesJson = await rulesRes.json();
      setRequests(reqJson.data?.items ?? []);
      setRules(rulesJson.data?.items ?? []);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load');
    } finally {
      setLoading(false);
    }
  }, [tab]);

  useEffect(() => { void fetchData(); }, [fetchData]);

  const handleDecision = async (requestId: string, action: 'approve' | 'reject') => {
    setDeciding(requestId);
    try {
      const res = await apiFetch('/api/accounting/approval-requests', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action, requestId }),
      });
      if (!res.ok) throw new Error('Failed');
      await fetchData();
    } catch {
      setError('Failed to process decision');
    } finally {
      setDeciding(null);
    }
  };

  const handleDeleteRule = async (ruleId: string) => {
    try {
      await apiFetch(`/api/accounting/approval-rules?id=${ruleId}`, { method: 'DELETE' });
      await fetchData();
    } catch {
      setError('Failed to delete rule');
    }
  };

  const pendingCount = requests.filter(r => r.status === 'pending').length;

  return (
    <AppLayout>
      <div className="p-4 lg:p-6 space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-teal-500/10">
              <Shield className="h-6 w-6 text-teal-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Approvals</h1>
              <p className="text-sm text-[var(--ff-text-secondary)]">
                Review and manage approval workflows
              </p>
            </div>
          </div>
          {pendingCount > 0 && (
            <div className="bg-amber-500/20 text-amber-500 px-3 py-1 rounded-full text-sm font-medium">
              {pendingCount} pending
            </div>
          )}
        </div>

        {/* Tabs */}
        <div className="flex gap-1 border-b border-[var(--ff-border-primary)]">
          {(['pending', 'history', 'rules'] as const).map(t => (
            <button
              key={t}
              onClick={() => setTab(t)}
              className={`px-4 py-2.5 text-sm font-medium border-b-2 transition-colors capitalize ${
                tab === t
                  ? 'border-teal-500 text-teal-500'
                  : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'
              }`}
            >
              {t === 'pending' ? `Pending (${pendingCount})` : t}
            </button>
          ))}
        </div>

        {error && (
          <div className="bg-red-500/10 border border-red-500/30 rounded-lg p-3 flex items-center gap-2 text-red-500 text-sm">
            <AlertCircle className="h-4 w-4" /> {error}
          </div>
        )}

        {loading ? (
          <div className="flex justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
          </div>
        ) : tab === 'rules' ? (
          /* Rules Tab */
          <div className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-xl overflow-hidden">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-[var(--ff-bg-secondary)]">
                  <th className="text-left px-4 py-3 font-medium text-[var(--ff-text-secondary)]">Rule Name</th>
                  <th className="text-left px-4 py-3 font-medium text-[var(--ff-text-secondary)]">Document Type</th>
                  <th className="text-left px-4 py-3 font-medium text-[var(--ff-text-secondary)]">Condition</th>
                  <th className="text-left px-4 py-3 font-medium text-[var(--ff-text-secondary)]">Approver</th>
                  <th className="text-center px-4 py-3 font-medium text-[var(--ff-text-secondary)]">Active</th>
                  <th className="text-center px-4 py-3 font-medium text-[var(--ff-text-secondary)]">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[var(--ff-border-primary)]">
                {rules.length === 0 ? (
                  <tr><td colSpan={6} className="px-4 py-8 text-center text-[var(--ff-text-secondary)]">No approval rules configured</td></tr>
                ) : rules.map(rule => (
                  <tr key={rule.id} className="hover:bg-[var(--ff-bg-hover)]">
                    <td className="px-4 py-3 text-[var(--ff-text-primary)] font-medium">{rule.name}</td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{DOC_TYPE_LABELS[rule.documentType] || rule.documentType}</td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                      {rule.conditionOperator === 'any' ? 'All documents' : `${rule.conditionField} > ${formatCurrency(rule.conditionValue)}`}
                    </td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)] capitalize">{rule.approverRole}</td>
                    <td className="px-4 py-3 text-center">
                      <span className={`inline-block w-2 h-2 rounded-full ${rule.isActive ? 'bg-teal-500' : 'bg-gray-400'}`} />
                    </td>
                    <td className="px-4 py-3 text-center">
                      <button onClick={() => void handleDeleteRule(rule.id)} className="text-red-400 hover:text-red-500">
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          /* Pending / History Tab */
          <div className="space-y-3">
            {requests.length === 0 ? (
              <div className="text-center py-12 text-[var(--ff-text-secondary)]">
                {tab === 'pending' ? 'No pending approvals' : 'No approval history'}
              </div>
            ) : requests.filter(r => tab === 'pending' ? r.status === 'pending' : true).map(req => (
              <div
                key={req.id}
                className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-xl p-4 flex items-center gap-4"
              >
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${STATUS_STYLES[req.status] || ''}`}>
                      {req.status}
                    </span>
                    <span className="text-xs text-[var(--ff-text-tertiary)]">
                      {DOC_TYPE_LABELS[req.documentType] || req.documentType}
                    </span>
                    {req.ruleName && (
                      <span className="text-xs text-[var(--ff-text-tertiary)]">• {req.ruleName}</span>
                    )}
                  </div>
                  <p className="text-sm font-medium text-[var(--ff-text-primary)]">
                    {req.documentReference || req.documentId.slice(0, 8)}
                    {req.amount != null && <span className="ml-2 text-teal-500">{formatCurrency(req.amount)}</span>}
                  </p>
                  <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">
                    Requested by {req.requestedByName || 'Unknown'} • {new Date(req.requestedAt).toLocaleDateString('en-ZA')}
                    {req.decidedByName && ` • Decided by ${req.decidedByName}`}
                  </p>
                </div>

                {req.status === 'pending' && (
                  <div className="flex gap-2 flex-shrink-0">
                    <button
                      onClick={() => void handleDecision(req.id, 'approve')}
                      disabled={deciding === req.id}
                      className="flex items-center gap-1 px-3 py-1.5 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-medium transition-colors disabled:opacity-50"
                    >
                      <CheckCircle2 className="h-4 w-4" /> Approve
                    </button>
                    <button
                      onClick={() => void handleDecision(req.id, 'reject')}
                      disabled={deciding === req.id}
                      className="flex items-center gap-1 px-3 py-1.5 bg-red-600 hover:bg-red-700 text-white rounded-lg text-sm font-medium transition-colors disabled:opacity-50"
                    >
                      <XCircle className="h-4 w-4" /> Reject
                    </button>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>
    </AppLayout>
  );
}

/**
 * SARS Submission History Page
 * Table of all past submissions with type, period, status, reference, and details.
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  FileText, Loader2, ChevronLeft,
  CheckCircle2, Clock, XCircle, AlertTriangle,
  Eye, X,
} from 'lucide-react';
import { formatDate } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

interface Submission {
  id: string;
  formType: string;
  periodStart: string;
  periodEnd: string;
  status: string;
  formData: Record<string, unknown>;
  submissionReference: string | null;
  submittedAt: string | null;
  submittedBy: string | null;
  notes: string | null;
  createdAt: string;
  updatedAt: string;
}

const fmt = (n: number) =>
  new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

const formatDateTime = (d: string) => {
  if (!d) return '—';
  return new Date(d).toLocaleString('en-ZA', {
    day: '2-digit', month: 'short', year: 'numeric',
    hour: '2-digit', minute: '2-digit',
  });
};

const statusBadge = (status: string) => {
  const configs: Record<string, { icon: typeof CheckCircle2; className: string }> = {
    submitted: { icon: CheckCircle2, className: 'bg-emerald-500/10 text-emerald-400' },
    accepted: { icon: CheckCircle2, className: 'bg-emerald-500/10 text-emerald-400' },
    draft: { icon: Clock, className: 'bg-amber-500/10 text-amber-400' },
    generated: { icon: Clock, className: 'bg-blue-500/10 text-blue-400' },
    rejected: { icon: XCircle, className: 'bg-red-500/10 text-red-400' },
  };
  const cfg = configs[status] || { icon: AlertTriangle, className: 'bg-gray-500/10 text-gray-400' };
  const Icon = cfg.icon;

  return (
    <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium ${cfg.className}`}>
      <Icon className="h-3 w-3" /> {status}
    </span>
  );
};

export default function SubmissionsPage() {
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [filter, setFilter] = useState<string>('all');
  const [detail, setDetail] = useState<Submission | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const typeParam = filter !== 'all' ? `?type=${filter}` : '';
      const res = await fetch(
        `/api/accounting/sars/sars-submissions${typeParam}`,
        { credentials: 'include' }
      );
      const json = await res.json();
      if (!res.ok) throw new Error(json.error?.message || json.message || 'Failed');
      setSubmissions(json.data?.items || []);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load submissions');
    } finally {
      setLoading(false);
    }
  }, [filter]);

  useEffect(() => { load(); }, [load]);

  const viewDetail = async (id: string) => {
    try {
      const res = await apiFetch('/api/accounting/sars/sars-submissions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ id, action: 'get' }),
      });
      const json = await res.json();
      if (json.data) {
        setDetail(json.data);
      }
    } catch {
      // Fallback to local data
      const sub = submissions.find((s) => s.id === id);
      if (sub) setDetail(sub);
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center gap-3">
            <Link
              href="/accounting/sars"
              className="p-2 rounded-lg hover:bg-[var(--ff-bg-primary)] text-[var(--ff-text-secondary)]"
            >
              <ChevronLeft className="h-5 w-5" />
            </Link>
            <div className="p-2 rounded-lg bg-purple-500/10">
              <FileText className="h-6 w-6 text-purple-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Submission History</h1>
              <p className="text-sm text-[var(--ff-text-secondary)]">
                All SARS eFiling submissions and their statuses
              </p>
            </div>
          </div>
        </div>

        <div className="p-6 space-y-4">
          {error && <div className="p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">{error}</div>}

          {/* Filter Tabs */}
          <div className="flex gap-1 bg-[var(--ff-bg-secondary)] rounded-lg p-1 w-fit border border-[var(--ff-border-light)]">
            {['all', 'VAT201', 'EMP201', 'EMP501', 'IRP5'].map((f) => (
              <button
                key={f}
                onClick={() => setFilter(f)}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${
                  filter === f
                    ? 'bg-teal-600 text-white'
                    : 'text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'
                }`}
              >
                {f === 'all' ? 'All' : f}
              </button>
            ))}
          </div>

          {/* Submissions Table */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-[var(--ff-border-light)] text-left text-[var(--ff-text-secondary)]">
                  <th className="px-4 py-3">Type</th>
                  <th className="px-4 py-3">Period</th>
                  <th className="px-4 py-3">Status</th>
                  <th className="px-4 py-3">SARS Reference</th>
                  <th className="px-4 py-3">Submitted</th>
                  <th className="px-4 py-3">Created</th>
                  <th className="px-4 py-3">Actions</th>
                </tr>
              </thead>
              <tbody>
                {loading && (
                  <tr>
                    <td colSpan={7} className="px-4 py-8 text-center text-[var(--ff-text-tertiary)]">
                      <Loader2 className="h-5 w-5 animate-spin inline mr-2" />
                      Loading submissions...
                    </td>
                  </tr>
                )}
                {!loading && submissions.length === 0 && (
                  <tr>
                    <td colSpan={7} className="px-4 py-8 text-center text-[var(--ff-text-tertiary)]">
                      No submissions found. Generate a VAT201 or EMP201 to create your first submission.
                    </td>
                  </tr>
                )}
                {submissions.map((sub) => (
                  <tr
                    key={sub.id}
                    className="border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-primary)]/50"
                  >
                    <td className="px-4 py-3">
                      <span className="inline-flex px-2 py-0.5 rounded text-xs font-medium bg-teal-500/10 text-teal-400">
                        {sub.formType}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-[var(--ff-text-primary)]">
                      {formatDate(sub.periodStart)} — {formatDate(sub.periodEnd)}
                    </td>
                    <td className="px-4 py-3">{statusBadge(sub.status)}</td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)] font-mono text-xs">
                      {sub.submissionReference || '—'}
                    </td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                      {sub.submittedAt ? formatDateTime(sub.submittedAt) : '—'}
                    </td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                      {formatDate(sub.createdAt)}
                    </td>
                    <td className="px-4 py-3">
                      <button
                        onClick={() => viewDetail(sub.id)}
                        className="inline-flex items-center gap-1 px-2 py-1 rounded text-xs text-teal-500 hover:text-teal-400 hover:bg-teal-500/10"
                      >
                        <Eye className="h-3 w-3" /> View
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Detail Modal */}
        {detail && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] w-full max-w-2xl mx-4 max-h-[80vh] overflow-auto">
              <div className="px-6 py-4 border-b border-[var(--ff-border-light)] flex items-center justify-between sticky top-0 bg-[var(--ff-bg-secondary)]">
                <h3 className="text-lg font-semibold text-[var(--ff-text-primary)]">
                  {detail.formType} — {formatDate(detail.periodStart)} to {formatDate(detail.periodEnd)}
                </h3>
                <button
                  onClick={() => setDetail(null)}
                  className="p-1 rounded hover:bg-[var(--ff-bg-primary)] text-[var(--ff-text-secondary)]"
                >
                  <X className="h-5 w-5" />
                </button>
              </div>

              <div className="p-6 space-y-4">
                <div className="grid grid-cols-2 gap-4 text-sm">
                  <div>
                    <p className="text-[var(--ff-text-tertiary)] text-xs mb-1">Status</p>
                    {statusBadge(detail.status)}
                  </div>
                  <div>
                    <p className="text-[var(--ff-text-tertiary)] text-xs mb-1">SARS Reference</p>
                    <p className="text-[var(--ff-text-primary)] font-mono">
                      {detail.submissionReference || '—'}
                    </p>
                  </div>
                  <div>
                    <p className="text-[var(--ff-text-tertiary)] text-xs mb-1">Submitted</p>
                    <p className="text-[var(--ff-text-secondary)]">
                      {detail.submittedAt ? formatDateTime(detail.submittedAt) : '—'}
                    </p>
                  </div>
                  <div>
                    <p className="text-[var(--ff-text-tertiary)] text-xs mb-1">Created</p>
                    <p className="text-[var(--ff-text-secondary)]">
                      {formatDateTime(detail.createdAt)}
                    </p>
                  </div>
                </div>

                {detail.notes && (
                  <div>
                    <p className="text-[var(--ff-text-tertiary)] text-xs mb-1">Notes</p>
                    <p className="text-[var(--ff-text-secondary)] text-sm">{detail.notes}</p>
                  </div>
                )}

                {/* Form Data */}
                <div>
                  <p className="text-[var(--ff-text-tertiary)] text-xs mb-2">Form Data</p>
                  <div className="bg-[var(--ff-bg-primary)] rounded-lg p-4 border border-[var(--ff-border-light)]">
                    {detail.formType === 'VAT201' && <VAT201Detail data={detail.formData} />}
                    {detail.formType === 'EMP201' && <EMP201Detail data={detail.formData} />}
                    {detail.formType !== 'VAT201' && detail.formType !== 'EMP201' && (
                      <pre className="text-xs text-[var(--ff-text-secondary)] overflow-auto">
                        {JSON.stringify(detail.formData, null, 2)}
                      </pre>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </AppLayout>
  );
}

