/**
 * Reusable Account Transaction Drill-Down Panel
 * Lazy-loads transactions from the account-transactions API when rendered.
 * Used by Income Statement, Balance Sheet, Trial Balance, and Budget vs Actual.
 */

import { useState, useEffect } from 'react';
import { Loader2, AlertCircle } from 'lucide-react';
import { formatDisplayDate } from '@/utils/dateFormat';

const fmt = (n: number) =>
  new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

const fmtDate = (d: string) => {
  if (!d) return '—';
  // Handle YYYY-MM-DD strings by appending T00:00:00 to avoid timezone-shift issues
  const iso = d.length === 10 ? `${d}T00:00:00` : d;
  return formatDisplayDate(iso, d);
};

interface Transaction {
  date: string;
  entryNumber: string;
  description: string;
  debit: number;
  credit: number;
  balance: number;
  source: string;
}

interface DrillDownData {
  accountCode: string;
  accountName: string;
  openingBalance: number;
  closingBalance: number;
  transactions: Transaction[];
}

interface AccountDrillDownProps {
  accountCode: string;
  periodStart: string;
  periodEnd: string;
  /** Render inside a <table> (uses <tr>/<td>) vs standalone (uses <div>) */
  asTableRow?: boolean;
  /** Column span when rendered as table row */
  colSpan?: number;
}

export function AccountDrillDown({
  accountCode,
  periodStart,
  periodEnd,
  asTableRow,
  colSpan = 5,
}: AccountDrillDownProps) {
  const [data, setData] = useState<DrillDownData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError('');

    const params = new URLSearchParams({
      account_code: accountCode,
      period_start: periodStart,
      period_end: periodEnd,
    });

    fetch(`/api/accounting/reports-account-transactions?${params}`, {
      credentials: 'include',
    })
      .then(r => r.json())
      .then(json => {
        if (cancelled) return;
        const d = json.data || json;
        setData(d);
      })
      .catch(() => {
        if (!cancelled) setError('Failed to load transactions');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => { cancelled = true; };
  }, [accountCode, periodStart, periodEnd]);

  const content = (
    <div className="bg-[var(--ff-bg-primary)] border-t border-[var(--ff-border-light)]">
      {loading ? (
        <div className="flex items-center justify-center py-4">
          <Loader2 className="h-4 w-4 animate-spin text-[var(--ff-text-tertiary)]" />
          <span className="ml-2 text-xs text-[var(--ff-text-tertiary)]">Loading transactions...</span>
        </div>
      ) : error ? (
        <div className="flex items-center gap-2 px-4 py-3 text-xs text-red-400">
          <AlertCircle className="h-3.5 w-3.5" /> {error}
        </div>
      ) : data && data.transactions.length === 0 ? (
        <div className="px-4 py-3 text-xs text-[var(--ff-text-tertiary)]">
          No transactions in this period
        </div>
      ) : data ? (
        <div>
          {/* Opening balance */}
          <div className="px-4 py-1.5 flex items-center justify-between text-xs bg-[var(--ff-bg-tertiary)]/50 border-b border-[var(--ff-border-light)]">
            <span className="text-[var(--ff-text-tertiary)] font-medium">Opening Balance</span>
            <span className="font-mono text-[var(--ff-text-secondary)]">{fmt(data.openingBalance)}</span>
          </div>

          {/* Column headers */}
          <div className="px-4 py-1 flex items-center gap-3 text-[10px] uppercase tracking-wider text-[var(--ff-text-tertiary)] border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]/30">
            <span className="w-20">Date</span>
            <span className="w-24">Entry #</span>
            <span className="flex-1">Description</span>
            <span className="w-24 text-right">Debit</span>
            <span className="w-24 text-right">Credit</span>
            <span className="w-24 text-right">Balance</span>
          </div>

          {/* Transaction rows */}
          {data.transactions.map((tx, i) => (
            <div
              key={`${tx.entryNumber}-${i}`}
              className="px-4 py-1 flex items-center gap-3 text-xs border-b border-[var(--ff-border-light)]/40 hover:bg-[var(--ff-bg-tertiary)]/20"
            >
              <span className="w-20 text-[var(--ff-text-tertiary)]">{fmtDate(tx.date)}</span>
              <span className="w-24 font-mono text-[var(--ff-text-secondary)]">{tx.entryNumber}</span>
              <span className="flex-1 text-[var(--ff-text-secondary)] truncate">{tx.description}</span>
              <span className="w-24 text-right font-mono text-[var(--ff-text-primary)]">
                {tx.debit > 0 ? fmt(tx.debit) : ''}
              </span>
              <span className="w-24 text-right font-mono text-[var(--ff-text-primary)]">
                {tx.credit > 0 ? fmt(tx.credit) : ''}
              </span>
              <span className="w-24 text-right font-mono text-[var(--ff-text-secondary)]">
                {fmt(tx.balance)}
              </span>
            </div>
          ))}

          {/* Closing balance */}
          <div className="px-4 py-1.5 flex items-center justify-between text-xs bg-[var(--ff-bg-tertiary)]/50 border-t border-[var(--ff-border-light)]">
            <span className="text-[var(--ff-text-tertiary)] font-medium">
              Closing Balance ({data.transactions.length} transaction{data.transactions.length !== 1 ? 's' : ''})
            </span>
            <span className="font-mono font-medium text-[var(--ff-text-primary)]">{fmt(data.closingBalance)}</span>
          </div>
        </div>
      ) : null}
    </div>
  );

  if (asTableRow) {
    return (
      <tr>
        <td colSpan={colSpan} className="p-0">{content}</td>
      </tr>
    );
  }

  return content;
}

/**
 * ExchangeRatesPanel — set rates, view history, and quick converter
 * Part of the Multi-Currency Management page
 */

import { useState } from 'react';
import { Save, ArrowRight, Loader2 } from 'lucide-react';
import { notify } from '@/utils/toast';
import type { Currency, ExchangeRate } from '@/modules/accounting/services/currencyService';

interface Props {
  currencies: Currency[];
  exchangeRates: ExchangeRate[];
  onRefresh: () => void;
}

interface RateForm {
  fromCurrency: string;
  toCurrency: string;
  rate: string;
  effectiveDate: string;
}

interface ConvertForm {
  amount: string;
  from: string;
  to: string;
}

// 🟢 WORKING: Exchange rate management with set-rate form, history table, and quick converter
export function ExchangeRatesPanel({ currencies, exchangeRates, onRefresh }: Props) {
  const today = new Date().toISOString().split('T')[0]!;

  const defaultFrom = currencies.find(c => c.code !== 'ZAR')?.code || '';
  const defaultTo = currencies[0]?.code || 'ZAR';

  const [rateForm, setRateForm] = useState<RateForm>({
    fromCurrency: defaultFrom,
    toCurrency: defaultTo,
    rate: '',
    effectiveDate: today,
  });
  const [savingRate, setSavingRate] = useState(false);

  const [convertForm, setConvertForm] = useState<ConvertForm>({
    amount: '',
    from: defaultFrom,
    to: defaultTo,
  });
  const [convertResult, setConvertResult] = useState<{ converted: number; rate: number } | null>(null);
  const [converting, setConverting] = useState(false);

  const handleSaveRate = async () => {
    if (!rateForm.fromCurrency || !rateForm.toCurrency || !rateForm.rate || !rateForm.effectiveDate) {
      notify.error('All fields are required');
      return;
    }
    if (rateForm.fromCurrency === rateForm.toCurrency) {
      notify.error('From and To currencies must differ');
      return;
    }
    const rateVal = parseFloat(rateForm.rate);
    if (isNaN(rateVal) || rateVal <= 0) {
      notify.error('Rate must be a positive number');
      return;
    }
    setSavingRate(true);
    try {
      const res = await fetch('/api/accounting/exchange-rates', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          fromCurrency: rateForm.fromCurrency,
          toCurrency: rateForm.toCurrency,
          rate: rateVal,
          effectiveDate: rateForm.effectiveDate,
          source: 'manual',
        }),
      });
      const json = await res.json();
      if (!res.ok || json.success === false) {
        notify.error(json.message || 'Failed to save rate');
        return;
      }
      notify.success(`Rate ${rateForm.fromCurrency}/${rateForm.toCurrency} saved`);
      setRateForm(f => ({ ...f, rate: '' }));
      onRefresh();
    } catch {
      notify.error('Failed to save exchange rate');
    } finally {
      setSavingRate(false);
    }
  };

  const handleConvert = async () => {
    const amt = parseFloat(convertForm.amount);
    if (isNaN(amt) || amt <= 0) {
      notify.error('Enter a valid amount');
      return;
    }
    if (!convertForm.from || !convertForm.to) {
      notify.error('Select both currencies');
      return;
    }
    setConverting(true);
    setConvertResult(null);
    try {
      const params = new URLSearchParams({
        convert: 'true',
        from: convertForm.from,
        to: convertForm.to,
        amount: String(amt),
      });
      const res = await fetch(`/api/accounting/exchange-rates?${params}`, { credentials: 'include' });
      const json = await res.json();
      if (!res.ok || json.success === false) {
        notify.error(json.message || 'No rate available for this pair');
        return;
      }
      setConvertResult(json.data);
    } catch {
      notify.error('Conversion failed');
    } finally {
      setConverting(false);
    }
  };

  const fromSymbol = (code: string) => currencies.find(c => c.code === code)?.symbol || '';

  return (
    <div className="max-w-4xl space-y-8">
      {/* Set Rate Form */}
      <div>
        <h2 className="text-base font-semibold text-[var(--ff-text-primary)] mb-4">Set Exchange Rate</h2>
        <div className="p-5 rounded-xl bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)]">
          <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
            <div>
              <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">From Currency</label>
              <select
                value={rateForm.fromCurrency}
                onChange={e => setRateForm(f => ({ ...f, fromCurrency: e.target.value }))}
                className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-violet-500"
              >
                <option value="">Select...</option>
                {currencies.map(c => <option key={c.code} value={c.code}>{c.code} — {c.name}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">To Currency</label>
              <select
                value={rateForm.toCurrency}
                onChange={e => setRateForm(f => ({ ...f, toCurrency: e.target.value }))}
                className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-violet-500"
              >
                <option value="">Select...</option>
                {currencies.map(c => <option key={c.code} value={c.code}>{c.code} — {c.name}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Rate</label>
              <input
                type="number"
                step="any"
                min="0"
                placeholder="e.g. 18.50"
                value={rateForm.rate}
                onChange={e => setRateForm(f => ({ ...f, rate: e.target.value }))}
                className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-violet-500"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Effective Date</label>
              <input
                type="date"
                value={rateForm.effectiveDate}
                onChange={e => setRateForm(f => ({ ...f, effectiveDate: e.target.value }))}
                className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-violet-500"
              />
            </div>
          </div>
          <div className="flex justify-end mt-4">
            <button
              onClick={handleSaveRate}
              disabled={savingRate}
              className="px-4 py-2 bg-violet-600 hover:bg-violet-700 disabled:opacity-50 text-white rounded-lg flex items-center gap-2 text-sm"
            >
              {savingRate ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
              Save Rate
            </button>
          </div>
        </div>
      </div>

      {/* Quick Converter */}
      <div>
        <h2 className="text-base font-semibold text-[var(--ff-text-primary)] mb-4">Quick Converter</h2>
        <div className="p-5 rounded-xl bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)]">
          <div className="flex flex-wrap items-end gap-3">
            <div>
              <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Amount</label>
              <input
                type="number"
                step="any"
                min="0"
                placeholder="100"
                value={convertForm.amount}
                onChange={e => { setConvertForm(f => ({ ...f, amount: e.target.value })); setConvertResult(null); }}
                className="w-36 px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-violet-500"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">From</label>
              <select
                value={convertForm.from}
                onChange={e => { setConvertForm(f => ({ ...f, from: e.target.value })); setConvertResult(null); }}
                className="px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-violet-500"
              >
                {currencies.map(c => <option key={c.code} value={c.code}>{c.code}</option>)}
              </select>
            </div>
            <ArrowRight className="h-4 w-4 text-[var(--ff-text-tertiary)] mb-2" />
            <div>
              <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">To</label>
              <select
                value={convertForm.to}
                onChange={e => { setConvertForm(f => ({ ...f, to: e.target.value })); setConvertResult(null); }}
                className="px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-violet-500"
              >
                {currencies.map(c => <option key={c.code} value={c.code}>{c.code}</option>)}
              </select>
            </div>
            <button
              onClick={handleConvert}
              disabled={converting}
              className="px-4 py-2 bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] hover:border-violet-500 text-[var(--ff-text-primary)] rounded-lg flex items-center gap-2 text-sm transition-colors"
            >
              {converting ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Convert'}
            </button>
            {convertResult && (
              <div className="flex items-center gap-2 px-4 py-2 rounded-lg bg-violet-500/10 border border-violet-500/20">
                <span className="text-xl font-bold text-violet-400">
                  {fromSymbol(convertForm.to)}{convertResult.converted.toLocaleString('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 4 })}
                </span>
                <span className="text-xs text-[var(--ff-text-tertiary)]">@ {convertResult.rate}</span>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Exchange Rates History */}
      <div>
        <h2 className="text-base font-semibold text-[var(--ff-text-primary)] mb-4">Recent Exchange Rates</h2>
        {exchangeRates.length === 0 ? (
          <p className="text-sm text-[var(--ff-text-secondary)] py-4">No exchange rates recorded yet.</p>
        ) : (
          <div className="rounded-xl border border-[var(--ff-border-light)] overflow-hidden">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
                  <th className="text-left px-4 py-2.5 text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">Pair</th>
                  <th className="text-right px-4 py-2.5 text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">Rate</th>
                  <th className="text-left px-4 py-2.5 text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">Effective</th>
                  <th className="text-left px-4 py-2.5 text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">Source</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[var(--ff-border-light)]">
                {exchangeRates.map(rate => (
                  <tr key={rate.id} className="bg-[var(--ff-bg-secondary)] hover:bg-[var(--ff-bg-primary)] transition-colors">
                    <td className="px-4 py-3 font-mono font-semibold text-[var(--ff-text-primary)]">
                      {rate.fromCurrency} <span className="text-[var(--ff-text-tertiary)]">/</span> {rate.toCurrency}
                    </td>
                    <td className="px-4 py-3 text-right font-mono text-[var(--ff-text-primary)]">
                      {rate.rate.toLocaleString('en-ZA', { minimumFractionDigits: 4, maximumFractionDigits: 6 })}
                    </td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{rate.effectiveDate}</td>
                    <td className="px-4 py-3">
                      <span className="px-2 py-0.5 rounded text-xs bg-[var(--ff-bg-primary)] text-[var(--ff-text-tertiary)] capitalize">
                        {rate.source}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * CurrencyList — displays all currencies with toggle and add controls
 * Part of the Multi-Currency Management page
 */

import { useState } from 'react';
import { Plus, Loader2, Check, X, Star } from 'lucide-react';
import { notify } from '@/utils/toast';
import type { Currency } from '@/modules/accounting/services/currencyService';

interface Props {
  currencies: Currency[];
  reportingCurrency: string;
  onRefresh: () => void;
}

interface AddForm {
  code: string;
  name: string;
  symbol: string;
  decimalPlaces: string;
}

const EMPTY_FORM: AddForm = { code: '', name: '', symbol: '', decimalPlaces: '2' };

// 🟢 WORKING: Currency list with inline add form and active toggle
export function CurrencyList({ currencies, reportingCurrency, onRefresh }: Props) {
  const [showAdd, setShowAdd] = useState(false);
  const [form, setForm] = useState<AddForm>(EMPTY_FORM);
  const [saving, setSaving] = useState(false);
  const [toggling, setToggling] = useState<string | null>(null);

  const handleAdd = async () => {
    if (!form.code.trim() || !form.name.trim() || !form.symbol.trim()) {
      notify.error('Code, name, and symbol are required');
      return;
    }
    setSaving(true);
    try {
      const res = await fetch('/api/accounting/currencies', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          code: form.code.trim().toUpperCase(),
          name: form.name.trim(),
          symbol: form.symbol.trim(),
          decimalPlaces: parseInt(form.decimalPlaces, 10) || 2,
        }),
      });
      const json = await res.json();
      if (!res.ok || json.success === false) {
        notify.error(json.message || 'Failed to create currency');
        return;
      }
      notify.success(`Currency ${form.code.toUpperCase()} created`);
      setForm(EMPTY_FORM);
      setShowAdd(false);
      onRefresh();
    } catch {
      notify.error('Failed to create currency');
    } finally {
      setSaving(false);
    }
  };

  const handleToggle = async (currency: Currency) => {
    setToggling(currency.code);
    try {
      const res = await fetch('/api/accounting/currencies', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ code: currency.code, isActive: !currency.isActive }),
      });
      if (!res.ok) {
        notify.error('Failed to update currency');
        return;
      }
      notify.success(`${currency.code} ${!currency.isActive ? 'activated' : 'deactivated'}`);
      onRefresh();
    } catch {
      notify.error('Failed to update currency');
    } finally {
      setToggling(null);
    }
  };

  return (
    <div className="max-w-3xl space-y-4">
      {/* Header row */}
      <div className="flex items-center justify-between">
        <p className="text-sm text-[var(--ff-text-secondary)]">
          {currencies.length} {currencies.length === 1 ? 'currency' : 'currencies'} configured
        </p>
        <button
          onClick={() => setShowAdd(s => !s)}
          className="px-3 py-1.5 bg-violet-600 hover:bg-violet-700 text-white rounded-lg flex items-center gap-1.5 text-sm"
        >
          <Plus className="h-3.5 w-3.5" />
          Add Currency
        </button>
      </div>

      {/* Inline add form */}
      {showAdd && (
        <div className="p-4 rounded-xl border border-violet-500/30 bg-violet-500/5 space-y-4">
          <h3 className="text-sm font-semibold text-[var(--ff-text-primary)]">New Currency</h3>
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
            <div>
              <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Code *</label>
              <input
                type="text"
                maxLength={3}
                placeholder="USD"
                value={form.code}
                onChange={e => setForm(f => ({ ...f, code: e.target.value.toUpperCase() }))}
                className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-violet-500 uppercase"
              />
            </div>
            <div className="col-span-2 sm:col-span-1">
              <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Name *</label>
              <input
                type="text"
                placeholder="US Dollar"
                value={form.name}
                onChange={e => setForm(f => ({ ...f, name: e.target.value }))}
                className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-violet-500"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Symbol *</label>
              <input
                type="text"
                maxLength={4}
                placeholder="$"
                value={form.symbol}
                onChange={e => setForm(f => ({ ...f, symbol: e.target.value }))}
                className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-violet-500"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Decimals</label>
              <input
                type="number"
                min={0}
                max={6}
                value={form.decimalPlaces}
                onChange={e => setForm(f => ({ ...f, decimalPlaces: e.target.value }))}
                className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-violet-500"
              />
            </div>
          </div>
          <div className="flex justify-end gap-2">
            <button
              onClick={() => { setShowAdd(false); setForm(EMPTY_FORM); }}
              className="px-3 py-1.5 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]"
            >
              Cancel
            </button>
            <button
              onClick={handleAdd}
              disabled={saving}
              className="px-4 py-1.5 bg-violet-600 hover:bg-violet-700 disabled:opacity-50 text-white rounded-lg text-sm flex items-center gap-1.5"
            >
              {saving ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Check className="h-3.5 w-3.5" />}
              Save Currency
            </button>
          </div>
        </div>
      )}

      {/* Currency table */}
      {currencies.length === 0 ? (
        <div className="text-center py-10 text-[var(--ff-text-secondary)]">
          No currencies configured
        </div>
      ) : (
        <div className="rounded-xl border border-[var(--ff-border-light)] overflow-hidden">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
                <th className="text-left px-4 py-2.5 text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">Code</th>
                <th className="text-left px-4 py-2.5 text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">Name</th>
                <th className="text-left px-4 py-2.5 text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">Symbol</th>
                <th className="text-left px-4 py-2.5 text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">Decimals</th>
                <th className="text-left px-4 py-2.5 text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">Status</th>
                <th className="px-4 py-2.5" />
              </tr>
            </thead>
            <tbody className="divide-y divide-[var(--ff-border-light)]">
              {currencies.map(currency => (
                <tr key={currency.code} className="bg-[var(--ff-bg-secondary)] hover:bg-[var(--ff-bg-primary)] transition-colors">
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-1.5">
                      <span className="font-mono font-semibold text-[var(--ff-text-primary)]">{currency.code}</span>
                      {currency.code === reportingCurrency && (
                        <span title="Reporting currency">
                          <Star className="h-3 w-3 text-amber-400" />
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-4 py-3 text-[var(--ff-text-primary)]">{currency.name}</td>
                  <td className="px-4 py-3 font-mono text-[var(--ff-text-secondary)]">{currency.symbol}</td>
                  <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{currency.decimalPlaces}</td>
                  <td className="px-4 py-3">
                    <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${
                      currency.isActive
                        ? 'bg-teal-500/10 text-teal-400'
                        : 'bg-[var(--ff-bg-primary)] text-[var(--ff-text-tertiary)]'
                    }`}>
                      {currency.isActive ? 'Active' : 'Inactive'}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-right">
                    {currency.code !== reportingCurrency && (
                      <button
                        onClick={() => handleToggle(currency)}
                        disabled={toggling === currency.code}
                        className={`text-xs px-3 py-1 rounded-lg border transition-colors disabled:opacity-50 ${
                          currency.isActive
                            ? 'border-red-500/30 text-red-400 hover:bg-red-500/10'
                            : 'border-teal-500/30 text-teal-400 hover:bg-teal-500/10'
                        }`}
                      >
                        {toggling === currency.code
                          ? <Loader2 className="h-3 w-3 animate-spin inline" />
                          : currency.isActive ? <><X className="h-3 w-3 inline mr-1" />Deactivate</> : <><Check className="h-3 w-3 inline mr-1" />Activate</>
                        }
                      </button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

/**
 * BankTxAttachmentsModal
 *
 * View, upload, and delete file attachments (receipts, invoices, PDFs) for a
 * single bank transaction. Files are stored as base64 data URLs in the
 * bank_transaction_attachments table (suitable for small receipts ≤ 2 MB).
 *
 * Props:
 *   bankTransactionId     — UUID of the target bank transaction
 *   transactionDescription — Optional label shown in the modal header
 *   onClose               — Dismiss callback
 */

import { useState, useEffect, useRef, useCallback } from 'react';
import { X, Paperclip, Trash2, Upload, FileImage, FileText, AlertCircle, Loader2 } from 'lucide-react';
import { notify } from '@/utils/toast';

// ── Types ─────────────────────────────────────────────────────────────────────

interface Attachment {
  id: string;
  bank_transaction_id: string;
  file_url: string;
  file_name: string;
  file_size: number | null;
  uploaded_by: string | null;
  created_at: string;
}

interface Props {
  bankTransactionId: string;
  transactionDescription?: string;
  onClose: () => void;
}

// ── Constants ─────────────────────────────────────────────────────────────────

const MAX_BYTES = 2 * 1024 * 1024; // 2 MB
const ACCEPT = '.jpg,.jpeg,.png,.pdf';
const ACCEPTED_MIME = ['image/jpeg', 'image/png', 'application/pdf'];

// ── Helpers ───────────────────────────────────────────────────────────────────

function formatBytes(bytes: number | null): string {
  if (bytes === null) return '';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString('en-ZA', {
    day: '2-digit', month: 'short', year: 'numeric',
  });
}

function fileIcon(name: string): 'image' | 'pdf' | 'generic' {
  const ext = name.split('.').pop()?.toLowerCase() ?? '';
  if (['jpg', 'jpeg', 'png'].includes(ext)) return 'image';
  if (ext === 'pdf') return 'pdf';
  return 'generic';
}

function readFileAsDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = () => reject(new Error('Failed to read file'));
    reader.readAsDataURL(file);
  });
}

// ── Component ─────────────────────────────────────────────────────────────────

// 🟢 WORKING: Attachment list + upload modal for bank transactions
export function BankTxAttachmentsModal({ bankTransactionId, transactionDescription, onClose }: Props) {
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // ── Fetch attachment list ──────────────────────────────────────────────────
  const fetchAttachments = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch(
        `/api/accounting/bank-tx-attachments?bankTransactionId=${encodeURIComponent(bankTransactionId)}`,
        { credentials: 'include' },
      );
      const json = await res.json() as { success: boolean; data: Attachment[] };
      if (!res.ok || !json.success) throw new Error('Failed to load attachments');
      setAttachments(json.data);
    } catch {
      notify.error('Could not load attachments');
    } finally {
      setLoading(false);
    }
  }, [bankTransactionId]);

  useEffect(() => { void fetchAttachments(); }, [fetchAttachments]);

  // ── Upload ─────────────────────────────────────────────────────────────────
  const handleUpload = useCallback(async (file: File) => {
    if (!ACCEPTED_MIME.includes(file.type)) {
      notify.error('Only JPG, PNG and PDF files are accepted');
      return;
    }
    if (file.size > MAX_BYTES) {
      notify.error('File exceeds the 2 MB limit');
      return;
    }

    setUploading(true);
    try {
      const fileData = await readFileAsDataUrl(file);
      const res = await fetch('/api/accounting/bank-tx-attachments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          bankTransactionId,
          fileName: file.name,
          fileData,
          fileSize: file.size,
        }),
      });
      const json = await res.json() as { success: boolean; message?: string };
      if (!res.ok || !json.success) throw new Error(json.message ?? 'Upload failed');
      notify.success(`${file.name} uploaded`);
      await fetchAttachments();
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Upload failed');
    } finally {
      setUploading(false);
    }
  }, [bankTransactionId, fetchAttachments]);

  // ── File input change ──────────────────────────────────────────────────────
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) void handleUpload(file);
    e.target.value = '';
  };

  // ── Drag-and-drop ──────────────────────────────────────────────────────────
  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    const file = e.dataTransfer.files?.[0];
    if (file) void handleUpload(file);
  };

  // ── Delete ─────────────────────────────────────────────────────────────────
  const handleDelete = async (id: string, name: string) => {
    setDeletingId(id);
    try {
      const res = await fetch(
        `/api/accounting/bank-tx-attachments?id=${encodeURIComponent(id)}`,
        { method: 'DELETE', credentials: 'include' },
      );
      const json = await res.json() as { success: boolean; message?: string };
      if (!res.ok || !json.success) throw new Error(json.message ?? 'Delete failed');
      notify.success(`${name} removed`);
      setAttachments(prev => prev.filter(a => a.id !== id));
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Delete failed');
    } finally {
      setDeletingId(null);
    }
  };

  // ── Render ─────────────────────────────────────────────────────────────────
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
      <div
        className="w-full max-w-lg bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-xl shadow-2xl flex flex-col max-h-[85vh]"
        onClick={e => e.stopPropagation()}
      >
        {/* ── Header ─────────────────────────────────────────────────────── */}
        <div className="flex items-center gap-3 px-5 py-4 border-b border-[var(--ff-border-light)] shrink-0">
          <div className="p-2 rounded-lg bg-blue-500/10">
            <Paperclip className="h-4 w-4 text-blue-400" />
          </div>
          <div className="flex-1 min-w-0">
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)]">Attachments</h2>
            {transactionDescription && (
              <p className="text-xs text-[var(--ff-text-tertiary)] truncate">{transactionDescription}</p>
            )}
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded hover:bg-[var(--ff-bg-primary)] text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)]"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* ── Upload zone ────────────────────────────────────────────────── */}
        <div className="px-5 pt-4 shrink-0">
          <div
            onDragOver={e => { e.preventDefault(); setDragOver(true); }}
            onDragLeave={() => setDragOver(false)}
            onDrop={handleDrop}
            onClick={() => !uploading && fileInputRef.current?.click()}
            className={`relative flex flex-col items-center justify-center gap-2 rounded-lg border-2 border-dashed py-5 cursor-pointer transition-colors ${
              dragOver
                ? 'border-blue-400 bg-blue-500/10'
                : 'border-[var(--ff-border-light)] hover:border-[var(--ff-text-tertiary)] bg-[var(--ff-bg-primary)]'
            }`}
          >
            {uploading ? (
              <>
                <Loader2 className="h-5 w-5 text-blue-400 animate-spin" />
                <span className="text-xs text-[var(--ff-text-secondary)]">Uploading…</span>
              </>
            ) : (
              <>
                <Upload className="h-5 w-5 text-[var(--ff-text-tertiary)]" />
                <p className="text-xs text-[var(--ff-text-secondary)] text-center">
                  Drag &amp; drop or{' '}
                  <span className="text-blue-400 font-medium">click to browse</span>
                </p>
                <p className="text-[10px] text-[var(--ff-text-tertiary)]">
                  JPG, PNG, PDF — max 2 MB
                </p>
              </>
            )}
            <input
              ref={fileInputRef}
              type="file"
              accept={ACCEPT}
              className="sr-only"
              onChange={handleFileChange}
              disabled={uploading}
            />
          </div>
        </div>

        {/* ── Attachment list ─────────────────────────────────────────────── */}
        <div className="flex-1 overflow-y-auto px-5 py-4 space-y-2">
          {loading ? (
            <div className="flex items-center justify-center py-8 gap-2 text-[var(--ff-text-tertiary)]">
              <Loader2 className="h-4 w-4 animate-spin" />
              <span className="text-xs">Loading…</span>
            </div>
          ) : attachments.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-8 gap-2 text-[var(--ff-text-tertiary)]">
              <AlertCircle className="h-5 w-5" />
              <span className="text-xs">No attachments yet</span>
            </div>
          ) : (
            attachments.map(att => {
              const icon = fileIcon(att.file_name);
              const isDeleting = deletingId === att.id;
              return (
                <div
                  key={att.id}
                  className="flex items-center gap-3 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)] px-3 py-2.5"
                >
                  {/* File type icon */}
                  <div className="shrink-0 p-1.5 rounded bg-[var(--ff-bg-secondary)]">
                    {icon === 'image' ? (
                      <FileImage className="h-4 w-4 text-blue-400" />
                    ) : icon === 'pdf' ? (
                      <FileText className="h-4 w-4 text-orange-400" />
                    ) : (
                      <Paperclip className="h-4 w-4 text-[var(--ff-text-tertiary)]" />
                    )}
                  </div>

                  {/* Name + meta */}
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-medium text-[var(--ff-text-primary)] truncate">
                      {att.file_name}
                    </p>
                    <p className="text-[10px] text-[var(--ff-text-tertiary)]">
                      {formatBytes(att.file_size)}{att.file_size ? ' · ' : ''}{formatDate(att.created_at)}
                    </p>
                  </div>

                  {/* Download link */}
                  <a
                    href={att.file_url}
                    download={att.file_name}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="shrink-0 p-1.5 rounded hover:bg-blue-500/10 text-[var(--ff-text-tertiary)] hover:text-blue-400 transition-colors"
                    title="Download"
                    onClick={e => e.stopPropagation()}
                  >
                    <Upload className="h-3.5 w-3.5 rotate-180" />
                  </a>

                  {/* Delete */}
                  <button
                    disabled={isDeleting}
                    onClick={() => void handleDelete(att.id, att.file_name)}
                    className="shrink-0 p-1.5 rounded hover:bg-red-500/10 text-[var(--ff-text-tertiary)] hover:text-red-400 disabled:opacity-40 transition-colors"
                    title="Remove"
                  >
                    {isDeleting
                      ? <Loader2 className="h-3.5 w-3.5 animate-spin" />
                      : <Trash2 className="h-3.5 w-3.5" />
                    }
                  </button>
                </div>
              );
            })
          )}
        </div>

        {/* ── Footer ─────────────────────────────────────────────────────── */}
        <div className="border-t border-[var(--ff-border-light)] px-5 py-3 flex items-center justify-between shrink-0">
          <span className="text-xs text-[var(--ff-text-tertiary)]">
            {attachments.length} attachment{attachments.length !== 1 ? 's' : ''}
          </span>
          <button
            onClick={onClose}
            className="px-4 py-1.5 rounded text-xs border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * Find & Match Modal — manually match a bank transaction to a candidate
 * (supplier invoice, purchase order, or GL journal line).
 * Fetches scored candidates from /api/accounting/bank-match-candidates and
 * confirms the selection via /api/accounting/bank-match-confirm.
 */

import { useState, useEffect } from 'react';
import { X, Search, CheckCircle, FileText, ShoppingCart, BookOpen, Loader2 } from 'lucide-react';
import { notify } from '@/utils/toast';
import type { MatchCandidate, CandidateType } from '@/modules/accounting/types/bank-match.types';

interface Transaction {
  id: string;
  description?: string;
  amount: number;
  transactionDate: string;
}

interface Props {
  transaction: Transaction;
  onClose: () => void;
  /** Called after a successful match — parent should refresh the transaction list */
  onMatch: (candidateType: CandidateType, candidateId: string) => void;
}

function fmtCurrency(n: number): string {
  return new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);
}

const TYPE_META: Record<CandidateType, { label: string; icon: typeof FileText; colour: string }> = {
  supplier_invoice: { label: 'Invoice', icon: FileText, colour: 'text-blue-400 bg-blue-400/10' },
  purchase_order: { label: 'PO', icon: ShoppingCart, colour: 'text-amber-400 bg-amber-400/10' },
  journal_line: { label: 'Journal', icon: BookOpen, colour: 'text-purple-400 bg-purple-400/10' },
};

const GROUP_ORDER: CandidateType[] = ['supplier_invoice', 'purchase_order', 'journal_line'];
const GROUP_TITLES: Record<CandidateType, string> = {
  supplier_invoice: 'Supplier Invoices',
  purchase_order: 'Purchase Orders',
  journal_line: 'Journal Lines',
};

export function FindMatchModal({ transaction, onClose, onMatch }: Props) {
  const [candidates, setCandidates] = useState<MatchCandidate[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selected, setSelected] = useState<MatchCandidate | null>(null);
  const [confirming, setConfirming] = useState(false);
  const [search, setSearch] = useState('');

  useEffect(() => {
    let cancelled = false;

    const fetchCandidates = async () => {
      setLoading(true);
      setError(null);
      try {
        const res = await fetch(
          `/api/accounting/bank-match-candidates?bankTransactionId=${encodeURIComponent(transaction.id)}`,
          { credentials: 'include' },
        );
        const json = await res.json() as { success: boolean; data?: { candidates: MatchCandidate[] }; error?: { message: string } };
        if (!res.ok || !json.success) {
          throw new Error(json.error?.message ?? 'Failed to load candidates');
        }
        if (!cancelled) {
          setCandidates(json.data?.candidates ?? []);
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : 'Failed to load candidates');
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    void fetchCandidates();
    return () => { cancelled = true; };
  }, [transaction.id]);

  const filtered = candidates.filter(c => {
    if (!search) return true;
    const q = search.toLowerCase();
    return c.label.toLowerCase().includes(q) || fmtCurrency(c.amount).includes(q);
  });

  const grouped = GROUP_ORDER.reduce<Record<CandidateType, MatchCandidate[]>>((acc, type) => {
    acc[type] = filtered.filter(c => c.type === type);
    return acc;
  }, { supplier_invoice: [], purchase_order: [], journal_line: [] });

  const handleConfirm = async () => {
    if (!selected) return;
    setConfirming(true);
    try {
      const res = await fetch('/api/accounting/bank-match-confirm', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          bankTransactionId: transaction.id,
          candidateType: selected.type,
          candidateId: selected.id,
        }),
      });
      const json = await res.json() as { success: boolean; error?: { message: string } };
      if (!res.ok || !json.success) {
        throw new Error(json.error?.message ?? 'Match failed');
      }
      const matchedMeta = TYPE_META[selected.type];
      notify.success(`Matched to ${matchedMeta?.label ?? selected.type}: ${selected.label}`);
      onMatch(selected.type, selected.id);
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Match confirmation failed');
    } finally {
      setConfirming(false);
    }
  };

  const txIsExact = (c: MatchCandidate) => Math.abs(Math.abs(c.amount) - Math.abs(transaction.amount)) < 0.01;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
      <div className="w-full max-w-xl bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-xl shadow-2xl flex flex-col max-h-[85vh]">

        {/* Header */}
        <div className="flex items-center gap-3 px-5 py-4 border-b border-[var(--ff-border-light)]">
          <div className="p-2 rounded-lg bg-teal-500/10">
            <Search className="h-4 w-4 text-teal-400" />
          </div>
          <div className="flex-1 min-w-0">
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)]">Find &amp; Match</h2>
            <p className="text-xs text-[var(--ff-text-tertiary)] truncate">
              {transaction.transactionDate} &middot; {transaction.description ?? 'No description'}
            </p>
          </div>
          <div className="text-right mr-2">
            <p className={`text-base font-bold font-mono ${transaction.amount < 0 ? 'text-red-400' : 'text-teal-400'}`}>
              {fmtCurrency(transaction.amount)}
            </p>
          </div>
          <button onClick={onClose} className="p-1.5 rounded hover:bg-[var(--ff-bg-primary)] text-[var(--ff-text-tertiary)]">
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Search bar */}
        <div className="px-4 pt-3 pb-2">
          <div className="relative">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-[var(--ff-text-tertiary)]" />
            <input
              type="text"
              placeholder="Filter candidates…"
              value={search}
              onChange={e => setSearch(e.target.value)}
              className="w-full pl-8 pr-3 py-1.5 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-primary)] focus:outline-none focus:border-blue-500"
            />
          </div>
        </div>

        {/* Candidate list */}
        <div className="overflow-y-auto flex-1 px-4 pb-3 space-y-4">
          {loading && (
            <div className="flex items-center justify-center py-10 gap-2 text-[var(--ff-text-tertiary)]">
              <Loader2 className="h-4 w-4 animate-spin" />
              <span className="text-xs">Loading candidates…</span>
            </div>
          )}

          {error && (
            <div className="text-xs text-red-400 py-4 text-center">{error}</div>
          )}

          {!loading && !error && filtered.length === 0 && (
            <div className="text-xs text-[var(--ff-text-tertiary)] py-4 text-center">
              No candidates found. Try importing the corresponding document first.
            </div>
          )}

          {!loading && !error && GROUP_ORDER.map(type => {
            // Safe non-null lookups — GROUP_ORDER and TYPE_META are both keyed by CandidateType
            const group: MatchCandidate[] = grouped[type] ?? [];
            if (group.length === 0) return null;
            const meta = TYPE_META[type]!;
            const Icon = meta.icon;
            return (
              <div key={type}>
                <p className="text-[10px] font-semibold uppercase tracking-wide text-[var(--ff-text-tertiary)] mb-1.5">
                  {GROUP_TITLES[type]}
                </p>
                <div className="space-y-1">
                  {group.map(c => {
                    const exact = txIsExact(c);
                    const isSelected = selected?.id === c.id && selected?.type === c.type;
                    return (
                      <button
                        key={`${c.type}-${c.id}`}
                        onClick={() => setSelected(isSelected ? null : c)}
                        className={`w-full text-left rounded-lg border px-3 py-2 transition-colors ${
                          isSelected
                            ? 'border-blue-500 bg-blue-500/10'
                            : 'border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)] hover:border-[var(--ff-border-medium)]'
                        }`}
                      >
                        <div className="flex items-center gap-2">
                          {/* Type badge */}
                          <span className={`inline-flex items-center gap-1 text-[10px] font-medium px-1.5 py-0.5 rounded ${meta.colour}`}>
                            <Icon className="h-2.5 w-2.5" />
                            {meta.label}
                          </span>

                          {/* Label */}
                          <span className="flex-1 text-xs text-[var(--ff-text-primary)] truncate">{c.label}</span>

                          {/* Amount */}
                          <span className={`text-xs font-mono font-semibold ${exact ? 'text-teal-400' : 'text-[var(--ff-text-primary)]'}`}>
                            {fmtCurrency(c.amount)}
                            {exact && <span className="ml-1 text-[10px] text-teal-400">exact</span>}
                          </span>
                        </div>

                        {/* Date + score bar */}
                        <div className="flex items-center gap-3 mt-1.5">
                          <span className="text-[10px] text-[var(--ff-text-tertiary)]">{c.date}</span>
                          <div className="flex-1 h-1 rounded-full bg-[var(--ff-bg-secondary)] overflow-hidden">
                            <div
                              className="h-full rounded-full bg-blue-500"
                              style={{ width: `${Math.min(100, c.score)}%` }}
                            />
                          </div>
                          <span className="text-[10px] text-[var(--ff-text-tertiary)] w-8 text-right">{c.score}pt</span>
                        </div>
                      </button>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>

        {/* Footer */}
        <div className="border-t border-[var(--ff-border-light)] px-5 py-3 flex items-center justify-between">
          <p className="text-xs text-[var(--ff-text-tertiary)]">
            {selected
              ? `Selected: ${TYPE_META[selected.type]?.label ?? selected.type} — ${selected.label}`
              : 'Select a candidate to match'}
          </p>
          <div className="flex items-center gap-2">
            <button
              onClick={onClose}
              className="px-3 py-1.5 rounded text-xs text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)]"
            >
              Cancel
            </button>
            <button
              onClick={handleConfirm}
              disabled={!selected || confirming}
              className="inline-flex items-center gap-1.5 px-4 py-1.5 rounded text-xs font-medium bg-teal-600 hover:bg-teal-700 disabled:opacity-40 text-white transition-colors"
            >
              {confirming
                ? <><Loader2 className="h-3 w-3 animate-spin" /> Confirming…</>
                : <><CheckCircle className="h-3 w-3" /> Confirm Match</>
              }
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * Inline entity creation modal — create GL Accounts, Suppliers, or Customers
 * directly from the bank transaction allocation dropdown (Sage-style).
 */

import { useState } from 'react';
import { Plus, X, Loader2 } from 'lucide-react';
import { notify } from '@/utils/toast';
import type { AllocType } from './BankTxTable';

interface Props {
  type: AllocType;
  onClose: () => void;
  onCreated: (entity: { id: string; code?: string; name: string }) => void;
}

const ACCOUNT_TYPES = [
  { value: 'expense', label: 'Expense', nb: 'debit' },
  { value: 'asset', label: 'Asset', nb: 'debit' },
  { value: 'liability', label: 'Liability', nb: 'credit' },
  { value: 'revenue', label: 'Revenue', nb: 'credit' },
  { value: 'equity', label: 'Equity', nb: 'credit' },
];

const INPUT = 'w-full px-3 py-2 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-sm text-[var(--ff-text-primary)] focus:outline-none focus:border-teal-500';
const LABEL = 'text-xs text-[var(--ff-text-tertiary)] mb-1 block';

export function CreateEntityModal({ type, onClose, onCreated }: Props) {
  const [saving, setSaving] = useState(false);

  // Account fields
  const [acctCode, setAcctCode] = useState('');
  const [acctName, setAcctName] = useState('');
  const [acctType, setAcctType] = useState('expense');

  // Supplier fields
  const [supName, setSupName] = useState('');
  const [supEmail, setSupEmail] = useState('');
  const [supPhone, setSupPhone] = useState('');

  // Customer fields
  const [custName, setCustName] = useState('');
  const [custEmail, setCustEmail] = useState('');
  const [custPhone, setCustPhone] = useState('');

  const title = type === 'account' ? 'New GL Account'
    : type === 'supplier' ? 'New Supplier' : 'New Customer';

  const canSave = type === 'account'
    ? !!(acctCode.trim() && acctName.trim())
    : type === 'supplier'
      ? !!(supName.trim() && supEmail.trim())
      : !!custName.trim();

  const handleSave = async () => {
    setSaving(true);
    try {
      let entity: { id: string; code?: string; name: string };

      if (type === 'account') {
        const nb = ACCOUNT_TYPES.find(t => t.value === acctType)?.nb || 'debit';
        const res = await fetch('/api/accounting/chart-of-accounts', {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
          body: JSON.stringify({
            accountCode: acctCode.trim(), accountName: acctName.trim(),
            accountType: acctType, normalBalance: nb,
          }),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.message || json.error?.message || 'Failed to create account');
        const d = json.data;
        entity = { id: d.id, code: d.accountCode, name: d.accountName };
      } else if (type === 'supplier') {
        const res = await fetch('/api/suppliers', {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
          body: JSON.stringify({ data: {
            name: supName.trim(),
            email: supEmail.trim(),
            phone: supPhone.trim() || undefined,
          }}),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.message || 'Failed to create supplier');
        const d = json.data;
        entity = { id: String(d.id), code: d.code, name: supName.trim() };
      } else {
        const res = await fetch('/api/clients', {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
          body: JSON.stringify({
            company_name: custName.trim(),
            email: custEmail.trim() || undefined,
            phone: custPhone.trim() || undefined,
          }),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.message || 'Failed to create customer');
        const d = json.data;
        entity = { id: d.id, name: custName.trim() };
      }

      notify.success(`${title.replace('New ', '')} created`);
      onCreated(entity);
    } catch (e) {
      notify.error(e instanceof Error ? e.message : 'Failed to create');
    } finally {
      setSaving(false);
    }
  };

  const nb = ACCOUNT_TYPES.find(t => t.value === acctType)?.nb;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/60">
      <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-xl shadow-2xl w-full max-w-md mx-4">
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-3 border-b border-[var(--ff-border-light)]">
          <div className="flex items-center gap-2">
            <Plus className="h-4 w-4 text-teal-400" />
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)]">{title}</h2>
          </div>
          <button onClick={onClose} className="p-1 rounded hover:bg-[var(--ff-bg-primary)] text-[var(--ff-text-tertiary)]">
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Body */}
        <div className="px-5 py-4 space-y-3">
          {type === 'account' && (
            <>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className={LABEL}>Account Code *</label>
                  <input type="text" value={acctCode} onChange={e => setAcctCode(e.target.value)}
                    placeholder="e.g. 5250" className={`${INPUT} font-mono`} autoFocus />
                </div>
                <div>
                  <label className={LABEL}>Type *</label>
                  <select value={acctType} onChange={e => setAcctType(e.target.value)} className={INPUT}>
                    {ACCOUNT_TYPES.map(t => <option key={t.value} value={t.value}>{t.label}</option>)}
                  </select>
                </div>
              </div>
              <div>
                <label className={LABEL}>Account Name *</label>
                <input type="text" value={acctName} onChange={e => setAcctName(e.target.value)}
                  placeholder="e.g. Cleaning & Maintenance" className={INPUT} />
              </div>
              <div className="flex items-center gap-2 text-xs text-[var(--ff-text-tertiary)]">
                Normal balance:&nbsp;
                <span className={nb === 'debit' ? 'text-red-400' : 'text-teal-400'}>
                  {nb === 'debit' ? 'Debit' : 'Credit'}
                </span>
              </div>
            </>
          )}

          {type === 'supplier' && (
            <>
              <div>
                <label className={LABEL}>Supplier Name *</label>
                <input type="text" value={supName} onChange={e => setSupName(e.target.value)}
                  placeholder="e.g. ACME Trading" className={INPUT} autoFocus />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className={LABEL}>Email *</label>
                  <input type="email" value={supEmail} onChange={e => setSupEmail(e.target.value)}
                    placeholder="info@supplier.co.za" className={INPUT} />
                </div>
                <div>
                  <label className={LABEL}>Phone</label>
                  <input type="tel" value={supPhone} onChange={e => setSupPhone(e.target.value)}
                    placeholder="012 345 6789" className={INPUT} />
                </div>
              </div>
            </>
          )}

          {type === 'customer' && (
            <>
              <div>
                <label className={LABEL}>Company Name *</label>
                <input type="text" value={custName} onChange={e => setCustName(e.target.value)}
                  placeholder="e.g. Fibertime" className={INPUT} autoFocus />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className={LABEL}>Email</label>
                  <input type="email" value={custEmail} onChange={e => setCustEmail(e.target.value)}
                    placeholder="client@example.com" className={INPUT} />
                </div>
                <div>
                  <label className={LABEL}>Phone</label>
                  <input type="tel" value={custPhone} onChange={e => setCustPhone(e.target.value)}
                    placeholder="012 345 6789" className={INPUT} />
                </div>
              </div>
            </>
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-end gap-2 px-5 py-3 border-t border-[var(--ff-border-light)]">
          <button onClick={onClose}
            className="px-4 py-1.5 rounded text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
            Cancel
          </button>
          <button onClick={handleSave} disabled={saving || !canSave}
            className="px-4 py-1.5 rounded bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white text-sm font-medium flex items-center gap-1.5">
            {saving && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
            Create
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * Create Rule Modal — opens pre-filled from a bank transaction row.
 * Extracts a recurring pattern from the description, lets user pick GL account,
 * allocation type (account/supplier/customer), and shows a live preview.
 */

import { useState, useEffect, useRef } from 'react';
import { X, Search, BookmarkPlus, Loader2 } from 'lucide-react';
import { notify } from '@/utils/toast';
import type { BankTx, SelectOption } from './BankTxTable';
import type { RuleMatchType, RuleVatCode } from '@/modules/accounting/types/bank.types';

const VAT_OPTIONS: { value: RuleVatCode; label: string }[] = [
  { value: 'none', label: 'No VAT' },
  { value: 'standard', label: 'Standard 15%' },
  { value: 'zero_rated', label: 'Zero Rated' },
  { value: 'exempt', label: 'Exempt' },
];

type AllocType = 'account' | 'supplier' | 'customer';

interface Props {
  transaction: BankTx;
  bankAccountId: string;
  glAccounts: SelectOption[];
  suppliers?: SelectOption[];
  clients?: SelectOption[];
  onClose: () => void;
  onCreated: () => void;
}

/**
 * Strip unique references, dates, card numbers from a transaction description
 * to extract the recurring core pattern for rule matching.
 * Exported so other components (e.g. allocation flow) can derive the same pattern.
 */
export function extractPattern(desc: string): string {
  let p = desc;
  p = p.replace(/[a-f0-9]{8,}/gi, '');
  p = p.replace(/\d{4}[-/]\d{2}[-/]\d{2}/g, '');
  p = p.replace(/\d{2}[-/]\d{2}[-/]\d{4}/g, '');
  p = p.replace(/\d{8}/g, '');
  p = p.replace(/\d{4,}/g, '');
  p = p.replace(/\/Cmd\s+\w\b/gi, '');
  p = p.replace(/\s{2,}/g, ' ').trim();
  p = p.replace(/[/\s]+$/, '');
  return p;
}

/** Reusable searchable dropdown for GL accounts, suppliers, or customers */
function EntityPicker({
  label, placeholder, options, selected, onSelect,
}: {
  label: string; placeholder: string; options: SelectOption[];
  selected: SelectOption | null; onSelect: (o: SelectOption) => void;
}) {
  const [search, setSearch] = useState('');
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const h = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', h);
    return () => document.removeEventListener('mousedown', h);
  }, []);

  const filtered = search
    ? options.filter(o =>
        (o.code || '').toLowerCase().includes(search.toLowerCase()) ||
        o.name.toLowerCase().includes(search.toLowerCase())
      )
    : options;

  return (
    <div ref={ref}>
      <label className="text-xs text-[var(--ff-text-tertiary)] mb-1 block">{label}</label>
      <div className="relative">
        <button
          onClick={() => { setOpen(!open); setSearch(''); }}
          className={`w-full text-left px-3 py-2 rounded border text-sm ${
            selected
              ? 'bg-[var(--ff-bg-primary)] border-[var(--ff-border-light)] text-[var(--ff-text-primary)]'
              : 'bg-[var(--ff-bg-primary)] border-amber-500/40 text-amber-400'
          }`}
        >
          {selected ? `${selected.code || ''} ${selected.name}`.trim() : placeholder}
        </button>
        {open && (
          <div className="absolute z-50 top-full left-0 mt-1 w-full bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg shadow-xl">
            <div className="p-2">
              <div className="relative">
                <Search className="absolute left-2 top-1/2 -translate-y-1/2 h-3 w-3 text-[var(--ff-text-tertiary)]" />
                <input
                  type="text"
                  placeholder={`Search...`}
                  value={search}
                  onChange={e => setSearch(e.target.value)}
                  className="w-full pl-7 pr-2 py-1.5 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-primary)] focus:outline-none focus:border-blue-500"
                  autoFocus
                />
              </div>
            </div>
            <div className="max-h-48 overflow-y-auto">
              {filtered.slice(0, 50).map(o => (
                <button
                  key={o.id}
                  onClick={() => { onSelect(o); setOpen(false); }}
                  className="w-full text-left px-3 py-1.5 hover:bg-[var(--ff-bg-primary)] text-xs flex items-center gap-2"
                >
                  {o.code && <span className="font-mono text-[var(--ff-text-tertiary)] w-10 shrink-0">{o.code}</span>}
                  <span className="text-[var(--ff-text-primary)] truncate">{o.name}</span>
                </button>
              ))}
              {filtered.length === 0 && (
                <div className="px-3 py-2 text-xs text-[var(--ff-text-tertiary)]">No results found</div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export function CreateRuleModal({ transaction, bankAccountId, glAccounts, suppliers = [], clients = [], onClose, onCreated }: Props) {
  const [pattern, setPattern] = useState(() => extractPattern(transaction.description || ''));
  const [matchType, setMatchType] = useState<RuleMatchType>('contains');
  const [ruleName, setRuleName] = useState(() => extractPattern(transaction.description || ''));
  const [autoCreateEntry, setAutoCreateEntry] = useState(false);

  const [allocType, setAllocType] = useState<AllocType>('account');
  const [vatCode, setVatCode] = useState<RuleVatCode>('none');
  const [selectedGl, setSelectedGl] = useState<SelectOption | null>(null);
  const [selectedSupplier, setSelectedSupplier] = useState<SelectOption | null>(null);
  const [selectedClient, setSelectedClient] = useState<SelectOption | null>(null);

  const [matchCount, setMatchCount] = useState<number | null>(null);
  const [previewLoading, setPreviewLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  // Live preview — debounced query as user edits pattern
  useEffect(() => {
    if (!pattern.trim()) { setMatchCount(0); return; }
    setPreviewLoading(true);
    const timer = setTimeout(async () => {
      try {
        const params = new URLSearchParams({ pattern, matchType, bankAccountId });
        const res = await fetch(`/api/accounting/bank-rules-preview?${params}`);
        const json = await res.json();
        setMatchCount(json.data?.matchCount ?? 0);
      } catch {
        setMatchCount(null);
      } finally {
        setPreviewLoading(false);
      }
    }, 400);
    return () => clearTimeout(timer);
  }, [pattern, matchType, bankAccountId]);

  // Clear entity selection when switching alloc type
  useEffect(() => {
    setSelectedSupplier(null);
    setSelectedClient(null);
  }, [allocType]);

  const needsGlAccount = allocType === 'account';

  const handleSave = async () => {
    if (!pattern.trim()) { notify.error('Pattern is required'); return; }
    if (needsGlAccount && !selectedGl) { notify.error('Select a GL account'); return; }
    if (allocType === 'supplier' && !selectedSupplier) { notify.error('Select a supplier'); return; }
    if (allocType === 'customer' && !selectedClient) { notify.error('Select a customer'); return; }
    setSaving(true);
    try {
      const body: Record<string, unknown> = {
        ruleName: ruleName.trim() || pattern.trim(),
        matchField: 'description',
        matchType,
        matchPattern: pattern.trim(),
        autoCreateEntry,
        vatCode,
      };
      // GL account only needed for 'account' type — supplier/customer use AP/AR automatically
      if (needsGlAccount && selectedGl) body.glAccountId = selectedGl.id;
      if (allocType === 'supplier' && selectedSupplier) body.supplierId = selectedSupplier.id;
      if (allocType === 'customer' && selectedClient) body.clientId = selectedClient.id;

      const res = await fetch('/api/accounting/bank-rules', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify(body),
      });
      const json = await res.json();
      if (!res.ok || json.success === false) throw new Error(json.message || 'Failed to create rule');
      notify.success('Rule created');
      onCreated();
    } catch (e) {
      notify.error(e instanceof Error ? e.message : 'Failed to create rule');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60">
      <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-xl shadow-2xl w-full max-w-lg mx-4">
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-3 border-b border-[var(--ff-border-light)]">
          <div className="flex items-center gap-2">
            <BookmarkPlus className="h-4 w-4 text-yellow-400" />
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)]">Create Categorisation Rule</h2>
          </div>
          <button onClick={onClose} className="p-1 rounded hover:bg-[var(--ff-bg-primary)] text-[var(--ff-text-tertiary)]">
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Body */}
        <div className="px-5 py-4 space-y-4">
          {/* Source description */}
          <div>
            <label className="text-xs text-[var(--ff-text-tertiary)] mb-1 block">Source Description</label>
            <p className="text-xs text-[var(--ff-text-secondary)] bg-[var(--ff-bg-primary)] rounded px-3 py-2 font-mono break-all">
              {transaction.description || '\u2014'}
            </p>
          </div>

          {/* Pattern */}
          <div>
            <label className="text-xs text-[var(--ff-text-tertiary)] mb-1 block">Match Pattern</label>
            <input
              type="text"
              value={pattern}
              onChange={e => setPattern(e.target.value)}
              className="w-full px-3 py-2 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-sm text-[var(--ff-text-primary)] focus:outline-none focus:border-blue-500"
            />
            <div className="flex items-center gap-2 mt-1.5">
              {previewLoading ? (
                <Loader2 className="h-3 w-3 animate-spin text-[var(--ff-text-tertiary)]" />
              ) : matchCount !== null ? (
                <span className={`text-xs font-medium ${matchCount > 0 ? 'text-teal-400' : 'text-[var(--ff-text-tertiary)]'}`}>
                  Would match <strong>{matchCount}</strong> transaction{matchCount !== 1 ? 's' : ''}
                </span>
              ) : null}
            </div>
          </div>

          {/* Match type */}
          <div>
            <label className="text-xs text-[var(--ff-text-tertiary)] mb-1 block">Match Type</label>
            <select
              value={matchType}
              onChange={e => setMatchType(e.target.value as RuleMatchType)}
              className="w-full px-3 py-2 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-sm text-[var(--ff-text-primary)]"
            >
              <option value="contains">Contains</option>
              <option value="starts_with">Starts With</option>
              <option value="ends_with">Ends With</option>
              <option value="exact">Exact Match</option>
            </select>
          </div>

          {/* Allocation Type */}
          <div>
            <label className="text-xs text-[var(--ff-text-tertiary)] mb-1 block">Allocation Type</label>
            <div className="flex gap-1">
              {(['account', 'supplier', 'customer'] as AllocType[]).map(t => (
                <button
                  key={t}
                  onClick={() => setAllocType(t)}
                  className={`flex-1 px-3 py-1.5 rounded text-xs font-medium transition-colors ${
                    allocType === t
                      ? 'bg-teal-600 text-white'
                      : 'bg-[var(--ff-bg-primary)] text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)]'
                  }`}
                >
                  {t === 'account' ? 'Account' : t === 'supplier' ? 'Supplier' : 'Customer'}
                </button>
              ))}
            </div>
          </div>

          {/* GL Account — only for 'account' type; supplier/customer use AP/AR automatically */}
          {needsGlAccount && (
            <EntityPicker
              label="GL Account"
              placeholder="Select GL Account..."
              options={glAccounts}
              selected={selectedGl}
              onSelect={setSelectedGl}
            />
          )}

          {/* Supplier picker — only when allocType is supplier */}
          {allocType === 'supplier' && (
            <EntityPicker
              label="Supplier"
              placeholder="Select Supplier..."
              options={suppliers}
              selected={selectedSupplier}
              onSelect={setSelectedSupplier}
            />
          )}

          {/* Customer picker — only when allocType is customer */}
          {allocType === 'customer' && (
            <EntityPicker
              label="Customer"
              placeholder="Select Customer..."
              options={clients}
              selected={selectedClient}
              onSelect={setSelectedClient}
            />
          )}

          {/* VAT */}
          <div>
            <label className="text-xs text-[var(--ff-text-tertiary)] mb-1 block">VAT Treatment</label>
            <div className="flex gap-1">
              {VAT_OPTIONS.map(opt => (
                <button
                  key={opt.value}
                  type="button"
                  onClick={() => setVatCode(opt.value)}
                  className={`flex-1 px-2 py-1.5 rounded text-xs font-medium transition-colors ${
                    vatCode === opt.value
                      ? 'bg-blue-600 text-white'
                      : 'bg-[var(--ff-bg-primary)] text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)]'
                  }`}
                >
                  {opt.label}
                </button>
              ))}
            </div>
          </div>

          {/* Rule name */}
          <div>
            <label className="text-xs text-[var(--ff-text-tertiary)] mb-1 block">Rule Name</label>
            <input
              type="text"
              value={ruleName}
              onChange={e => setRuleName(e.target.value)}
              className="w-full px-3 py-2 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-sm text-[var(--ff-text-primary)] focus:outline-none focus:border-blue-500"
            />
          </div>

          {/* Auto-create toggle */}
          <label className="flex items-center gap-2 cursor-pointer">
            <input
              type="checkbox"
              checked={autoCreateEntry}
              onChange={e => setAutoCreateEntry(e.target.checked)}
              className="accent-teal-500"
            />
            <span className="text-xs text-[var(--ff-text-secondary)]">
              Auto-create journal entry (otherwise suggestion only)
            </span>
          </label>
        </div>

        {/* Footer */}
        <div className="flex items-center justify-end gap-2 px-5 py-3 border-t border-[var(--ff-border-light)]">
          <button onClick={onClose}
            className="px-4 py-1.5 rounded text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
            Cancel
          </button>
          <button onClick={handleSave} disabled={saving || !pattern.trim() || (needsGlAccount && !selectedGl)}
            className="px-4 py-1.5 rounded bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white text-sm font-medium flex items-center gap-1.5">
            {saving && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
            Create Rule
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * Split Transaction Modal — allocate a single bank transaction
 * across multiple GL accounts (Sage-style split entry).
 * Each line has its own GL account, amount, and VAT treatment.
 */

import { useState, useRef, useEffect, useCallback } from 'react';
import { X, Plus, Trash2, Search, Scissors } from 'lucide-react';
import { notify } from '@/utils/toast';
import type { BankTx, SelectOption, VatCode } from './BankTxTable';
import { VAT_OPTIONS } from './BankTxTable';

interface SplitLineState {
  id: string; // local key for React rendering
  contraAccountId: string;
  accountLabel: string;
  amount: string; // string to allow free-form input
  vatCode: VatCode;
  description: string;
}

interface Props {
  transaction: BankTx;
  glAccounts: SelectOption[];
  onClose: () => void;
  onSplit: () => void;
}

function fmtCurrency(n: number): string {
  return new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);
}

function newLine(amount = ''): SplitLineState {
  return {
    id: crypto.randomUUID(),
    contraAccountId: '',
    accountLabel: '',
    amount,
    vatCode: 'none',
    description: '',
  };
}

export function SplitTransactionModal({ transaction, glAccounts, onClose, onSplit }: Props) {
  const total = Math.abs(transaction.amount);
  const [lines, setLines] = useState<SplitLineState[]>([newLine(total.toFixed(2))]);
  const [submitting, setSubmitting] = useState(false);
  const [openPicker, setOpenPicker] = useState<string | null>(null); // line id with open dropdown
  const [pickerSearch, setPickerSearch] = useState('');
  const pickerRef = useRef<HTMLDivElement>(null);

  // Close picker on outside click
  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (pickerRef.current && !pickerRef.current.contains(e.target as Node)) {
        setOpenPicker(null);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const filteredAccounts = useCallback((): SelectOption[] => {
    if (!pickerSearch) return glAccounts.slice(0, 30);
    const q = pickerSearch.toLowerCase();
    return glAccounts
      .filter(a => (a.code || '').toLowerCase().includes(q) || a.name.toLowerCase().includes(q))
      .slice(0, 30);
  }, [glAccounts, pickerSearch]);

  const updateLine = (id: string, patch: Partial<SplitLineState>) => {
    setLines(prev => prev.map(l => (l.id === id ? { ...l, ...patch } : l)));
  };

  const addLine = () => setLines(prev => [...prev, newLine()]);

  const removeLine = (id: string) => {
    if (lines.length <= 1) return;
    setLines(prev => prev.filter(l => l.id !== id));
  };

  const allocated = lines.reduce((sum, l) => sum + (parseFloat(l.amount) || 0), 0);
  const remaining = Math.round((total - allocated) * 100) / 100;
  const canSubmit = Math.abs(remaining) <= 0.01 && lines.every(l => l.contraAccountId && parseFloat(l.amount) > 0);

  const handleSubmit = async () => {
    if (!canSubmit) return;
    setSubmitting(true);
    try {
      const payload = {
        action: 'split_allocate',
        bankTransactionId: transaction.id,
        lines: lines.map(l => ({
          contraAccountId: l.contraAccountId,
          amount: parseFloat(l.amount),
          vatCode: l.vatCode,
          description: l.description || undefined,
        })),
      };
      const res = await fetch('/api/accounting/bank-transactions-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify(payload),
      });
      const json = await res.json();
      if (!res.ok || json.success === false) throw new Error(json.message || json.error || 'Split failed');
      notify.success(`Transaction split into ${lines.length} lines and allocated`);
      onSplit();
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Split allocation failed');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
      <div className="w-full max-w-2xl bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-xl shadow-2xl flex flex-col max-h-[90vh]">
        {/* Header */}
        <div className="flex items-center gap-3 px-5 py-4 border-b border-[var(--ff-border-light)]">
          <div className="p-2 rounded-lg bg-purple-500/10">
            <Scissors className="h-4 w-4 text-purple-400" />
          </div>
          <div className="flex-1 min-w-0">
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)]">Split Transaction</h2>
            <p className="text-xs text-[var(--ff-text-tertiary)] truncate">
              {transaction.transactionDate} · {transaction.description || 'No description'}
            </p>
          </div>
          <div className="text-right mr-2">
            <p className={`text-base font-bold font-mono ${transaction.amount < 0 ? 'text-red-400' : 'text-teal-400'}`}>
              {fmtCurrency(transaction.amount)}
            </p>
            <p className="text-xs text-[var(--ff-text-tertiary)]">{transaction.amount < 0 ? 'Spent' : 'Received'}</p>
          </div>
          <button onClick={onClose} className="p-1.5 rounded hover:bg-[var(--ff-bg-primary)] text-[var(--ff-text-tertiary)]">
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Split lines */}
        <div className="overflow-y-auto flex-1 p-4 space-y-2" ref={pickerRef}>
          {lines.map((line, idx) => (
            <div key={line.id} className="rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)] p-3">
              <div className="flex items-center gap-1 mb-2">
                <span className="text-xs font-medium text-[var(--ff-text-tertiary)] w-16 shrink-0">Line {idx + 1}</span>
                {lines.length > 1 && (
                  <button onClick={() => removeLine(line.id)}
                    className="ml-auto p-1 rounded hover:bg-red-500/10 text-red-400">
                    <Trash2 className="h-3 w-3" />
                  </button>
                )}
              </div>

              <div className="grid grid-cols-[1fr_100px_110px] gap-2">
                {/* GL Account picker */}
                <div className="relative">
                  <button
                    onClick={() => { setOpenPicker(openPicker === line.id ? null : line.id); setPickerSearch(''); }}
                    className={`w-full text-left text-xs px-2 py-1.5 rounded border truncate ${
                      line.contraAccountId
                        ? 'bg-[var(--ff-bg-secondary)] border-[var(--ff-border-light)] text-[var(--ff-text-primary)]'
                        : 'bg-amber-500/5 border-amber-500/30 text-amber-400 font-medium'
                    }`}
                  >
                    {line.accountLabel || 'Select GL Account'}
                  </button>
                  {openPicker === line.id && (
                    <div className="absolute z-50 top-full left-0 mt-1 w-80 bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg shadow-xl">
                      <div className="p-2">
                        <div className="relative">
                          <Search className="absolute left-2 top-1/2 -translate-y-1/2 h-3 w-3 text-[var(--ff-text-tertiary)]" />
                          <input type="text" placeholder="Search accounts..." value={pickerSearch}
                            onChange={e => setPickerSearch(e.target.value)}
                            className="w-full pl-7 pr-2 py-1.5 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-primary)] focus:outline-none focus:border-blue-500"
                            autoFocus />
                        </div>
                      </div>
                      <div className="max-h-44 overflow-y-auto">
                        {filteredAccounts().map(o => (
                          <button key={o.id}
                            onClick={() => {
                              updateLine(line.id, {
                                contraAccountId: o.id,
                                accountLabel: o.code ? `${o.code} ${o.name}` : o.name,
                              });
                              setOpenPicker(null);
                            }}
                            className="w-full text-left px-3 py-1.5 hover:bg-[var(--ff-bg-primary)] text-xs flex items-center gap-2"
                          >
                            {o.code && <span className="font-mono text-[var(--ff-text-tertiary)] w-10 shrink-0">{o.code}</span>}
                            <span className="text-[var(--ff-text-primary)] truncate">{o.name}</span>
                          </button>
                        ))}
                        {filteredAccounts().length === 0 && (
                          <div className="px-3 py-2 text-xs text-[var(--ff-text-tertiary)]">No results</div>
                        )}
                      </div>
                    </div>
                  )}
                </div>

                {/* Amount */}
                <input type="number" min="0.01" step="0.01" placeholder="0.00"
                  value={line.amount}
                  onChange={e => updateLine(line.id, { amount: e.target.value })}
                  className="text-xs px-2 py-1.5 rounded bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-right font-mono focus:outline-none focus:border-blue-500"
                />

                {/* VAT */}
                <select value={line.vatCode}
                  onChange={e => updateLine(line.id, { vatCode: e.target.value as VatCode })}
                  className={`text-xs px-1 py-1.5 rounded bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] focus:outline-none ${
                    line.vatCode === 'standard' ? 'text-cyan-400' : 'text-[var(--ff-text-primary)]'
                  }`}
                >
                  {VAT_OPTIONS.map(v => (
                    <option key={v.value} value={v.value}>{v.label}</option>
                  ))}
                </select>
              </div>

              {/* Description (optional) */}
              <input type="text" placeholder="Description (optional)"
                value={line.description}
                onChange={e => updateLine(line.id, { description: e.target.value })}
                className="mt-2 w-full text-xs px-2 py-1.5 rounded bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] focus:outline-none focus:border-blue-500"
              />
            </div>
          ))}

          <button onClick={addLine}
            className="flex items-center gap-2 text-xs text-blue-400 hover:text-blue-300 px-1 py-1">
            <Plus className="h-3.5 w-3.5" /> Add Line
          </button>
        </div>

        {/* Summary footer */}
        <div className="border-t border-[var(--ff-border-light)] px-5 py-3">
          <div className="flex items-center justify-between mb-3 text-xs">
            <div className="flex items-center gap-6 text-[var(--ff-text-secondary)]">
              <span>Total: <span className="font-mono font-medium text-[var(--ff-text-primary)]">{fmtCurrency(total)}</span></span>
              <span>Allocated: <span className="font-mono font-medium text-[var(--ff-text-primary)]">{fmtCurrency(allocated)}</span></span>
              <span>Remaining:
                <span className={`font-mono font-medium ml-1 ${
                  Math.abs(remaining) <= 0.01 ? 'text-teal-400' : 'text-amber-400'
                }`}>{fmtCurrency(remaining)}</span>
              </span>
            </div>
            <div className="flex items-center gap-2">
              <button onClick={onClose}
                className="px-3 py-1.5 rounded text-xs text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)]">
                Cancel
              </button>
              <button onClick={handleSubmit} disabled={!canSubmit || submitting}
                className="px-4 py-1.5 rounded text-xs font-medium bg-purple-600 hover:bg-purple-700 disabled:opacity-40 text-white transition-colors">
                {submitting ? 'Splitting…' : 'Split & Allocate'}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

