/**
 * Approval Workflows — Manage rules and pending approval requests
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import {
import { apiFetch } from '@/lib/apiFetch';
  Shield, CheckCircle2, XCircle, Clock, Loader2, Plus, Trash2, AlertCircle,
} from 'lucide-react';

function formatCurrency(amount: number): string {
  return 'R ' + Math.abs(amount).toLocaleString('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

interface ApprovalRule {
  id: string;
  name: string;
  documentType: string;
  conditionField: string;
  conditionOperator: string;
  conditionValue: number;
  approverRole: string;
  isActive: boolean;
}

interface ApprovalRequest {
  id: string;
  ruleName?: string;
  documentType: string;
  documentId: string;
  documentReference: string | null;
  amount: number | null;
  status: string;
  requestedByName?: string;
  requestedAt: string;
  decidedByName?: string;
  decidedAt: string | null;
  decisionNotes: string | null;
}

const DOC_TYPE_LABELS: Record<string, string> = {
  customer_invoice: 'Customer Invoice',
  supplier_invoice: 'Supplier Invoice',
  payment: 'Payment',
  journal_entry: 'Journal Entry',
  credit_note: 'Credit Note',
};

const STATUS_STYLES: Record<string, string> = {
  pending: 'bg-amber-500/20 text-amber-500',
  approved: 'bg-teal-500/20 text-teal-500',
  rejected: 'bg-red-500/20 text-red-500',
  cancelled: 'bg-gray-500/20 text-gray-500',
};

export default function ApprovalsPage() {
  const [tab, setTab] = useState<'pending' | 'rules' | 'history'>('pending');
  const [requests, setRequests] = useState<ApprovalRequest[]>([]);
  const [rules, setRules] = useState<ApprovalRule[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [deciding, setDeciding] = useState<string | null>(null);

  const fetchData = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const [reqRes, rulesRes] = await Promise.all([
        apiFetch(tab === 'pending' ? '/api/accounting/approval-requests?status=pending' : '/api/accounting/approval-requests'),
        apiFetch('/api/accounting/approval-rules'),
      ]);
      if (!reqRes.ok || !rulesRes.ok) throw new Error('Failed to load');
      const reqJson = await reqRes.json();
      const rulesJson = await rulesRes.json();
      setRequests(reqJson.data?.items ?? []);
      setRules(rulesJson.data?.items ?? []);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load');
    } finally {
      setLoading(false);
    }
  }, [tab]);

  useEffect(() => { void fetchData(); }, [fetchData]);

  const handleDecision = async (requestId: string, action: 'approve' | 'reject') => {
    setDeciding(requestId);
    try {
      const res = await apiFetch('/api/accounting/approval-requests', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action, requestId }),
      });
      if (!res.ok) throw new Error('Failed');
      await fetchData();
    } catch {
      setError('Failed to process decision');
    } finally {
      setDeciding(null);
    }
  };

  const handleDeleteRule = async (ruleId: string) => {
    try {
      await apiFetch(`/api/accounting/approval-rules?id=${ruleId}`, { method: 'DELETE' });
      await fetchData();
    } catch {
      setError('Failed to delete rule');
    }
  };

  const pendingCount = requests.filter(r => r.status === 'pending').length;

  return (
    <AppLayout>
      <div className="p-4 lg:p-6 space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-teal-500/10">
              <Shield className="h-6 w-6 text-teal-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Approvals</h1>
              <p className="text-sm text-[var(--ff-text-secondary)]">
                Review and manage approval workflows
              </p>
            </div>
          </div>
          {pendingCount > 0 && (
            <div className="bg-amber-500/20 text-amber-500 px-3 py-1 rounded-full text-sm font-medium">
              {pendingCount} pending
            </div>
          )}
        </div>

        {/* Tabs */}
        <div className="flex gap-1 border-b border-[var(--ff-border-primary)]">
          {(['pending', 'history', 'rules'] as const).map(t => (
            <button
              key={t}
              onClick={() => setTab(t)}
              className={`px-4 py-2.5 text-sm font-medium border-b-2 transition-colors capitalize ${
                tab === t
                  ? 'border-teal-500 text-teal-500'
                  : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'
              }`}
            >
              {t === 'pending' ? `Pending (${pendingCount})` : t}
            </button>
          ))}
        </div>

        {error && (
          <div className="bg-red-500/10 border border-red-500/30 rounded-lg p-3 flex items-center gap-2 text-red-500 text-sm">
            <AlertCircle className="h-4 w-4" /> {error}
          </div>
        )}

        {loading ? (
          <div className="flex justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
          </div>
        ) : tab === 'rules' ? (
          /* Rules Tab */
          <div className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-xl overflow-hidden">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-[var(--ff-bg-secondary)]">
                  <th className="text-left px-4 py-3 font-medium text-[var(--ff-text-secondary)]">Rule Name</th>
                  <th className="text-left px-4 py-3 font-medium text-[var(--ff-text-secondary)]">Document Type</th>
                  <th className="text-left px-4 py-3 font-medium text-[var(--ff-text-secondary)]">Condition</th>
                  <th className="text-left px-4 py-3 font-medium text-[var(--ff-text-secondary)]">Approver</th>
                  <th className="text-center px-4 py-3 font-medium text-[var(--ff-text-secondary)]">Active</th>
                  <th className="text-center px-4 py-3 font-medium text-[var(--ff-text-secondary)]">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[var(--ff-border-primary)]">
                {rules.length === 0 ? (
                  <tr><td colSpan={6} className="px-4 py-8 text-center text-[var(--ff-text-secondary)]">No approval rules configured</td></tr>
                ) : rules.map(rule => (
                  <tr key={rule.id} className="hover:bg-[var(--ff-bg-hover)]">
                    <td className="px-4 py-3 text-[var(--ff-text-primary)] font-medium">{rule.name}</td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{DOC_TYPE_LABELS[rule.documentType] || rule.documentType}</td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                      {rule.conditionOperator === 'any' ? 'All documents' : `${rule.conditionField} > ${formatCurrency(rule.conditionValue)}`}
                    </td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)] capitalize">{rule.approverRole}</td>
                    <td className="px-4 py-3 text-center">
                      <span className={`inline-block w-2 h-2 rounded-full ${rule.isActive ? 'bg-teal-500' : 'bg-gray-400'}`} />
                    </td>
                    <td className="px-4 py-3 text-center">
                      <button onClick={() => void handleDeleteRule(rule.id)} className="text-red-400 hover:text-red-500">
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          /* Pending / History Tab */
          <div className="space-y-3">
            {requests.length === 0 ? (
              <div className="text-center py-12 text-[var(--ff-text-secondary)]">
                {tab === 'pending' ? 'No pending approvals' : 'No approval history'}
              </div>
            ) : requests.filter(r => tab === 'pending' ? r.status === 'pending' : true).map(req => (
              <div
                key={req.id}
                className="bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-xl p-4 flex items-center gap-4"
              >
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${STATUS_STYLES[req.status] || ''}`}>
                      {req.status}
                    </span>
                    <span className="text-xs text-[var(--ff-text-tertiary)]">
                      {DOC_TYPE_LABELS[req.documentType] || req.documentType}
                    </span>
                    {req.ruleName && (
                      <span className="text-xs text-[var(--ff-text-tertiary)]">• {req.ruleName}</span>
                    )}
                  </div>
                  <p className="text-sm font-medium text-[var(--ff-text-primary)]">
                    {req.documentReference || req.documentId.slice(0, 8)}
                    {req.amount != null && <span className="ml-2 text-teal-500">{formatCurrency(req.amount)}</span>}
                  </p>
                  <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">
                    Requested by {req.requestedByName || 'Unknown'} • {new Date(req.requestedAt).toLocaleDateString('en-ZA')}
                    {req.decidedByName && ` • Decided by ${req.decidedByName}`}
                  </p>
                </div>

                {req.status === 'pending' && (
                  <div className="flex gap-2 flex-shrink-0">
                    <button
                      onClick={() => void handleDecision(req.id, 'approve')}
                      disabled={deciding === req.id}
                      className="flex items-center gap-1 px-3 py-1.5 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-medium transition-colors disabled:opacity-50"
                    >
                      <CheckCircle2 className="h-4 w-4" /> Approve
                    </button>
                    <button
                      onClick={() => void handleDecision(req.id, 'reject')}
                      disabled={deciding === req.id}
                      className="flex items-center gap-1 px-3 py-1.5 bg-red-600 hover:bg-red-700 text-white rounded-lg text-sm font-medium transition-colors disabled:opacity-50"
                    >
                      <XCircle className="h-4 w-4" /> Reject
                    </button>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>
    </AppLayout>
  );
}

/**
 * Create Rule Modal — opens pre-filled from a bank transaction row.
 * Extracts a recurring pattern from the description, lets user pick GL account,
 * allocation type (account/supplier/customer), and shows a live preview.
 */

import { useState, useEffect, useRef } from 'react';
import { X, Search, BookmarkPlus, Loader2 } from 'lucide-react';
import { notify } from '@/utils/toast';
import { apiFetch } from '@/lib/apiFetch';
import type { BankTx, SelectOption } from './BankTxTable';
import type { RuleMatchType, RuleVatCode } from '@/modules/accounting/types/bank.types';

const VAT_OPTIONS: { value: RuleVatCode; label: string }[] = [
  { value: 'none', label: 'No VAT' },
  { value: 'standard', label: 'Standard 15%' },
  { value: 'zero_rated', label: 'Zero Rated' },
  { value: 'exempt', label: 'Exempt' },
];

type AllocType = 'account' | 'supplier' | 'customer';

interface Props {
  transaction: BankTx;
  bankAccountId: string;
  glAccounts: SelectOption[];
  suppliers?: SelectOption[];
  clients?: SelectOption[];
  onClose: () => void;
  onCreated: () => void;
}

/**
 * Strip unique references, dates, card numbers from a transaction description
 * to extract the recurring core pattern for rule matching.
 * Exported so other components (e.g. allocation flow) can derive the same pattern.
 */
export function extractPattern(desc: string): string {
  let p = desc;
  p = p.replace(/[a-f0-9]{8,}/gi, '');
  p = p.replace(/\d{4}[-/]\d{2}[-/]\d{2}/g, '');
  p = p.replace(/\d{2}[-/]\d{2}[-/]\d{4}/g, '');
  p = p.replace(/\d{8}/g, '');
  p = p.replace(/\d{4,}/g, '');
  p = p.replace(/\/Cmd\s+\w\b/gi, '');
  p = p.replace(/\s{2,}/g, ' ').trim();
  p = p.replace(/[/\s]+$/, '');
  return p;
}

/** Reusable searchable dropdown for GL accounts, suppliers, or customers */
function EntityPicker({
  label, placeholder, options, selected, onSelect,
}: {
  label: string; placeholder: string; options: SelectOption[];
  selected: SelectOption | null; onSelect: (o: SelectOption) => void;
}) {
  const [search, setSearch] = useState('');
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const h = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', h);
    return () => document.removeEventListener('mousedown', h);
  }, []);

  const filtered = search
    ? options.filter(o =>
        (o.code || '').toLowerCase().includes(search.toLowerCase()) ||
        o.name.toLowerCase().includes(search.toLowerCase())
      )
    : options;

  return (
    <div ref={ref}>
      <label className="text-xs text-[var(--ff-text-tertiary)] mb-1 block">{label}</label>
      <div className="relative">
        <button
          onClick={() => { setOpen(!open); setSearch(''); }}
          className={`w-full text-left px-3 py-2 rounded border text-sm ${
            selected
              ? 'bg-[var(--ff-bg-primary)] border-[var(--ff-border-light)] text-[var(--ff-text-primary)]'
              : 'bg-[var(--ff-bg-primary)] border-amber-500/40 text-amber-400'
          }`}
        >
          {selected ? `${selected.code || ''} ${selected.name}`.trim() : placeholder}
        </button>
        {open && (
          <div className="absolute z-50 top-full left-0 mt-1 w-full bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg shadow-xl">
            <div className="p-2">
              <div className="relative">
                <Search className="absolute left-2 top-1/2 -translate-y-1/2 h-3 w-3 text-[var(--ff-text-tertiary)]" />
                <input
                  type="text"
                  placeholder={`Search...`}
                  value={search}
                  onChange={e => setSearch(e.target.value)}
                  className="w-full pl-7 pr-2 py-1.5 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-primary)] focus:outline-none focus:border-blue-500"
                  autoFocus
                />
              </div>
            </div>
            <div className="max-h-48 overflow-y-auto">
              {filtered.slice(0, 50).map(o => (
                <button
                  key={o.id}
                  onClick={() => { onSelect(o); setOpen(false); }}
                  className="w-full text-left px-3 py-1.5 hover:bg-[var(--ff-bg-primary)] text-xs flex items-center gap-2"
                >
                  {o.code && <span className="font-mono text-[var(--ff-text-tertiary)] w-10 shrink-0">{o.code}</span>}
                  <span className="text-[var(--ff-text-primary)] truncate">{o.name}</span>
                </button>
              ))}
              {filtered.length === 0 && (
                <div className="px-3 py-2 text-xs text-[var(--ff-text-tertiary)]">No results found</div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export function CreateRuleModal({ transaction, bankAccountId, glAccounts, suppliers = [], clients = [], onClose, onCreated }: Props) {
  const [pattern, setPattern] = useState(() => extractPattern(transaction.description || ''));
  const [matchType, setMatchType] = useState<RuleMatchType>('contains');
  const [ruleName, setRuleName] = useState(() => extractPattern(transaction.description || ''));
  const [autoCreateEntry, setAutoCreateEntry] = useState(false);

  const [allocType, setAllocType] = useState<AllocType>('account');
  const [vatCode, setVatCode] = useState<RuleVatCode>('none');
  const [selectedGl, setSelectedGl] = useState<SelectOption | null>(null);
  const [selectedSupplier, setSelectedSupplier] = useState<SelectOption | null>(null);
  const [selectedClient, setSelectedClient] = useState<SelectOption | null>(null);

  const [matchCount, setMatchCount] = useState<number | null>(null);
  const [previewLoading, setPreviewLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  // Live preview — debounced query as user edits pattern
  useEffect(() => {
    if (!pattern.trim()) { setMatchCount(0); return; }
    setPreviewLoading(true);
    const timer = setTimeout(async () => {
      try {
        const params = new URLSearchParams({ pattern, matchType, bankAccountId });
        const res = await fetch(`/api/accounting/bank-rules-preview?${params}`);
        const json = await res.json();
        setMatchCount(json.data?.matchCount ?? 0);
      } catch {
        setMatchCount(null);
      } finally {
        setPreviewLoading(false);
      }
    }, 400);
    return () => clearTimeout(timer);
  }, [pattern, matchType, bankAccountId]);

  // Clear entity selection when switching alloc type
  useEffect(() => {
    setSelectedSupplier(null);
    setSelectedClient(null);
  }, [allocType]);

  const needsGlAccount = allocType === 'account';

  const handleSave = async () => {
    if (!pattern.trim()) { notify.error('Pattern is required'); return; }
    if (needsGlAccount && !selectedGl) { notify.error('Select a GL account'); return; }
    if (allocType === 'supplier' && !selectedSupplier) { notify.error('Select a supplier'); return; }
    if (allocType === 'customer' && !selectedClient) { notify.error('Select a customer'); return; }
    setSaving(true);
    try {
      const body: Record<string, unknown> = {
        ruleName: ruleName.trim() || pattern.trim(),
        matchField: 'description',
        matchType,
        matchPattern: pattern.trim(),
        autoCreateEntry,
        vatCode,
      };
      // GL account only needed for 'account' type — supplier/customer use AP/AR automatically
      if (needsGlAccount && selectedGl) body.glAccountId = selectedGl.id;
      if (allocType === 'supplier' && selectedSupplier) body.supplierId = selectedSupplier.id;
      if (allocType === 'customer' && selectedClient) body.clientId = selectedClient.id;

      const res = await fetch('/api/accounting/bank-rules', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify(body),
      });
      const json = await res.json();
      if (!res.ok || json.success === false) throw new Error(json.message || 'Failed to create rule');
      notify.success('Rule created');
      onCreated();
    } catch (e) {
      notify.error(e instanceof Error ? e.message : 'Failed to create rule');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60">
      <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-xl shadow-2xl w-full max-w-lg mx-4">
        {/* Header */}
