                    vatCode === opt.value
                      ? 'bg-blue-600 text-white'
                      : 'bg-[var(--ff-bg-primary)] text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)]'
                  }`}
                >
                  {opt.label}
