}

interface AccountTreeNode extends GLAccount {
  children: AccountTreeNode[];
}

export async function getChartOfAccounts(_companyId: string, includeInactive = false): Promise<GLAccount[]> {
  try {
    let rows;
    if (includeInactive) {
      rows = await sql`
        SELECT a.*,
          p.account_code AS parent_code,
          p.account_name AS parent_name
        FROM gl_accounts a
        LEFT JOIN gl_accounts p ON p.id = a.parent_account_id
        ORDER BY a.account_code
      `;
    } else {
      rows = await sql`
        SELECT a.*,
          p.account_code AS parent_code,
          p.account_name AS parent_name
        FROM gl_accounts a
        LEFT JOIN gl_accounts p ON p.id = a.parent_account_id
        WHERE a.is_active = true
        ORDER BY a.account_code
      `;
    }
    return (rows as { [key: string]: unknown }[]).map(mapRow);
  } catch (err) {
    log.error('Failed to get chart of accounts', { error: err }, 'accounting');
    throw err;
  }
}

export async function getAccountTree(_companyId: string, includeInactive = false): Promise<AccountTreeNode[]> {
  const accounts = await getChartOfAccounts(_companyId, includeInactive);
  const map = new Map<string, AccountTreeNode>();
  const roots: AccountTreeNode[] = [];

  for (const acc of accounts) {
    map.set(acc.id, { ...acc, children: [] });
  }

  for (const acc of accounts) {
    const node = map.get(acc.id)!;
    if (acc.parentAccountId) {
      const parent = map.get(acc.parentAccountId);
      if (parent) {
        parent.children.push(node);
        continue;
      }
    }
    roots.push(node);
  }

  return roots;
}

