/**
 * Companies API
 * GET  — list companies for current user
 * POST — create a new company
 * PUT  — update company details
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import {
  listCompanies, getCompany, createCompany, updateCompany,
  getUserCompanies, setDefaultCompany,
} from '@/modules/accounting/services/companyService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    if (req.query.action === 'user-companies') {
      const companies = await getUserCompanies(userId);
      return apiResponse.success(res, { items: companies });
    }
    if (req.query.id) {
      // Verify user has access to this company
      const userCompanies = await getUserCompanies(userId);
      const hasAccess = userCompanies.some(c => c.companyId === req.query.id);
      if (!hasAccess) return apiResponse.forbidden(res, 'You do not have access to this company');
      const company = await getCompany(req.query.id as string);
      if (!company) return apiResponse.notFound(res, 'Company');
      return apiResponse.success(res, company);
    }
    // Default: only return companies the user belongs to
    const companies = await getUserCompanies(userId);
    return apiResponse.success(res, { items: companies });
  }

  if (req.method === 'POST') {
    if (req.body.action === 'set-default') {
      // Verify membership before setting default
      const userCompanies = await getUserCompanies(userId);
      if (!userCompanies.some(c => c.companyId === req.body.companyId)) {
        return apiResponse.forbidden(res, 'You do not have access to this company');
      }
      await setDefaultCompany(userId, req.body.companyId);
      return apiResponse.success(res, { success: true });
    }
    const { name, tradingName, registrationNumber, vatNumber, taxNumber, email, phone } = req.body;
    if (!name) return apiResponse.badRequest(res, 'name is required');
    const company = await createCompany(
      { name, tradingName, registrationNumber, vatNumber, taxNumber, email, phone },
      userId
    );
    return apiResponse.success(res, company);
  }

  if (req.method === 'PUT') {
    const { id, ...updates } = req.body;
    if (!id) return apiResponse.badRequest(res, 'id is required');
    // Verify user is owner or admin of this company
    const userCompanies = await getUserCompanies(userId);
    const membership = userCompanies.find(c => c.companyId === id);
    if (!membership) return apiResponse.forbidden(res, 'You do not have access to this company');
    if (!['owner', 'admin'].includes(membership.role)) {
      return apiResponse.forbidden(res, 'Only owners and admins can update company details');
    }
    const company = await updateCompany(id, updates);
    return apiResponse.success(res, company);
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST', 'PUT']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

/**
 * Cost Centre (Analysis Code) Service
 * Phase 5: Custom reporting dimensions for GL entries
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export type CcType = 'cc1' | 'cc2';

export interface CostCentre {
  id: string;
  code: string;
  name: string;
  description?: string;
  department?: string;
  ccType: CcType;
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
}

export interface CostCentreInput {
  code: string;
  name: string;
  description?: string;
  department?: string;
  ccType?: CcType;
}

export async function getCostCentres(_companyId: string, activeOnly = false, ccType?: CcType): Promise<CostCentre[]> {
  let rows: Row[];
  if (ccType === 'cc1') {
    rows = activeOnly
      ? ((await sql`SELECT * FROM cost_centres WHERE cc_type = 'cc1' AND is_active = true ORDER BY code`) as Row[])
      : ((await sql`SELECT * FROM cost_centres WHERE cc_type = 'cc1' ORDER BY code`) as Row[]);
  } else if (ccType === 'cc2') {
    rows = activeOnly
      ? ((await sql`SELECT * FROM cost_centres WHERE cc_type = 'cc2' AND is_active = true ORDER BY code`) as Row[])
      : ((await sql`SELECT * FROM cost_centres WHERE cc_type = 'cc2' ORDER BY code`) as Row[]);
  } else {
    rows = activeOnly
      ? ((await sql`SELECT * FROM cost_centres WHERE is_active = true ORDER BY code`) as Row[])
      : ((await sql`SELECT * FROM cost_centres ORDER BY code`) as Row[]);
  }
  return rows.map(mapRow);
}

export async function getCostCentre(id: string): Promise<CostCentre | null> {
  const rows = (await sql`SELECT * FROM cost_centres WHERE id = ${id}::UUID`) as Row[];
  return rows[0] ? mapRow(rows[0]) : null;
}

export async function createCostCentre(_companyId: string, input: CostCentreInput, userId: string): Promise<CostCentre> {
  const ccType: CcType = input.ccType || 'cc1';
  const rows = (await sql`
    INSERT INTO cost_centres (code, name, description, department, cc_type, created_by)
    VALUES (${input.code}, ${input.name}, ${input.description || null},
            ${input.department || null}, ${ccType}, ${userId}::UUID)
    RETURNING *
  `) as Row[];
  log.info('Created cost centre', { id: rows[0].id, code: input.code }, 'accounting');
  return mapRow(rows[0]);
}

export async function updateCostCentre(_companyId: string, id: string, input: Partial<CostCentreInput>): Promise<CostCentre> {
  const rows = (await sql`
    UPDATE cost_centres SET
      code = COALESCE(${input.code || null}, code),
      name = COALESCE(${input.name || null}, name),
      description = COALESCE(${input.description || null}, description),
      department = COALESCE(${input.department || null}, department)
    WHERE id = ${id}::UUID RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Cost centre ${id} not found`);
  return mapRow(rows[0]);
}

/**
 * PRD-060: FibreFlow Accounting Module
 * Fiscal Period Service
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { FiscalPeriod, FiscalPeriodStatus } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export async function getFiscalPeriods(_companyId: string, fiscalYear?: number): Promise<FiscalPeriod[]> {
  try {
    let rows: Row[];
    if (fiscalYear) {
      rows = (await sql`
        SELECT * FROM fiscal_periods
        WHERE fiscal_year = ${fiscalYear}
        ORDER BY period_number
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT * FROM fiscal_periods
        ORDER BY fiscal_year DESC, period_number
      `) as Row[];
    }
    return rows.map(mapRow);
  } catch (err) {
    log.error('Failed to get fiscal periods', { fiscalYear, error: err }, 'accounting');
    throw err;
  }
}

export async function getFiscalPeriodById(id: string): Promise<FiscalPeriod | null> {
  try {
    const rows = (await sql`SELECT * FROM fiscal_periods WHERE id = ${id}`) as Row[];
    return rows.length > 0 ? mapRow(rows[0]) : null;
  } catch (err) {
    log.error('Failed to get fiscal period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function getCurrentFiscalPeriod(_companyId: string): Promise<FiscalPeriod | null> {
  try {
    const rows = (await sql`
      SELECT * FROM fiscal_periods
      WHERE start_date <= CURRENT_DATE AND end_date >= CURRENT_DATE
      LIMIT 1
    `) as Row[];
    return rows.length > 0 ? mapRow(rows[0]) : null;
  } catch (err) {
    log.error('Failed to get current fiscal period', { error: err }, 'accounting');
    throw err;
  }
}

export async function createFiscalYear(_companyId: string, year: number): Promise<FiscalPeriod[]> {
  try {
    const existing = (await sql`
      SELECT COUNT(*) AS cnt FROM fiscal_periods WHERE fiscal_year = ${year}
    `) as Row[];
    if (Number(existing[0].cnt) > 0) {
      throw new Error(`Fiscal year ${year} already exists`);
    }

    const months = [
      'January', 'February', 'March', 'April', 'May', 'June',
      'July', 'August', 'September', 'October', 'November', 'December',
    ];

    const periods: FiscalPeriod[] = [];
    for (let i = 0; i < 12; i++) {
      const periodNum = i + 1;
      const startDate = `${year}-${String(periodNum).padStart(2, '0')}-01`;
      const lastDay = new Date(year, periodNum, 0).getDate();
      const endDate = `${year}-${String(periodNum).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;

      const rows = (await sql`
        INSERT INTO fiscal_periods (period_name, period_number, fiscal_year, start_date, end_date)
        VALUES (${months[i]! + ' ' + year}, ${periodNum}, ${year}, ${startDate}, ${endDate})
        RETURNING *
      `) as Row[];
      periods.push(mapRow(rows[0]));
    }

    return periods;
  } catch (err) {
    log.error('Failed to create fiscal year', { year, error: err }, 'accounting');
    throw err;
  }
}

export async function closePeriod(_companyId: string, id: string, userId: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status === 'locked') throw new Error('Cannot close a locked period');
    if (period.status === 'closed') throw new Error('Period is already closed');

