/**
 * Group Company Service
 * Manages company groups, memberships, group COA, COA mappings,
 * and intercompany transactions for consolidated reporting.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ────────────────────────────────────────────────────────────────────

export interface CompanyGroup {
  id: string;
  name: string;
  holdingCompanyId: string | null;
  defaultCurrency: string;
  financialYearStart: number;
  isActive: boolean;
  createdBy: string | null;
  createdAt: string;
  updatedAt: string;
  memberCount?: number;
}

export interface GroupMember {
  id: string;
  groupId: string;
  companyId: string;
  companyName?: string;
  ownershipPct: number;
  consolidationMethod: string;
  isHolding: boolean;
  joinedDate: string;
  leftDate: string | null;
  createdAt: string;
}

export interface GroupAccount {
  id: string;
  groupId: string;
  accountCode: string;
  accountName: string;
  accountType: string;
  accountSubtype: string | null;
  parentAccountId: string | null;
  normalBalance: string;
  level: number;
  displayOrder: number;
  isActive: boolean;
  createdAt: string;
}

export interface CoaMapping {
  id: string;
  groupId: string;
  groupAccountId: string;
  groupAccountCode?: string;
  groupAccountName?: string;
  companyId: string;
  companyAccountId: string;
  companyAccountCode?: string;
  companyAccountName?: string;
  createdAt: string;
}

export interface IntercompanyTransaction {
  id: string;
  groupId: string;
