                <div>
                  <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">{activeCompany?.tradingName || activeCompany?.name || 'ISAFlow'}</h1>
                  <p className="text-sm text-[var(--ff-text-secondary)]">
