/**
 * Group Dashboard — consolidated view across multiple entities in a company group.
 * Shows combined KPIs, entity summary table, and quick links to consolidated reports.
 */

import { useState, useEffect, useCallback } from 'react';
import Link from 'next/link';
import { AppLayout } from '@/components/layout/AppLayout';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';
import {
  Building2,
  ChevronDown,
  Plus,
  Loader2,
  AlertCircle,
  TrendingUp,
  DollarSign,
  Landmark,
  FileText,
  CreditCard,
  ArrowRight,
  Settings,
  Scale,
  FileSpreadsheet,
  BarChart3,
  Layers,
  RefreshCw,
} from 'lucide-react';

// ─── Types ────────────────────────────────────────────────────────────────────

interface CompanyGroup {
  id: string;
  name: string;
  holdingCompanyName: string;
  memberCount: number;
}

interface EntitySummary {
  companyId: string;
  companyName: string;
  revenue: number;
  expenses: number;
  netProfit: number;
  cashPosition: number;
}

interface GroupDashboardData {
  combinedCash: number;
  combinedRevenue: number;
  combinedAR: number;
  combinedAP: number;
  entities: EntitySummary[];
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function fmtCurrency(n: number): string {
  return 'R ' + new Intl.NumberFormat('en-ZA', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(n);
}

function fmtCompact(n: number): string {
  if (Math.abs(n) >= 1_000_000) return 'R ' + (n / 1_000_000).toFixed(1) + 'M';
  if (Math.abs(n) >= 1_000) return 'R ' + (n / 1_000).toFixed(1) + 'K';
  return fmtCurrency(n);
}

// ─── Quick Links Config ───────────────────────────────────────────────────────

const QUICK_LINKS = [
  {
    label: 'Consolidated Trial Balance',
    href: '/accounting/group/trial-balance',
    icon: Scale,
    description: 'Combined trial balance across all entities',
  },
  {
    label: 'Consolidated Income Statement',
    href: '/accounting/group/income-statement',
    icon: TrendingUp,
    description: 'Revenue and expenses for the group',
  },
