      flash('Member added', 'success');
      setShowAddMember(false);
      setNewMember({ company_id: '', ownership_pct: 100, consolidation_method: 'full' });
      await fetchMembers(group.id);
    } catch {
      flash('Failed to add member', 'error');
    } finally {
      setSaving(false);
    }
  };

