      if (!res.ok) throw new Error('Auto-generate failed');
      flash('Group COA generated from company', 'success');
      setCoaSourceCompany('');
      await fetchGroupAccounts(group.id);
    } catch {
      flash('Failed to generate group COA', 'error');
    } finally {
      setSaving(false);
    }
  };

