tool_response.originalFile:
/**
 * Intercompany Reconciliation
 * View, record, and reconcile intercompany transactions across group companies.
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import {
  Building2,
  Loader2,
  AlertCircle,
  Check,
  Plus,
  Link2,
  X,
  ArrowLeftRight,
  Calendar,
  Filter,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

/* ── Formatters ── */
const fmt = (n: number, currency = 'ZAR') =>
  new Intl.NumberFormat('en-ZA', { style: 'currency', currency }).format(n);

/* ── Types ── */
interface CompanyGroup {
  id: string;
  name: string;
  companies: { id: string; name: string }[];
}

interface IntercompanyTx {
  id: string;
  date: string;
  sourceCompanyId: string;
  sourceCompanyName: string;
  targetCompanyId: string;
  targetCompanyName: string;
  type: string;
  amount: number;
  currency: string;
  description: string;
  status: 'matched' | 'partial' | 'unmatched' | 'variance';
  matchedTxId?: string;
  journalEntryId?: string;
}

interface ReconciliationStats {
  totalVolume: number;
  matchedCount: number;
  matchedAmount: number;
  unmatchedCount: number;
  unmatchedAmount: number;
  varianceCount: number;
  varianceAmount: number;
}

type TabKey = 'all' | 'unmatched' | 'matched' | 'variance';

const TX_TYPES = [
  { value: 'sale', label: 'Sale' },
  { value: 'purchase', label: 'Purchase' },
  { value: 'loan', label: 'Loan' },
  { value: 'dividend', label: 'Dividend' },
  { value: 'mgmt_fee', label: 'Management Fee' },
  { value: 'transfer', label: 'Transfer' },
] as const;

const STATUS_STYLES: Record<string, string> = {
  matched: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30',
  partial: 'bg-amber-500/10 text-amber-400 border-amber-500/30',
  unmatched: 'bg-red-500/10 text-red-400 border-red-500/30',
  variance: 'bg-orange-500/10 text-orange-400 border-orange-500/30',
};

/* ── Default date range: current month ── */
function defaultRange() {
  const now = new Date();
  const start = new Date(now.getFullYear(), now.getMonth(), 1);
  const end = new Date(now.getFullYear(), now.getMonth() + 1, 0);
  return {
    start: start.toISOString().split('T')[0],
    end: end.toISOString().split('T')[0],
  };
}

export default function IntercompanyReconciliationPage() {
  /* ── State ── */
  const [groups, setGroups] = useState<CompanyGroup[]>([]);
  const [selectedGroupId, setSelectedGroupId] = useState('');
  const range = defaultRange();
  const [periodStart, setPeriodStart] = useState(range.start);
  const [periodEnd, setPeriodEnd] = useState(range.end);

  const [transactions, setTransactions] = useState<IntercompanyTx[]>([]);
  const [stats, setStats] = useState<ReconciliationStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [loadingTx, setLoadingTx] = useState(false);

  const [activeTab, setActiveTab] = useState<TabKey>('all');
  const [showCreate, setShowCreate] = useState(false);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

  // Matching state
  const [matchSelection, setMatchSelection] = useState<string[]>([]);

  // Create form state
  const [form, setForm] = useState({
    sourceCompanyId: '',
    targetCompanyId: '',
    type: 'sale',
    amount: '',
    currency: 'ZAR',
    date: new Date().toISOString().slice(0, 10),
    description: '',
    journalEntryId: '',
  });

  /* ── Helpers ── */
  const activeGroup = groups.find((g) => g.id === selectedGroupId);
  const companies = activeGroup?.companies || [];

  /* ── Load groups ── */
  useEffect(() => {
    (async () => {
      setLoading(true);
      const res = await apiFetch('/api/accounting/company-groups');
      if (res.ok) {
        const json = await res.json();
        const list: CompanyGroup[] = json.data || json.groups || [];
        setGroups(list);
        if (list.length > 0 && !selectedGroupId && list[0]) {
          setSelectedGroupId(list[0].id);
        }
      }
      setLoading(false);
    })();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  /* ── Load transactions + stats ── */
  const loadData = useCallback(async () => {
    if (!selectedGroupId) return;
    setLoadingTx(true);
    setMsg(null);

    const params = new URLSearchParams({
      group_id: selectedGroupId,
      ...(periodStart ? { period_start: periodStart } : {}),
      ...(periodEnd ? { period_end: periodEnd } : {}),
    });
    if (activeTab !== 'all') params.set('status', activeTab);

    const [txRes, reconRes] = await Promise.all([
      apiFetch(`/api/accounting/intercompany-transactions?${params}`),
      apiFetch(
        `/api/accounting/intercompany-transactions?group_id=${selectedGroupId}&action=reconciliation&period_start=${periodStart}&period_end=${periodEnd}`
      ),
    ]);

    if (txRes.ok) {
      const json = await txRes.json();
      setTransactions(json.data?.items || json.data || []);
    }
    if (reconRes.ok) {
      const json = await reconRes.json();
      setStats(json.data || null);
    }
    setLoadingTx(false);
  }, [selectedGroupId, periodStart, periodEnd, activeTab]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  /* ── Create transaction ── */
  const handleCreate = async () => {
    if (!form.sourceCompanyId || !form.targetCompanyId || !form.amount) return;
    setSaving(true);
    const res = await apiFetch('/api/accounting/intercompany-transactions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        groupId: selectedGroupId,
        sourceCompanyId: form.sourceCompanyId,
        targetCompanyId: form.targetCompanyId,
        transactionType: form.type,
        amount: parseFloat(form.amount),
        currency: form.currency,
        transactionDate: form.date,
        description: form.description,
        sourceJournalEntryId: form.journalEntryId || undefined,
      }),
    });
    if (res.ok) {
      setMsg({ type: 'success', text: 'Transaction recorded' });
      setShowCreate(false);
      setForm({
        sourceCompanyId: '',
        targetCompanyId: '',
        type: 'sale',
        amount: '',
        currency: 'ZAR',
        date: new Date().toISOString().slice(0, 10),
        description: '',
        journalEntryId: '',
      });
      await loadData();
    } else {
      const err = await res.json().catch(() => null);
      setMsg({ type: 'error', text: err?.message || 'Failed to create transaction' });
    }
    setSaving(false);
  };

  /* ── Match two transactions ── */
  const toggleMatchSelect = (id: string) => {
    setMatchSelection((prev) => {
      if (prev.includes(id)) return prev.filter((x) => x !== id);
      if (prev.length >= 2) return [prev[1]!, id];
      return [...prev, id];
    });
  };

  const handleMatch = async () => {
    if (matchSelection.length !== 2) return;
    setSaving(true);
    const res = await apiFetch('/api/accounting/intercompany-transactions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'match',
        transactionIds: matchSelection,
      }),
    });
    if (res.ok) {
      setMsg({ type: 'success', text: 'Transactions matched' });
      setMatchSelection([]);
      await loadData();
    } else {
      const err = await res.json().catch(() => null);
      setMsg({ type: 'error', text: err?.message || 'Match failed' });
    }
    setSaving(false);
  };

  /* ── Filtered transactions (client-side fallback) ── */
  const filtered = activeTab === 'all'
    ? transactions
    : transactions.filter((t) => t.status === activeTab);

  /* ── Tab config ── */
  const tabs: { key: TabKey; label: string }[] = [
    { key: 'all', label: 'All' },
    { key: 'unmatched', label: 'Unmatched' },
    { key: 'matched', label: 'Matched' },
    { key: 'variance', label: 'Variance' },
  ];

  /* ── Render ── */
  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between flex-wrap gap-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-purple-500/10">
                <Building2 className="h-6 w-6 text-purple-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">
                  Intercompany Reconciliation
                </h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  View, record, and reconcile intercompany transactions
                </p>
              </div>
            </div>

            <div className="flex items-center gap-3 flex-wrap">
              {/* Group Selector */}
              <div className="flex items-center gap-2">
                <Filter className="h-4 w-4 text-[var(--ff-text-tertiary)]" />
                <select
                  value={selectedGroupId}
                  onChange={(e) => setSelectedGroupId(e.target.value)}
                  className="px-3 py-1.5 text-sm bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)]"
                >
                  {groups.map((g) => (
                    <option key={g.id} value={g.id}>
                      {g.name}
                    </option>
                  ))}
                </select>
              </div>

              {/* Date Range */}
              <div className="flex items-center gap-2">
                <Calendar className="h-4 w-4 text-[var(--ff-text-tertiary)]" />
                <input
                  type="date"
                  value={periodStart}
                  onChange={(e) => setPeriodStart(e.target.value)}
                  className="px-2 py-1.5 text-sm bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)]"
                />
                <span className="text-[var(--ff-text-tertiary)] text-sm">to</span>
                <input
                  type="date"
                  value={periodEnd}
                  onChange={(e) => setPeriodEnd(e.target.value)}
                  className="px-2 py-1.5 text-sm bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)]"
                />
              </div>

              <button
                onClick={() => setShowCreate(true)}
                className="flex items-center gap-2 px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 text-sm font-medium transition-colors"
              >
                <Plus className="h-4 w-4" /> Record Transaction
              </button>
            </div>
          </div>
        </div>

        <div className="p-6 space-y-4">
          {/* Message banner */}
          {msg && (
            <div
              className={`flex items-center gap-2 p-3 rounded-lg text-sm ${
                msg.type === 'success'
                  ? 'bg-teal-500/10 text-teal-400'
                  : 'bg-red-500/10 text-red-400'
              }`}
            >
              {msg.type === 'success' ? (
                <Check className="h-4 w-4" />
              ) : (
                <AlertCircle className="h-4 w-4" />
              )}
              {msg.text}
              <button onClick={() => setMsg(null)} className="ml-auto">
                <X className="h-4 w-4" />
              </button>
            </div>
          )}

          {/* Stats Cards */}
          {stats && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
              <StatCard
                label="Total Intercompany Volume"
                value={fmt(stats.totalVolume)}
                sub={`${stats.matchedCount + stats.unmatchedCount + stats.varianceCount} transaction(s)`}
                color="text-purple-400"
              />
              <StatCard
                label="Matched"
                value={fmt(stats.matchedAmount)}
                sub={`${stats.matchedCount} transaction(s)`}
                color="text-emerald-400"
              />
              <StatCard
                label="Unmatched"
                value={fmt(stats.unmatchedAmount)}
                sub={`${stats.unmatchedCount} transaction(s)`}
                color="text-red-400"
              />
              <StatCard
                label="Variance"
                value={fmt(stats.varianceAmount)}
                sub={`${stats.varianceCount} transaction(s)`}
                color="text-orange-400"
              />
            </div>
          )}

          {/* Tabs */}
          <div className="flex items-center gap-1 border-b border-[var(--ff-border-light)]">
            {tabs.map((tab) => (
              <button
                key={tab.key}
                onClick={() => setActiveTab(tab.key)}
                className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
                  activeTab === tab.key
                    ? 'border-purple-500 text-purple-400'
                    : 'border-transparent text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-secondary)]'
                }`}
              >
                {tab.label}
              </button>
            ))}

            {/* Match button */}
            {matchSelection.length === 2 && (
              <button
                onClick={handleMatch}
                disabled={saving}
                className="ml-auto flex items-center gap-2 px-4 py-1.5 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 text-sm font-medium transition-colors"
              >
                {saving ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Link2 className="h-4 w-4" />
                )}
                Match Selected ({matchSelection.length})
              </button>
            )}
            {matchSelection.length > 0 && matchSelection.length < 2 && (
              <span className="ml-auto text-xs text-[var(--ff-text-tertiary)] py-2">
                Select 1 more transaction to match
              </span>
            )}
          </div>

          {/* Transaction Table */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
            {loading || loadingTx ? (
              <div className="p-12 text-center">
                <Loader2 className="h-6 w-6 animate-spin text-[var(--ff-text-tertiary)] mx-auto" />
              </div>
            ) : filtered.length === 0 ? (
              <div className="p-12 text-center text-[var(--ff-text-tertiary)]">
                <ArrowLeftRight className="h-8 w-8 mx-auto mb-2 opacity-50" />
                <p>No intercompany transactions found</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-[var(--ff-border-light)] text-[var(--ff-text-tertiary)] text-xs uppercase">
                      <th className="px-4 py-3 text-left w-8" />
                      <th className="px-4 py-3 text-left">Date</th>
                      <th className="px-4 py-3 text-left">Source Company</th>
                      <th className="px-4 py-3 text-left">Target Company</th>
                      <th className="px-4 py-3 text-left">Type</th>
                      <th className="px-4 py-3 text-right">Amount</th>
                      <th className="px-4 py-3 text-center">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[var(--ff-border-light)]">
                    {filtered.map((tx) => {
                      const isSelected = matchSelection.includes(tx.id);
                      const canSelect = tx.status === 'unmatched' || tx.status === 'partial';
                      return (
                        <tr
                          key={tx.id}
                          onClick={() => canSelect && toggleMatchSelect(tx.id)}
                          className={`hover:bg-[var(--ff-bg-tertiary)] transition-colors ${
                            canSelect ? 'cursor-pointer' : ''
                          } ${isSelected ? 'bg-purple-500/5' : ''}`}
                        >
                          <td className="px-4 py-3">
                            {canSelect && (
                              <input
                                type="checkbox"
                                checked={isSelected}
                                onChange={() => toggleMatchSelect(tx.id)}
                                className="rounded border-[var(--ff-border-light)]"
                              />
                            )}
                          </td>
                          <td className="px-4 py-3 text-[var(--ff-text-primary)] whitespace-nowrap">
                            {tx.date?.split('T')[0]}
                          </td>
                          <td className="px-4 py-3 text-[var(--ff-text-primary)]">
                            {tx.sourceCompanyName}
                          </td>
                          <td className="px-4 py-3 text-[var(--ff-text-primary)]">
                            {tx.targetCompanyName}
                          </td>
                          <td className="px-4 py-3 text-[var(--ff-text-secondary)] capitalize">
                            {tx.type.replace('_', ' ')}
                          </td>
                          <td className="px-4 py-3 text-right font-mono text-[var(--ff-text-primary)]">
                            {fmt(tx.amount, tx.currency)}
                          </td>
                          <td className="px-4 py-3 text-center">
                            <span
                              className={`inline-block px-2 py-0.5 text-xs font-medium rounded-full border ${
                                STATUS_STYLES[tx.status] || STATUS_STYLES.unmatched
                              }`}
                            >
                              {tx.status}
                            </span>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>

        {/* ── Create Transaction Modal ── */}
        {showCreate && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60">
            <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-xl w-full max-w-lg mx-4 shadow-2xl">
              <div className="flex items-center justify-between px-6 py-4 border-b border-[var(--ff-border-light)]">
                <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
                  Record Intercompany Transaction
                </h2>
                <button
                  onClick={() => setShowCreate(false)}
                  className="p-1 rounded hover:bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)]"
                >
                  <X className="h-5 w-5" />
                </button>
              </div>

              <div className="px-6 py-4 space-y-4">
                {/* Source / Target */}
                <div className="grid grid-cols-2 gap-4">
                  <FieldSelect
                    label="Source Company"
                    value={form.sourceCompanyId}
                    onChange={(v) => setForm((f) => ({ ...f, sourceCompanyId: v }))}
                    options={companies.map((c) => ({ value: c.id, label: c.name }))}
                    placeholder="Select..."
                  />
                  <FieldSelect
                    label="Target Company"
                    value={form.targetCompanyId}
                    onChange={(v) => setForm((f) => ({ ...f, targetCompanyId: v }))}
                    options={companies.filter((c) => c.id !== form.sourceCompanyId).map((c) => ({ value: c.id, label: c.name }))}
                    placeholder="Select..."
                  />
                </div>

                {/* Type + Currency */}
                <div className="grid grid-cols-2 gap-4">
                  <FieldSelect
                    label="Transaction Type"
                    value={form.type}
                    onChange={(v) => setForm((f) => ({ ...f, type: v }))}
                    options={TX_TYPES.map((t) => ({ value: t.value, label: t.label }))}
                  />
                  <FieldInput
                    label="Currency"
                    value={form.currency}
                    onChange={(v) => setForm((f) => ({ ...f, currency: v }))}
                  />
                </div>

                {/* Amount + Date */}
                <div className="grid grid-cols-2 gap-4">
                  <FieldInput
                    label="Amount"
                    type="number"
                    value={form.amount}
                    onChange={(v) => setForm((f) => ({ ...f, amount: v }))}
                    placeholder="0.00"
                  />
                  <FieldInput
                    label="Date"
                    type="date"
                    value={form.date}
                    onChange={(v) => setForm((f) => ({ ...f, date: v }))}
                  />
                </div>

                {/* Description */}
                <FieldInput
                  label="Description"
                  value={form.description}
                  onChange={(v) => setForm((f) => ({ ...f, description: v }))}
                  placeholder="e.g. Management fee Q1 2026"
                />

                {/* Journal Entry Link (optional) */}
                <FieldInput
                  label="Journal Entry ID (optional)"
                  value={form.journalEntryId}
                  onChange={(v) => setForm((f) => ({ ...f, journalEntryId: v }))}
                  placeholder="Leave blank if not linked"
                />
              </div>

              <div className="flex items-center justify-end gap-3 px-6 py-4 border-t border-[var(--ff-border-light)]">
                <button
                  onClick={() => setShowCreate(false)}
                  className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={handleCreate}
                  disabled={saving || !form.sourceCompanyId || !form.targetCompanyId || !form.amount}
                  className="flex items-center gap-2 px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 text-sm font-medium disabled:opacity-40 transition-colors"
                >
                  {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Plus className="h-4 w-4" />}
                  Record
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </AppLayout>
  );
}

/* ── Reusable sub-components ── */

function StatCard({
  label,
  value,
  sub,
  color,
}: {
  label: string;
  value: string;
  sub: string;
  color: string;
}) {
  return (
    <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
      <p className="text-xs text-[var(--ff-text-tertiary)] uppercase">{label}</p>
      <p className={`text-xl font-bold font-mono ${color}`}>{value}</p>
      <p className="text-xs text-[var(--ff-text-tertiary)]">{sub}</p>
    </div>
  );
}

function FieldInput({
  label,
  value,
  onChange,
  type = 'text',
  placeholder,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
  type?: string;
  placeholder?: string;
}) {
  return (
    <label className="block">
      <span className="text-xs text-[var(--ff-text-tertiary)] uppercase">{label}</span>
      <input
        type={type}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className="mt-1 w-full px-3 py-2 text-sm bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)] placeholder:text-[var(--ff-text-tertiary)]"
      />
    </label>
  );
}

function FieldSelect({
  label,
  value,
  onChange,
  options,
  placeholder,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
  options: { value: string; label: string }[];
  placeholder?: string;
}) {
  return (
    <label className="block">
      <span className="text-xs text-[var(--ff-text-tertiary)] uppercase">{label}</span>
      <select
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="mt-1 w-full px-3 py-2 text-sm bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)]"
      >
        {placeholder && <option value="">{placeholder}</option>}
        {options.map((o) => (
          <option key={o.value} value={o.value}>
            {o.label}
          </option>
        ))}
      </select>
    </label>
  );
}

/**
 * Consolidated Trial Balance Page
 * Shows trial balance across all entities in a group with elimination entries
 * and consolidated debit/credit totals.
 */

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Scale, Loader2, AlertCircle, Download, Building2 } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

interface EntityBalance {
  debit: number;
  credit: number;
}

interface ConsolidatedTBRow {
  groupAccountCode: string;
  groupAccountName: string;
  accountType: string;
  entities: { [companyId: string]: EntityBalance };
  eliminationDebit: number;
  eliminationCredit: number;
  consolidatedDebit: number;
  consolidatedCredit: number;
}

interface ConsolidatedTBResponse {
  rows: ConsolidatedTBRow[];
  entityNames: { [companyId: string]: string };
  totals: {
    entities: { [companyId: string]: EntityBalance };
    eliminationDebit: number;
    eliminationCredit: number;
    consolidatedDebit: number;
    consolidatedCredit: number;
  };
}

interface EntityGroup {
  id: string;
  name: string;
}

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

const fmt = (n: number) =>
  new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

const today = new Date();
const defaultPeriodStart = `${today.getFullYear()}-01-01`;
const defaultPeriodEnd = today.toISOString().substring(0, 10);

const selectClass =
  'px-3 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm';
const inputClass = selectClass;

/* ------------------------------------------------------------------ */
/*  Component                                                          */
/* ------------------------------------------------------------------ */

export default function ConsolidatedTrialBalancePage() {
  const [groups, setGroups] = useState<EntityGroup[]>([]);
  const [selectedGroupId, setSelectedGroupId] = useState('');
  const [periodStart, setPeriodStart] = useState(defaultPeriodStart);
  const [periodEnd, setPeriodEnd] = useState(defaultPeriodEnd);

  const [data, setData] = useState<ConsolidatedTBResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  /* ---------- Load available groups ---------- */
  useEffect(() => {
    apiFetch('/api/accounting/consolidated-reports?action=list-groups')
      .then(r => r.json())
      .then(json => {
        const items: EntityGroup[] = json.data?.groups || json.data || [];
        setGroups(items);
        if (items.length > 0 && !selectedGroupId && items[0]) {
          setSelectedGroupId(items[0].id);
        }
      })
      .catch(() => {
        // Non-critical — group list load failure
      });
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /* ---------- Load consolidated trial balance ---------- */
  const loadData = useCallback(async () => {
    if (!selectedGroupId) return;
    setLoading(true);
    setError('');
    try {
      const params = new URLSearchParams({
        group_id: selectedGroupId,
        action: 'trial-balance',
        period_start: periodStart,
        period_end: periodEnd,
      });
      const res = await apiFetch(`/api/accounting/consolidated-reports?${params}`);
      if (!res.ok) throw new Error('Failed to load consolidated trial balance');
      const json = await res.json();
      const payload: ConsolidatedTBResponse = json.data || json;
      setData(payload);
    } catch {
      setError('Failed to load consolidated trial balance');
      setData(null);
    } finally {
      setLoading(false);
    }
  }, [selectedGroupId, periodStart, periodEnd]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  /* ---------- Derived values ---------- */
  const entityIds = useMemo(() => {
    if (!data) return [];
    return Object.keys(data.entityNames).sort((a, b) =>
      (data.entityNames[a] || '').localeCompare(data.entityNames[b] || ''),
    );
  }, [data]);

  const totals = data?.totals;

  const consolidatedBalanced = useMemo(() => {
    if (!totals) return true;
    return Math.abs(totals.consolidatedDebit - totals.consolidatedCredit) < 0.02;
  }, [totals]);

  /* ---------- CSV Export ---------- */
  const handleExport = useCallback(() => {
    if (!data || data.rows.length === 0) return;

    const headerCols = ['Group Account Code', 'Account Name', 'Account Type'];
    entityIds.forEach(eid => {
      const name = data.entityNames[eid] || eid;
      headerCols.push(`${name} Debit`, `${name} Credit`);
    });
    headerCols.push(
      'Eliminations Debit',
      'Eliminations Credit',
      'Consolidated Debit',
      'Consolidated Credit',
    );

    const csvRows: string[] = [headerCols.map(c => `"${c}"`).join(',')];

    for (const row of data.rows) {
      const cols: string[] = [
        `"${row.groupAccountCode}"`,
        `"${row.groupAccountName}"`,
        `"${row.accountType}"`,
      ];
      entityIds.forEach(eid => {
        const eb = row.entities[eid];
        cols.push(String(eb?.debit ?? 0), String(eb?.credit ?? 0));
      });
      cols.push(
        String(row.eliminationDebit),
        String(row.eliminationCredit),
        String(row.consolidatedDebit),
        String(row.consolidatedCredit),
      );
      csvRows.push(cols.join(','));
    }

    // Totals row
    if (totals) {
      const tCols: string[] = ['""', '"TOTALS"', '""'];
      entityIds.forEach(eid => {
        const eb = totals.entities[eid];
        tCols.push(String(eb?.debit ?? 0), String(eb?.credit ?? 0));
      });
      tCols.push(
        String(totals.eliminationDebit),
        String(totals.eliminationCredit),
        String(totals.consolidatedDebit),
        String(totals.consolidatedCredit),
      );
      csvRows.push(tCols.join(','));
    }

    const blob = new Blob([csvRows.join('\n')], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `consolidated-trial-balance-${periodStart}-to-${periodEnd}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  }, [data, entityIds, totals, periodStart, periodEnd]);

  /* ---------- Row classification helpers ---------- */
  const hasElimination = (row: ConsolidatedTBRow) =>
    row.eliminationDebit > 0 || row.eliminationCredit > 0;

  const isUnmapped = (row: ConsolidatedTBRow) =>
    !row.groupAccountCode || row.groupAccountCode === '';

  /* ---------------------------------------------------------------- */
  /*  Render                                                           */
  /* ---------------------------------------------------------------- */
  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between flex-wrap gap-3">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-indigo-500/10">
                <Building2 className="h-6 w-6 text-indigo-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">
                  Consolidated Trial Balance
                </h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  Multi-entity trial balance with elimination entries
                </p>
              </div>
            </div>
            <div className="flex items-center gap-3 flex-wrap">
              {/* Group selector */}
              <select
                value={selectedGroupId}
                onChange={e => setSelectedGroupId(e.target.value)}
                className={selectClass}
              >
                {groups.length === 0 && <option value="">No groups</option>}
                {groups.map(g => (
                  <option key={g.id} value={g.id}>
                    {g.name}
                  </option>
                ))}
              </select>

              {/* Period start */}
              <input
                type="date"
                value={periodStart}
                onChange={e => setPeriodStart(e.target.value)}
                className={inputClass}
              />

              {/* Period end */}
              <input
                type="date"
                value={periodEnd}
                onChange={e => setPeriodEnd(e.target.value)}
                className={inputClass}
              />

              {/* Export */}
              <button
                onClick={handleExport}
                disabled={!data || data.rows.length === 0}
                className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium disabled:opacity-50"
              >
                <Download className="h-4 w-4" /> Export CSV
              </button>
            </div>
          </div>
        </div>

        <div className="p-6">
          {/* Summary cards */}
          {!loading && data && data.rows.length > 0 && totals && (
            <div className="grid grid-cols-3 gap-4 mb-6">
              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
                <p className="text-xs text-[var(--ff-text-tertiary)] mb-1">
                  Consolidated Debits
                </p>
                <p className="text-xl font-bold text-[var(--ff-text-primary)]">
                  {fmt(totals.consolidatedDebit)}
                </p>
              </div>
              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
                <p className="text-xs text-[var(--ff-text-tertiary)] mb-1">
                  Consolidated Credits
                </p>
                <p className="text-xl font-bold text-[var(--ff-text-primary)]">
                  {fmt(totals.consolidatedCredit)}
                </p>
              </div>
              <div
                className={`rounded-lg border p-4 ${
                  consolidatedBalanced
                    ? 'bg-teal-500/5 border-teal-500/30'
                    : 'bg-red-500/5 border-red-500/30'
                }`}
              >
                <p className="text-xs text-[var(--ff-text-tertiary)] mb-1">Difference</p>
                <p
                  className={`text-xl font-bold ${
                    consolidatedBalanced ? 'text-teal-400' : 'text-red-400'
                  }`}
                >
                  {fmt(Math.abs(totals.consolidatedDebit - totals.consolidatedCredit))}
                  <span className="text-sm ml-2">
                    {consolidatedBalanced ? 'Balanced' : 'Out of Balance'}
                  </span>
                </p>
              </div>
            </div>
          )}

          {/* States: loading / error / empty / table */}
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-indigo-500" />
            </div>
          ) : error ? (
            <div className="flex items-center gap-2 text-red-400 py-8 justify-center">
              <AlertCircle className="h-5 w-5" />
              <span>{error}</span>
            </div>
          ) : !data || data.rows.length === 0 ? (
            <div className="text-center py-12">
              <Scale className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-3" />
              <p className="text-[var(--ff-text-secondary)]">
                No consolidated trial balance data
              </p>
              <p className="text-sm text-[var(--ff-text-tertiary)] mt-1">
                Select a group and date range with posted journal entries
              </p>
            </div>
          ) : (
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-x-auto">
              <table className="w-full text-sm whitespace-nowrap">
                <thead>
                  <tr className="border-b border-[var(--ff-border-light)] text-left text-[var(--ff-text-secondary)]">
                    <th className="px-4 py-3 sticky left-0 bg-[var(--ff-bg-secondary)] z-10">
                      Code
                    </th>
                    <th className="px-4 py-3 sticky left-[80px] bg-[var(--ff-bg-secondary)] z-10">
                      Account Name
                    </th>
                    {/* Per-entity column pairs */}
                    {entityIds.map(eid => (
                      <th
                        key={eid}
                        colSpan={2}
                        className="px-4 py-3 text-center border-l border-[var(--ff-border-light)]"
                      >
                        {data.entityNames[eid]}
                      </th>
                    ))}
                    {/* Eliminations */}
                    <th
                      colSpan={2}
                      className="px-4 py-3 text-center border-l border-[var(--ff-border-light)] text-amber-400"
                    >
                      Eliminations
                    </th>
                    {/* Consolidated */}
                    <th
                      colSpan={2}
                      className="px-4 py-3 text-center border-l-2 border-[var(--ff-border-light)] font-bold"
                    >
                      Consolidated
                    </th>
                  </tr>
                  {/* Sub-header: Debit / Credit for each group */}
                  <tr className="border-b border-[var(--ff-border-light)] text-xs text-[var(--ff-text-tertiary)]">
                    <th className="px-4 py-2 sticky left-0 bg-[var(--ff-bg-secondary)] z-10" />
                    <th className="px-4 py-2 sticky left-[80px] bg-[var(--ff-bg-secondary)] z-10" />
                    {entityIds.map(eid => (
                      <React.Fragment key={`sub-${eid}`}>
                        <th className="px-4 py-2 text-right border-l border-[var(--ff-border-light)]">
                          Debit
                        </th>
                        <th className="px-4 py-2 text-right">Credit</th>
                      </React.Fragment>
                    ))}
                    <th className="px-4 py-2 text-right border-l border-[var(--ff-border-light)]">
                      Debit
                    </th>
                    <th className="px-4 py-2 text-right">Credit</th>
                    <th className="px-4 py-2 text-right border-l-2 border-[var(--ff-border-light)]">
                      Debit
                    </th>
                    <th className="px-4 py-2 text-right">Credit</th>
                  </tr>
                </thead>
                <tbody>
                  {data.rows.map(row => {
                    const elimRow = hasElimination(row);
                    const unmapped = isUnmapped(row);
                    const rowBg = unmapped
                      ? 'bg-red-500/10'
                      : elimRow
                        ? 'bg-amber-500/5'
                        : '';
                    return (
                      <tr
                        key={row.groupAccountCode || row.groupAccountName}
                        className={`border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-primary)]/50 ${rowBg}`}
                      >
                        <td className="px-4 py-3 font-mono text-[var(--ff-text-tertiary)] sticky left-0 bg-[var(--ff-bg-secondary)] z-10">
                          <span className="flex items-center gap-1">
                            {unmapped && (
                              <AlertCircle className="h-3.5 w-3.5 text-red-400 shrink-0" />
                            )}
                            {row.groupAccountCode || '—'}
                          </span>
                        </td>
                        <td className="px-4 py-3 text-[var(--ff-text-primary)] sticky left-[80px] bg-[var(--ff-bg-secondary)] z-10">
                          {row.groupAccountName}
                        </td>
                        {/* Entity columns */}
                        {entityIds.map(eid => {
                          const eb = row.entities[eid];
                          return (
                            <React.Fragment key={eid}>
                              <td className="px-4 py-3 text-right text-[var(--ff-text-primary)] border-l border-[var(--ff-border-light)]">
                                {(eb?.debit ?? 0) > 0 ? fmt(eb?.debit ?? 0) : '—'}
                              </td>
                              <td className="px-4 py-3 text-right text-[var(--ff-text-primary)]">
                                {(eb?.credit ?? 0) > 0 ? fmt(eb?.credit ?? 0) : '—'}
                              </td>
                            </React.Fragment>
                          );
                        })}
                        {/* Eliminations */}
                        <td className="px-4 py-3 text-right border-l border-[var(--ff-border-light)] text-amber-400">
                          {row.eliminationDebit > 0 ? fmt(row.eliminationDebit) : '—'}
                        </td>
                        <td className="px-4 py-3 text-right text-amber-400">
                          {row.eliminationCredit > 0 ? fmt(row.eliminationCredit) : '—'}
                        </td>
                        {/* Consolidated */}
                        <td className="px-4 py-3 text-right font-semibold text-[var(--ff-text-primary)] border-l-2 border-[var(--ff-border-light)]">
                          {row.consolidatedDebit > 0 ? fmt(row.consolidatedDebit) : '—'}
                        </td>
                        <td className="px-4 py-3 text-right font-semibold text-[var(--ff-text-primary)]">
                          {row.consolidatedCredit > 0 ? fmt(row.consolidatedCredit) : '—'}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
                <tfoot>
                  <tr className="border-t-2 border-[var(--ff-border-light)] font-bold">
                    <td className="px-4 py-3 text-[var(--ff-text-primary)] sticky left-0 bg-[var(--ff-bg-secondary)] z-10">
                      TOTALS
                    </td>
                    <td className="px-4 py-3 sticky left-[80px] bg-[var(--ff-bg-secondary)] z-10" />
                    {entityIds.map(eid => {
                      const eb = totals?.entities[eid];
                      return (
                        <React.Fragment key={`tot-${eid}`}>
                          <td className="px-4 py-3 text-right text-[var(--ff-text-primary)] border-l border-[var(--ff-border-light)]">
                            {fmt(eb?.debit ?? 0)}
                          </td>
                          <td className="px-4 py-3 text-right text-[var(--ff-text-primary)]">
                            {fmt(eb?.credit ?? 0)}
                          </td>
                        </React.Fragment>
                      );
                    })}
                    <td className="px-4 py-3 text-right border-l border-[var(--ff-border-light)] text-amber-400">
                      {fmt(totals?.eliminationDebit ?? 0)}
                    </td>
                    <td className="px-4 py-3 text-right text-amber-400">
                      {fmt(totals?.eliminationCredit ?? 0)}
                    </td>
                    <td className="px-4 py-3 text-right border-l-2 border-[var(--ff-border-light)] text-[var(--ff-text-primary)]">
                      {fmt(totals?.consolidatedDebit ?? 0)}
                    </td>
                    <td className="px-4 py-3 text-right text-[var(--ff-text-primary)]">
                      {fmt(totals?.consolidatedCredit ?? 0)}
                    </td>
                  </tr>
                </tfoot>
              </table>
            </div>
          )}

          {/* Balance check footer */}
          {!loading && data && data.rows.length > 0 && totals && (
            <div className="mt-4 flex items-center gap-4 text-sm">
              <div
                className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-lg ${
                  consolidatedBalanced
                    ? 'bg-teal-500/10 text-teal-400'
                    : 'bg-red-500/10 text-red-400'
                }`}
              >
                {consolidatedBalanced ? (
                  <Scale className="h-4 w-4" />
                ) : (
                  <AlertCircle className="h-4 w-4" />
                )}
                {consolidatedBalanced
                  ? 'Consolidated trial balance is in balance'
                  : `Out of balance by ${fmt(Math.abs(totals.consolidatedDebit - totals.consolidatedCredit))}`}
              </div>
              {data.rows.some(isUnmapped) && (
                <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-lg bg-red-500/10 text-red-400">
                  <AlertCircle className="h-4 w-4" />
                  Unmapped accounts detected — review group account mappings
                </div>
              )}
              {data.rows.some(hasElimination) && (
                <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-lg bg-amber-500/10 text-amber-400">
