        period_end: periodEnd,
      });
      const res = await apiFetch(`/api/accounting/consolidated-reports?${params}`);
      if (!res.ok) throw new Error('Failed to load consolidated trial balance');
      const json = await res.json();
      const payload: ConsolidatedTBResponse = json.data || json;
      setData(payload);
    } catch {
      setError('Failed to load consolidated trial balance');
      setData(null);
    } finally {
      setLoading(false);
    }
  }, [selectedGroupId, periodStart, periodEnd]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  /* ---------- Derived values ---------- */
  const entityIds = useMemo(() => {
    if (!data) return [];
    return Object.keys(data.entityNames).sort((a, b) =>
      (data.entityNames[a] || '').localeCompare(data.entityNames[b] || ''),
    );
  }, [data]);

  const totals = data?.totals;

  const consolidatedBalanced = useMemo(() => {
    if (!totals) return true;
    return Math.abs(totals.consolidatedDebit - totals.consolidatedCredit) < 0.02;
  }, [totals]);

  /* ---------- CSV Export ---------- */
  const handleExport = useCallback(() => {
    if (!data || data.rows.length === 0) return;

    const headerCols = ['Group Account Code', 'Account Name', 'Account Type'];
    entityIds.forEach(eid => {
      const name = data.entityNames[eid] || eid;
      headerCols.push(`${name} Debit`, `${name} Credit`);
    });
    headerCols.push(
      'Eliminations Debit',
      'Eliminations Credit',
      'Consolidated Debit',
      'Consolidated Credit',
    );

    const csvRows: string[] = [headerCols.map(c => `"${c}"`).join(',')];

    for (const row of data.rows) {
      const cols: string[] = [
        `"${row.groupAccountCode}"`,
        `"${row.groupAccountName}"`,
        `"${row.accountType}"`,
      ];
      entityIds.forEach(eid => {
        const eb = row.entities[eid];
        cols.push(String(eb?.debit ?? 0), String(eb?.credit ?? 0));
      });
      cols.push(
        String(row.eliminationDebit),
        String(row.eliminationCredit),
        String(row.consolidatedDebit),
        String(row.consolidatedCredit),
      );
      csvRows.push(cols.join(','));
    }

    // Totals row
    if (totals) {
      const tCols: string[] = ['""', '"TOTALS"', '""'];
      entityIds.forEach(eid => {
        const eb = totals.entities[eid];
        tCols.push(String(eb?.debit ?? 0), String(eb?.credit ?? 0));
      });
      tCols.push(
        String(totals.eliminationDebit),
        String(totals.eliminationCredit),
        String(totals.consolidatedDebit),
        String(totals.consolidatedCredit),
      );
      csvRows.push(tCols.join(','));
    }

    const blob = new Blob([csvRows.join('\n')], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `consolidated-trial-balance-${periodStart}-to-${periodEnd}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  }, [data, entityIds, totals, periodStart, periodEnd]);

  /* ---------- Row classification helpers ---------- */
  const hasElimination = (row: ConsolidatedTBRow) =>
    row.eliminationDebit > 0 || row.eliminationCredit > 0;

  const isUnmapped = (row: ConsolidatedTBRow) =>
    !row.groupAccountCode || row.groupAccountCode === '';

  /* ---------------------------------------------------------------- */
  /*  Render                                                           */
  /* ---------------------------------------------------------------- */
  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between flex-wrap gap-3">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-indigo-500/10">
                <Building2 className="h-6 w-6 text-indigo-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">
                  Consolidated Trial Balance
                </h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  Multi-entity trial balance with elimination entries
                </p>
              </div>
            </div>
            <div className="flex items-center gap-3 flex-wrap">
              {/* Group selector */}
              <select
                value={selectedGroupId}
                onChange={e => setSelectedGroupId(e.target.value)}
                className={selectClass}
              >
                {groups.length === 0 && <option value="">No groups</option>}
                {groups.map(g => (
                  <option key={g.id} value={g.id}>
                    {g.name}
                  </option>
                ))}
              </select>

              {/* Period start */}
              <input
                type="date"
                value={periodStart}
                onChange={e => setPeriodStart(e.target.value)}
                className={inputClass}
              />

              {/* Period end */}
              <input
                type="date"
                value={periodEnd}
                onChange={e => setPeriodEnd(e.target.value)}
                className={inputClass}
              />

              {/* Export */}
              <button
                onClick={handleExport}
                disabled={!data || data.rows.length === 0}
                className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium disabled:opacity-50"
              >
                <Download className="h-4 w-4" /> Export CSV
              </button>
            </div>
          </div>
        </div>

        <div className="p-6">
          {/* Summary cards */}
          {!loading && data && data.rows.length > 0 && totals && (
            <div className="grid grid-cols-3 gap-4 mb-6">
              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
                <p className="text-xs text-[var(--ff-text-tertiary)] mb-1">
                  Consolidated Debits
                </p>
                <p className="text-xl font-bold text-[var(--ff-text-primary)]">
                  {fmt(totals.consolidatedDebit)}
                </p>
              </div>
              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
                <p className="text-xs text-[var(--ff-text-tertiary)] mb-1">
                  Consolidated Credits
                </p>
                <p className="text-xl font-bold text-[var(--ff-text-primary)]">
                  {fmt(totals.consolidatedCredit)}
                </p>
              </div>
              <div
                className={`rounded-lg border p-4 ${
                  consolidatedBalanced
                    ? 'bg-teal-500/5 border-teal-500/30'
                    : 'bg-red-500/5 border-red-500/30'
                }`}
              >
                <p className="text-xs text-[var(--ff-text-tertiary)] mb-1">Difference</p>
                <p
                  className={`text-xl font-bold ${
                    consolidatedBalanced ? 'text-teal-400' : 'text-red-400'
                  }`}
                >
                  {fmt(Math.abs(totals.consolidatedDebit - totals.consolidatedCredit))}
                  <span className="text-sm ml-2">
                    {consolidatedBalanced ? 'Balanced' : 'Out of Balance'}
                  </span>
                </p>
              </div>
            </div>
          )}

          {/* States: loading / error / empty / table */}
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-indigo-500" />
            </div>
          ) : error ? (
            <div className="flex items-center gap-2 text-red-400 py-8 justify-center">
              <AlertCircle className="h-5 w-5" />
              <span>{error}</span>
            </div>
          ) : !data || data.rows.length === 0 ? (
            <div className="text-center py-12">
              <Scale className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-3" />
              <p className="text-[var(--ff-text-secondary)]">
                No consolidated trial balance data
              </p>
              <p className="text-sm text-[var(--ff-text-tertiary)] mt-1">
                Select a group and date range with posted journal entries
              </p>
            </div>
          ) : (
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-x-auto">
              <table className="w-full text-sm whitespace-nowrap">
                <thead>
                  <tr className="border-b border-[var(--ff-border-light)] text-left text-[var(--ff-text-secondary)]">
                    <th className="px-4 py-3 sticky left-0 bg-[var(--ff-bg-secondary)] z-10">
                      Code
                    </th>
                    <th className="px-4 py-3 sticky left-[80px] bg-[var(--ff-bg-secondary)] z-10">
                      Account Name
                    </th>
                    {/* Per-entity column pairs */}
                    {entityIds.map(eid => (
                      <th
                        key={eid}
                        colSpan={2}
                        className="px-4 py-3 text-center border-l border-[var(--ff-border-light)]"
                      >
                        {data.entityNames[eid]}
                      </th>
                    ))}
                    {/* Eliminations */}
                    <th
                      colSpan={2}
                      className="px-4 py-3 text-center border-l border-[var(--ff-border-light)] text-amber-400"
                    >
                      Eliminations
                    </th>
                    {/* Consolidated */}
                    <th
                      colSpan={2}
                      className="px-4 py-3 text-center border-l-2 border-[var(--ff-border-light)] font-bold"
                    >
                      Consolidated
                    </th>
                  </tr>
                  {/* Sub-header: Debit / Credit for each group */}
                  <tr className="border-b border-[var(--ff-border-light)] text-xs text-[var(--ff-text-tertiary)]">
                    <th className="px-4 py-2 sticky left-0 bg-[var(--ff-bg-secondary)] z-10" />
                    <th className="px-4 py-2 sticky left-[80px] bg-[var(--ff-bg-secondary)] z-10" />
                    {entityIds.map(eid => (
                      <React.Fragment key={`sub-${eid}`}>
                        <th className="px-4 py-2 text-right border-l border-[var(--ff-border-light)]">
                          Debit
                        </th>
                        <th className="px-4 py-2 text-right">Credit</th>
                      </React.Fragment>
                    ))}
                    <th className="px-4 py-2 text-right border-l border-[var(--ff-border-light)]">
                      Debit
                    </th>
                    <th className="px-4 py-2 text-right">Credit</th>
                    <th className="px-4 py-2 text-right border-l-2 border-[var(--ff-border-light)]">
                      Debit
                    </th>
                    <th className="px-4 py-2 text-right">Credit</th>
                  </tr>
                </thead>
                <tbody>
                  {data.rows.map(row => {
                    const elimRow = hasElimination(row);
                    const unmapped = isUnmapped(row);
                    const rowBg = unmapped
                      ? 'bg-red-500/10'
                      : elimRow
                        ? 'bg-amber-500/5'
                        : '';
                    return (
                      <tr
                        key={row.groupAccountCode || row.groupAccountName}
                        className={`border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-primary)]/50 ${rowBg}`}
                      >
                        <td className="px-4 py-3 font-mono text-[var(--ff-text-tertiary)] sticky left-0 bg-[var(--ff-bg-secondary)] z-10">
                          <span className="flex items-center gap-1">
                            {unmapped && (
                              <AlertCircle className="h-3.5 w-3.5 text-red-400 shrink-0" />
                            )}
                            {row.groupAccountCode || '—'}
                          </span>
                        </td>
                        <td className="px-4 py-3 text-[var(--ff-text-primary)] sticky left-[80px] bg-[var(--ff-bg-secondary)] z-10">
                          {row.groupAccountName}
                        </td>
                        {/* Entity columns */}
                        {entityIds.map(eid => {
                          const eb = row.entities[eid];
                          return (
                            <React.Fragment key={eid}>
                              <td className="px-4 py-3 text-right text-[var(--ff-text-primary)] border-l border-[var(--ff-border-light)]">
                                {(eb?.debit ?? 0) > 0 ? fmt(eb?.debit ?? 0) : '—'}
                              </td>
                              <td className="px-4 py-3 text-right text-[var(--ff-text-primary)]">
                                {(eb?.credit ?? 0) > 0 ? fmt(eb?.credit ?? 0) : '—'}
                              </td>
                            </React.Fragment>
                          );
                        })}
                        {/* Eliminations */}
                        <td className="px-4 py-3 text-right border-l border-[var(--ff-border-light)] text-amber-400">
                          {row.eliminationDebit > 0 ? fmt(row.eliminationDebit) : '—'}
                        </td>
                        <td className="px-4 py-3 text-right text-amber-400">
                          {row.eliminationCredit > 0 ? fmt(row.eliminationCredit) : '—'}
                        </td>
                        {/* Consolidated */}
                        <td className="px-4 py-3 text-right font-semibold text-[var(--ff-text-primary)] border-l-2 border-[var(--ff-border-light)]">
                          {row.consolidatedDebit > 0 ? fmt(row.consolidatedDebit) : '—'}
                        </td>
                        <td className="px-4 py-3 text-right font-semibold text-[var(--ff-text-primary)]">
                          {row.consolidatedCredit > 0 ? fmt(row.consolidatedCredit) : '—'}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
                <tfoot>
                  <tr className="border-t-2 border-[var(--ff-border-light)] font-bold">
                    <td className="px-4 py-3 text-[var(--ff-text-primary)] sticky left-0 bg-[var(--ff-bg-secondary)] z-10">
                      TOTALS
                    </td>
                    <td className="px-4 py-3 sticky left-[80px] bg-[var(--ff-bg-secondary)] z-10" />
                    {entityIds.map(eid => {
                      const eb = totals?.entities[eid];
                      return (
                        <React.Fragment key={`tot-${eid}`}>
                          <td className="px-4 py-3 text-right text-[var(--ff-text-primary)] border-l border-[var(--ff-border-light)]">
                            {fmt(eb?.debit ?? 0)}
                          </td>
                          <td className="px-4 py-3 text-right text-[var(--ff-text-primary)]">
                            {fmt(eb?.credit ?? 0)}
                          </td>
                        </React.Fragment>
                      );
                    })}
                    <td className="px-4 py-3 text-right border-l border-[var(--ff-border-light)] text-amber-400">
                      {fmt(totals?.eliminationDebit ?? 0)}
                    </td>
                    <td className="px-4 py-3 text-right text-amber-400">
                      {fmt(totals?.eliminationCredit ?? 0)}
                    </td>
                    <td className="px-4 py-3 text-right border-l-2 border-[var(--ff-border-light)] text-[var(--ff-text-primary)]">
                      {fmt(totals?.consolidatedDebit ?? 0)}
                    </td>
                    <td className="px-4 py-3 text-right text-[var(--ff-text-primary)]">
                      {fmt(totals?.consolidatedCredit ?? 0)}
                    </td>
                  </tr>
                </tfoot>
              </table>
            </div>
          )}

          {/* Balance check footer */}
          {!loading && data && data.rows.length > 0 && totals && (
            <div className="mt-4 flex items-center gap-4 text-sm">
              <div
                className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-lg ${
                  consolidatedBalanced
                    ? 'bg-teal-500/10 text-teal-400'
                    : 'bg-red-500/10 text-red-400'
                }`}
              >
                {consolidatedBalanced ? (
                  <Scale className="h-4 w-4" />
                ) : (
                  <AlertCircle className="h-4 w-4" />
                )}
                {consolidatedBalanced
                  ? 'Consolidated trial balance is in balance'
                  : `Out of balance by ${fmt(Math.abs(totals.consolidatedDebit - totals.consolidatedCredit))}`}
              </div>
              {data.rows.some(isUnmapped) && (
                <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-lg bg-red-500/10 text-red-400">
                  <AlertCircle className="h-4 w-4" />
                  Unmapped accounts detected — review group account mappings
                </div>
              )}
              {data.rows.some(hasElimination) && (
                <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-lg bg-amber-500/10 text-amber-400">
                  <Scale className="h-4 w-4" />
                  Rows with elimination entries highlighted in amber
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Income Statement (P&L) Report Page
 * PRD-060 Phase 5: Revenue, Cost of Sales, Operating Expenses
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, BarChart3, Loader2, AlertCircle, ChevronDown, ChevronRight, Download } from 'lucide-react';
import type { IncomeStatementReport, IncomeStatementLineItem } from '@/modules/accounting/types/gl.types';
import { AccountDrillDown } from '@/components/accounting/AccountDrillDown';

import { formatCurrency } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

interface CostCentre { id: string; code: string; name: string }

function getDefaultDates(): { periodStart: string; periodEnd: string } {
  const now = new Date();
  const start = new Date(now.getFullYear(), now.getMonth(), 1);
  return {
    periodStart: start.toISOString().split('T')[0] ?? '',
    periodEnd: now.toISOString().split('T')[0] ?? '',
  };
}

export default function IncomeStatementPage() {
  const defaults = getDefaultDates();
  const [periodStart, setPeriodStart] = useState(defaults.periodStart);
  const [periodEnd, setPeriodEnd] = useState(defaults.periodEnd);
  const [report, setReport] = useState<IncomeStatementReport | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [expandedAccount, setExpandedAccount] = useState<string | null>(null);
  const [costCentres, setCostCentres] = useState<CostCentre[]>([]);
  const [costCentreId, setCostCentreId] = useState('');
  const [showComparative, setShowComparative] = useState(false);

  useEffect(() => {
    apiFetch('/api/accounting/cost-centres?active_only=true', { credentials: 'include' })
      .then(r => r.json())
      .then(json => setCostCentres(json.data?.items || json.data || []))
      .catch(() => { /* reference data load failure — non-critical, cost centre filter will be empty */ });
  }, []);

  function handleExport() {
    const params = new URLSearchParams({ period_start: periodStart, period_end: periodEnd });
    if (costCentreId) params.set('cost_centre_id', costCentreId);
    window.open(`/api/accounting/income-statement-export?${params}`, '_blank');
  }

  function toggleAccount(code: string) {
    setExpandedAccount(prev => (prev === code ? null : code));
  }

  const loadReport = useCallback(async () => {
    if (!periodStart || !periodEnd) return;
    setIsLoading(true);
    setError('');
    try {
      const params = new URLSearchParams({ period_start: periodStart, period_end: periodEnd });
      if (costCentreId) params.set('cost_centre_id', costCentreId);
      if (showComparative) {
        const start = new Date(periodStart);
        const end = new Date(periodEnd);
        const durationMs = end.getTime() - start.getTime();
        const priorEnd = new Date(start.getTime() - 1);
        const priorStart = new Date(priorEnd.getTime() - durationMs);
        params.set('compare_start', priorStart.toISOString().split('T')[0] ?? '');
        params.set('compare_end', priorEnd.toISOString().split('T')[0] ?? '');
      }
      const res = await apiFetch(`/api/accounting/reports-income-statement?${params}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to load');
      setReport(json.data || json);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load income statement');
    } finally {
      setIsLoading(false);
    }
  }, [periodStart, periodEnd, costCentreId, showComparative]);

  useEffect(() => { loadReport(); }, [loadReport]);

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <Link href="/accounting?tab=reports" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] mb-2">
              <ArrowLeft className="h-4 w-4" /> Back to Reports
            </Link>
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="p-2 rounded-lg bg-teal-500/10">
                  <BarChart3 className="h-6 w-6 text-teal-500" />
                </div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Income Statement</h1>
              </div>
              <button onClick={handleExport} disabled={!report}
                className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 text-sm font-medium disabled:opacity-50">
                <Download className="h-4 w-4" /> Export CSV
              </button>
            </div>
          </div>
        </div>

        <div className="p-6 max-w-4xl space-y-6">
          {/* Date Range + Filters */}
          <div className="flex flex-wrap items-end gap-4">
            <div>
              <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">From</label>
              <input type="date" value={periodStart} onChange={e => setPeriodStart(e.target.value)} className="ff-input text-sm" />
            </div>
            <div>
              <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">To</label>
              <input type="date" value={periodEnd} onChange={e => setPeriodEnd(e.target.value)} className="ff-input text-sm" />
            </div>
            <div>
              <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Cost Centre</label>
              <select value={costCentreId} onChange={e => setCostCentreId(e.target.value)}
                className="ff-input text-sm min-w-[160px]">
                <option value="">All Cost Centres</option>
                {costCentres.map(cc => (
                  <option key={cc.id} value={cc.id}>{cc.code} — {cc.name}</option>
                ))}
              </select>
            </div>
            <label className="flex items-center gap-2 text-sm text-[var(--ff-text-secondary)] cursor-pointer select-none pb-1">
              <input type="checkbox" checked={showComparative} onChange={e => setShowComparative(e.target.checked)}
                className="rounded border-[var(--ff-border-light)]" />
              Compare prior period
            </label>
          </div>

          {error && (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">
              <AlertCircle className="h-4 w-4" /> {error}
            </div>
          )}

          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-6 w-6 animate-spin text-teal-500" />
            </div>
          ) : report ? (
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
              <div className="px-6 py-4 border-b border-[var(--ff-border-light)]">
                <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
                  Profit &amp; Loss — {periodStart} to {periodEnd}
                </h2>
              </div>

              <div className="divide-y divide-[var(--ff-border-light)]">
                {/* Revenue */}
                <Section label="Revenue" items={report.revenue} total={report.totalRevenue} color="teal"
                  periodStart={periodStart} periodEnd={periodEnd} expandedAccount={expandedAccount}
                  onToggleAccount={toggleAccount} showComparative={showComparative} />

                {/* Cost of Sales */}
                {report.costOfSales.length > 0 && (
                  <Section label="Cost of Sales" items={report.costOfSales} total={report.totalCostOfSales} color="orange"
                    periodStart={periodStart} periodEnd={periodEnd} expandedAccount={expandedAccount}
                    onToggleAccount={toggleAccount} showComparative={showComparative} />
                )}

                {/* Gross Profit */}
                <div className="px-6 py-3 flex justify-between bg-teal-500/5">
                  <span className="font-semibold text-[var(--ff-text-primary)]">Gross Profit</span>
                  <span className={`font-bold font-mono ${report.grossProfit >= 0 ? 'text-teal-400' : 'text-red-400'}`}>
                    {formatCurrency(report.grossProfit)}
                    {showComparative && report.priorGrossProfit !== undefined && (
                      <span className="text-xs text-[var(--ff-text-tertiary)] ml-2">
                        (prior: {formatCurrency(report.priorGrossProfit)})
                      </span>
                    )}
                  </span>
                </div>

                {/* Operating Expenses */}
                <Section label="Operating Expenses" items={report.operatingExpenses} total={report.totalOperatingExpenses} color="red"
                  periodStart={periodStart} periodEnd={periodEnd} expandedAccount={expandedAccount}
                  onToggleAccount={toggleAccount} showComparative={showComparative} />

                {/* Net Profit */}
                <div className="px-6 py-4 flex justify-between bg-[var(--ff-bg-primary)]">
                  <span className="text-lg font-bold text-[var(--ff-text-primary)]">Net Profit / (Loss)</span>
                  <span className={`text-xl font-bold font-mono ${report.netProfit >= 0 ? 'text-teal-400' : 'text-red-400'}`}>
                    {formatCurrency(report.netProfit)}
                    {showComparative && report.priorNetProfit !== undefined && (
                      <span className="text-xs text-[var(--ff-text-tertiary)] ml-2">
                        (prior: {formatCurrency(report.priorNetProfit)})
                      </span>
                    )}
                  </span>
                </div>
              </div>
            </div>
          ) : null}
        </div>
      </div>
    </AppLayout>
  );
}

function Section({ label, items, total, color, periodStart, periodEnd, expandedAccount, onToggleAccount, showComparative }: {
  label: string;
  items: IncomeStatementLineItem[];
  total: number;
  color: string;
  periodStart: string;
  periodEnd: string;
  expandedAccount: string | null;
  onToggleAccount: (code: string) => void;
  showComparative: boolean;
}) {
  return (
    <div>
      <div className={`px-6 py-2 bg-${color}-500/5 flex items-center`}>
        <span className={`text-sm font-semibold text-${color}-400`}>{label}</span>
        {showComparative ? (
          <span className="flex items-center gap-4 text-xs text-[var(--ff-text-tertiary)] ml-auto">
            <span className="w-28 text-right">Prior</span>
            <span className="w-28 text-right">Current</span>
            <span className="w-20 text-right">Variance</span>
          </span>
        ) : (
          <span className="text-xs text-[var(--ff-text-tertiary)] ml-auto">Click account to expand</span>
        )}
      </div>
      {items.map(item => {
        const isExpanded = expandedAccount === item.accountCode;
        return (
          <div key={item.accountCode}>
            <button
              type="button"
              onClick={() => onToggleAccount(item.accountCode)}
              className="w-full px-6 py-2 flex justify-between items-center text-sm hover:bg-[var(--ff-bg-tertiary)] cursor-pointer text-left"
            >
              <span className="flex items-center gap-1 text-[var(--ff-text-secondary)] flex-1">
                {isExpanded
                  ? <ChevronDown className="h-3 w-3 shrink-0 text-[var(--ff-text-tertiary)]" />
                  : <ChevronRight className="h-3 w-3 shrink-0 text-[var(--ff-text-tertiary)]" />}
                <span className="font-mono text-xs mr-1">{item.accountCode}</span>
                {item.accountName}
              </span>
              {showComparative && item.priorAmount !== undefined ? (
                <span className="flex items-center gap-4">
                  <span className="font-mono text-[var(--ff-text-tertiary)] w-28 text-right text-xs">{formatCurrency(item.priorAmount)}</span>
                  <span className="font-mono text-[var(--ff-text-primary)] w-28 text-right">{formatCurrency(item.amount)}</span>
                  <span className={`font-mono w-20 text-right text-xs ${(item.variance ?? 0) >= 0 ? 'text-teal-400' : 'text-red-400'}`}>
                    {(item.variance ?? 0) >= 0 ? '+' : ''}{formatCurrency(item.variance ?? 0)}
                  </span>
                </span>
              ) : (
                <span className="font-mono text-[var(--ff-text-primary)]">{formatCurrency(item.amount)}</span>
              )}
            </button>
            {isExpanded && (
              <div className="px-6 pb-3">
                <AccountDrillDown accountCode={item.accountCode} periodStart={periodStart} periodEnd={periodEnd} />
              </div>
            )}
          </div>
        );
      })}
      {items.length === 0 && (
        <div className="px-6 py-2 text-sm text-[var(--ff-text-tertiary)]">No entries</div>
      )}
      <div className="px-6 py-2 flex justify-between border-t border-[var(--ff-border-light)]">
        <span className="text-sm font-medium text-[var(--ff-text-primary)]">Total {label}</span>
        <span className="font-mono font-medium text-[var(--ff-text-primary)]">{formatCurrency(total)}</span>
      </div>
    </div>
  );
}

/**
 * Fetch wrapper that automatically injects the active company ID header.
 * Use this instead of raw fetch() for all accounting API calls.
 */

const COMPANY_STORAGE_KEY = 'isaflow_active_company';

export async function apiFetch(url: string, options?: RequestInit): Promise<Response> {
  const headers = new Headers(options?.headers);

  if (typeof window !== 'undefined') {
    const stored = localStorage.getItem(COMPANY_STORAGE_KEY);
    if (stored) {
      try {
        const { id } = JSON.parse(stored);
        if (id) headers.set('X-Company-Id', id);
      } catch {
        // Invalid JSON — ignore
      }
    }
  }

  return fetch(url, {
    ...options,
    headers,
    credentials: 'include',
  });
}

