              <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                <div>
                  <label className={LABEL_CLS}>Company *</label>
                  <select
                    className={INPUT_CLS}
                    value={newMember.company_id}
                    onChange={e => setNewMember({ ...newMember, company_id: e.target.value })}
