/**
 * Sidebar navigation that mirrors the top-bar AccountingNav.
 * Uses the same TABS config from accountingNavConfig.ts.
 * Renders as an accordion with collapsible sections.
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { ChevronDown, ChevronRight } from 'lucide-react';
import {
  TABS,
  getActiveTabId,
  isFlyout,
  isLinkActive,
  type Tab,
  type NavItem,
  type DropdownItem,
} from '../accounting/accountingNavConfig';

// ─── Helpers ────────────────────────────────────────────────────────────────

function collectLinks(items: NavItem[]): DropdownItem[] {
  const links: DropdownItem[] = [];
  for (const item of items) {
    if (isFlyout(item)) {
      links.push(...collectLinks(item.items));
    } else {
      links.push(item);
    }
  }
  return links;
}

function isTabActive(tab: Tab, pathname: string, query: Record<string, string | string[] | undefined>): boolean {
  return getActiveTabId(pathname, query) === tab.id;
}

// ─── Section renderer (recursive for nested flyouts) ────────────────────────

function SidebarSection({
  label,
  items,
  asPath,
  depth,
}: {
  label: string;
  items: NavItem[];
  asPath: string;
  depth: number;
}) {
  const [open, setOpen] = useState(false);

  // Auto-open if any child link is active
  useEffect(() => {
    const links = collectLinks(items);
    if (links.some(l => isLinkActive(l.href, asPath))) {
      setOpen(true);
    }
  }, [asPath, items]);

  return (
    <div className={depth > 0 ? 'ml-2' : ''}>
      <button
        onClick={() => setOpen(o => !o)}
        className="flex items-center justify-between w-full px-3 py-1.5 text-xs font-semibold uppercase tracking-wider text-gray-400 dark:text-gray-500 hover:text-gray-600 dark:hover:text-gray-300 transition-colors"
      >
        <span>{label}</span>
        {open
          ? <ChevronDown className="w-3 h-3" />
          : <ChevronRight className="w-3 h-3" />
        }
      </button>
      {open && (
        <div className="space-y-0.5 pb-1">
          {items.map(item => {
            if (isFlyout(item)) {
              return (
                <SidebarSection
                  key={item.section}
                  label={item.section}
                  items={item.items}
                  asPath={asPath}
                  depth={depth + 1}
                />
              );
            }
            const active = isLinkActive(item.href, asPath);
            return (
              <Link
                key={item.href}
                href={item.href}
                className={`
                  block px-3 py-1.5 text-sm rounded-md mx-1 transition-colors
                  ${active
                    ? 'text-teal-600 dark:text-teal-400 bg-teal-500/10 font-medium'
                    : 'text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50'
                  }
                `}
              >
                {item.label}
              </Link>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ─── Main sidebar nav ───────────────────────────────────────────────────────

interface SidebarNavProps {
  collapsed?: boolean;
}

export function SidebarNav({ collapsed }: SidebarNavProps) {
  const router = useRouter();
  const asPath = router.asPath;
  const activeTabId = getActiveTabId(router.pathname, router.query);

  // In collapsed mode, just show icons (first letter of tab label)
  if (collapsed) {
    return (
      <nav className="flex-1 px-1 py-4 space-y-1 overflow-y-auto">
        {TABS.map(tab => {
          const active = isTabActive(tab, router.pathname, router.query);
          return (
            <Link
              key={tab.id}
              href={tab.href || '#'}
              title={tab.label}
              className={`
                flex items-center justify-center w-10 h-10 mx-auto rounded-lg text-xs font-bold transition-colors
                ${active
                  ? 'bg-teal-600/20 text-teal-600 dark:text-teal-400 border border-teal-500/30'
                  : 'text-gray-500 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50'
                }
              `}
            >
              {tab.label.slice(0, 2)}
            </Link>
          );
        })}
      </nav>
    );
  }

  return (
    <nav className="flex-1 overflow-y-auto py-2">
      {TABS.map(tab => {
        const active = activeTabId === tab.id;

        // Simple link tab (no dropdown items)
        if (tab.href && !tab.items?.length) {
          return (
            <Link
              key={tab.id}
              href={tab.href}
              className={`
                flex items-center px-4 py-2.5 text-sm font-medium transition-colors
                ${active
