/**
 * Sidebar navigation that mirrors the top-bar AccountingNav.
 * Uses the same TABS config from accountingNavConfig.ts.
 * Renders as an accordion with collapsible sections.
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { ChevronDown, ChevronRight } from 'lucide-react';
import {
  TABS,
  getActiveTabId,
  isFlyout,
  isLinkActive,
  type Tab,
  type NavItem,
  type DropdownItem,
} from '../accounting/accountingNavConfig';

// ─── Helpers ────────────────────────────────────────────────────────────────

function collectLinks(items: NavItem[]): DropdownItem[] {
  const links: DropdownItem[] = [];
  for (const item of items) {
    if (isFlyout(item)) {
      links.push(...collectLinks(item.items));
    } else {
      links.push(item);
    }
  }
  return links;
}

function isTabActive(tab: Tab, pathname: string, query: Record<string, string | string[] | undefined>): boolean {
  return getActiveTabId(pathname, query) === tab.id;
}

// ─── Section renderer (recursive for nested flyouts) ────────────────────────

function SidebarSection({
  label,
  items,
  asPath,
  depth,
}: {
  label: string;
  items: NavItem[];
  asPath: string;
  depth: number;
}) {
  const [open, setOpen] = useState(false);

  // Auto-open if any child link is active
  useEffect(() => {
    const links = collectLinks(items);
    if (links.some(l => isLinkActive(l.href, asPath))) {
      setOpen(true);
    }
  }, [asPath, items]);

  return (
    <div className={depth > 0 ? 'ml-2' : ''}>
      <button
        onClick={() => setOpen(o => !o)}
        className="flex items-center justify-between w-full px-3 py-1.5 text-xs font-semibold uppercase tracking-wider text-gray-400 dark:text-gray-500 hover:text-gray-600 dark:hover:text-gray-300 transition-colors"
      >
        <span>{label}</span>
        {open
          ? <ChevronDown className="w-3 h-3" />
          : <ChevronRight className="w-3 h-3" />
        }
      </button>
      {open && (
        <div className="space-y-0.5 pb-1">
          {items.map(item => {
            if (isFlyout(item)) {
              return (
                <SidebarSection
                  key={item.section}
                  label={item.section}
                  items={item.items}
                  asPath={asPath}
                  depth={depth + 1}
                />
              );
            }
            const active = isLinkActive(item.href, asPath);
            return (
              <Link
                key={item.href}
                href={item.href}
                className={`
                  block px-3 py-1.5 text-sm rounded-md mx-1 transition-colors
                  ${active
                    ? 'text-teal-600 dark:text-teal-400 bg-teal-500/10 font-medium'
                    : 'text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50'
                  }
                `}
              >
                {item.label}
              </Link>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ─── Main sidebar nav ───────────────────────────────────────────────────────

interface SidebarNavProps {
  collapsed?: boolean;
}

export function SidebarNav({ collapsed }: SidebarNavProps) {
  const router = useRouter();
  const asPath = router.asPath;
  const activeTabId = getActiveTabId(router.pathname, router.query);

  // In collapsed mode, just show icons (first letter of tab label)
  if (collapsed) {
    return (
      <nav className="flex-1 px-1 py-4 space-y-1 overflow-y-auto">
        {TABS.map(tab => {
          const active = isTabActive(tab, router.pathname, router.query);
          return (
            <Link
              key={tab.id}
              href={tab.href || '#'}
              title={tab.label}
              className={`
                flex items-center justify-center w-10 h-10 mx-auto rounded-lg text-xs font-bold transition-colors
                ${active
                  ? 'bg-teal-600/20 text-teal-600 dark:text-teal-400 border border-teal-500/30'
                  : 'text-gray-500 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50'
                }
              `}
            >
              {tab.label.slice(0, 2)}
            </Link>
          );
        })}
      </nav>
    );
  }

  return (
    <nav className="flex-1 overflow-y-auto py-2">
      {TABS.map(tab => {
        const active = activeTabId === tab.id;

        // Simple link tab (no dropdown items)
        if (tab.href && !tab.items?.length) {
          return (
            <Link
              key={tab.id}
              href={tab.href}
              className={`
                flex items-center px-4 py-2.5 text-sm font-medium transition-colors
                ${active
                  ? 'text-teal-600 dark:text-teal-400 bg-teal-500/10 border-l-3 border-teal-500'
                  : 'text-gray-700 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50'
                }
              `}
            >
              {tab.label}
            </Link>
          );
        }

        // Tab with dropdown items — render as accordion
        const allLinks = tab.items ? collectLinks(tab.items) : [];
        const hasActiveChild = allLinks.some(l => isLinkActive(l.href, asPath));
        const hasSections = tab.items?.some(isFlyout) ?? false;

        return (
          <SidebarAccordionTab
            key={tab.id}
            tab={tab}
            active={active}
            hasActiveChild={hasActiveChild}
            hasSections={hasSections}
            asPath={asPath}
          />
        );
      })}
    </nav>
  );
}

// ─── Accordion tab ──────────────────────────────────────────────────────────

function SidebarAccordionTab({
  tab,
  active,
  hasActiveChild,
  hasSections,
  asPath,
}: {
  tab: Tab;
  active: boolean;
  hasActiveChild: boolean;
  hasSections: boolean;
  asPath: string;
}) {
  const [open, setOpen] = useState(hasActiveChild);

  // Auto-open when navigating to a child
  useEffect(() => {
    if (hasActiveChild) setOpen(true);
  }, [hasActiveChild]);

  return (
    <div>
      <button
        onClick={() => setOpen(o => !o)}
        className={`
          flex items-center justify-between w-full px-4 py-2.5 text-sm font-medium transition-colors
          ${active || hasActiveChild
            ? 'text-teal-600 dark:text-teal-400 bg-teal-500/5'
            : 'text-gray-700 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50'
          }
        `}
      >
        <span>{tab.label}</span>
        <ChevronDown className={`w-3.5 h-3.5 transition-transform ${open ? 'rotate-180' : ''}`} />
      </button>

      {open && (
        <div className="pb-1">
          {/* Top items (quick actions like "Add a Customer") */}
          {tab.topItems?.map(item => {
            const itemActive = isLinkActive(item.href, asPath);
            return (
              <Link
                key={item.href}
                href={item.href}
                className={`
                  block px-6 py-1.5 text-sm transition-colors
                  ${itemActive
                    ? 'text-teal-600 dark:text-teal-400 bg-teal-500/10 font-medium'
                    : 'text-teal-600/70 dark:text-teal-500/70 hover:text-teal-600 dark:hover:text-teal-400 hover:bg-gray-100 dark:hover:bg-gray-700/50'
                  }
                `}
              >
                + {item.label}
              </Link>
            );
          })}

          {/* Sections with sub-items */}
          {hasSections && tab.items?.map(item => {
            if (isFlyout(item)) {
              return (
                <SidebarSection
                  key={item.section}
                  label={item.section}
                  items={item.items}
                  asPath={asPath}
                  depth={0}
                />
              );
            }
            // Plain link items at top level
            const itemActive = isLinkActive(item.href, asPath);
            return (
              <Link
                key={item.href}
                href={item.href}
                className={`
                  block px-6 py-1.5 text-sm transition-colors
                  ${itemActive
                    ? 'text-teal-600 dark:text-teal-400 bg-teal-500/10 font-medium'
                    : 'text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50'
                  }
                `}
              >
                {item.label}
              </Link>
            );
          })}

          {/* Flat items (no sections) */}
          {!hasSections && tab.items?.map(item => {
            if (isFlyout(item)) return null;
            const itemActive = isLinkActive(item.href, asPath);
            return (
              <Link
                key={item.href}
                href={item.href}
                className={`
                  block px-6 py-1.5 text-sm transition-colors
                  ${itemActive
                    ? 'text-teal-600 dark:text-teal-400 bg-teal-500/10 font-medium'
                    : 'text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50'
                  }
                `}
              >
                {item.label}
              </Link>
            );
          })}
        </div>
      )}
    </div>
  );
}

