            >
              <LogOut className="w-4 h-4" />
            </button>
          )}
        </header>

        {/* Horizontal nav bar (only in top mode) */}
        {!showSidebar && (
          <div className="relative z-40">
            <AccountingNav />
          </div>
        )}

        {/* Page content */}
        <main className="flex-1 overflow-y-auto bg-white dark:bg-gray-950 p-4 lg:p-6 relative z-0">
          {children}
        </main>
      </div>
    </div>
  );
}

