// Step 1: Check the sidebar structure
const aside = document.querySelector('aside.lg\\:flex');
if (!aside) 'No desktop sidebar found';
else {
  const nav = aside.querySelector('nav');
  const divs = nav ? nav.querySelectorAll(':scope > div') : [];
  const links = nav ? nav.querySelectorAll(':scope > a') : [];

  // Check if the Customers div has event listeners
  let customersDiv = null;
  divs.forEach(d => { if (d.textContent?.trim().startsWith('Customers')) customersDiv = d; });

  // Try to find React fiber to check state
  let fiberKey = null;
  if (customersDiv) {
    for (const key of Object.keys(customersDiv)) {
      if (key.startsWith('__reactFiber') || key.startsWith('__reactInternalInstance')) {
        fiberKey = key;
        break;
      }
    }
  }

  // Check: does mouseenter event actually fire?
  let eventFired = false;
  if (customersDiv) {
    const origEnter = customersDiv.onmouseenter;
    customersDiv.addEventListener('mouseenter', () => { eventFired = true; }, { once: true });
    customersDiv.dispatchEvent(new MouseEvent('mouseenter', { bubbles: false }));
  }

  JSON.stringify({
    sidebarFound: !!aside,
    navFound: !!nav,
    tabDivs: divs.length,
    tabLinks: links.length,
    customersFound: !!customersDiv,
    fiberKey: fiberKey?.slice(0, 30),
    nativeEventFired: eventFired,
    // Check if any fixed-position flyout exists
    fixedFlyouts: document.querySelectorAll('[style*="position: fixed"], .fixed.z-\\[9999\\]').length,
  });
}

