/**
 * Sidebar navigation that mirrors the top-bar AccountingNav.
 * Uses the same TABS config from accountingNavConfig.ts.
 * Hover on a tab → flyout panel pops out to the right using fixed positioning
 * (so it escapes any overflow clipping on the sidebar).
 */

import { useState, useRef, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { ChevronRight } from 'lucide-react';
import {
  TABS,
  getActiveTabId,
  isFlyout,
  isLinkActive,
  type Tab,
  type NavItem,
  type DropdownItem,
} from '../accounting/accountingNavConfig';

// ─── Helpers ────────────────────────────────────────────────────────────────

function collectLinks(items: NavItem[]): DropdownItem[] {
  const links: DropdownItem[] = [];
  for (const item of items) {
    if (isFlyout(item)) {
      links.push(...collectLinks(item.items));
    } else {
      links.push(item);
    }
  }
  return links;
}

const linkCls = (active: boolean) =>
  `block px-4 py-1.5 text-sm whitespace-nowrap transition-colors ${
    active
      ? 'text-teal-400 bg-teal-500/10 font-medium'
      : 'text-gray-300 hover:text-white hover:bg-gray-700/50'
  }`;

// ─── Sub-flyout (nested sections, uses absolute positioning) ────────────────

function SubFlyout({
  items,
  asPath,
  onNavigate,
}: {
  items: NavItem[];
  asPath: string;
  onNavigate: () => void;
}) {
  const [hoveredSection, setHoveredSection] = useState<string | null>(null);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const clear = () => { if (timerRef.current) clearTimeout(timerRef.current); };
  const delayed = () => { timerRef.current = setTimeout(() => setHoveredSection(null), 120); };
  useEffect(() => () => clear(), []);

  return (
    <>
      {items.map(item => {
        if (!isFlyout(item)) {
          return (
            <Link
              key={item.href}
              href={item.href}
              onClick={onNavigate}
              className={linkCls(isLinkActive(item.href, asPath))}
            >
              {item.label}
            </Link>
          );
        }

        const isHov = hoveredSection === item.section;
        return (
          <div
            key={item.section}
            className="relative"
            onMouseEnter={() => { clear(); setHoveredSection(item.section); }}
            onMouseLeave={delayed}
          >
            <div className={`flex items-center justify-between px-4 py-1.5 text-sm cursor-default transition-colors ${
              isHov ? 'bg-gray-700 text-white' : 'text-gray-300'
            }`}>
              <span className="font-medium">{item.section}</span>
              <ChevronRight className="h-3 w-3 ml-4 flex-shrink-0" />
            </div>
            {isHov && (
              <div
                className="absolute left-full top-0 bg-gray-800 border border-gray-700 rounded-r-lg shadow-xl min-w-[200px] py-1 z-[60]"
                onMouseEnter={clear}
                onMouseLeave={delayed}
              >
                <SubFlyout items={item.items} asPath={asPath} onNavigate={onNavigate} />
              </div>
            )}
          </div>
        );
      })}
    </>
  );
}

// ─── Main flyout panel content for a tab ────────────────────────────────────

function TabFlyoutContent({
  tab,
  asPath,
  onNavigate,
}: {
  tab: Tab;
  asPath: string;
  onNavigate: () => void;
}) {
  const hasSections = tab.items?.some(isFlyout) ?? false;
  const [hoveredSection, setHoveredSection] = useState<string | null>(null);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const clear = () => { if (timerRef.current) clearTimeout(timerRef.current); };
  const delayed = () => { timerRef.current = setTimeout(() => setHoveredSection(null), 120); };
  useEffect(() => () => clear(), []);

  return (
    <>
      {/* Quick action items */}
      {tab.topItems?.map(item => (
        <Link
          key={item.href}
          href={item.href}
          onClick={onNavigate}
          className="block px-4 py-2 text-sm text-teal-400 hover:bg-gray-700/50 transition-colors whitespace-nowrap"
        >
          + {item.label}
        </Link>
      ))}
      {tab.topItems && tab.topItems.length > 0 && (
        <div className="border-t border-gray-700 my-1" />
      )}

      {/* Sectioned items with sub-flyouts */}
      {hasSections && tab.items?.map(item => {
        if (!isFlyout(item)) {
          return (
            <Link
              key={item.href}
              href={item.href}
              onClick={onNavigate}
              className={linkCls(isLinkActive(item.href, asPath))}
            >
              {item.label}
            </Link>
          );
        }

        const isHov = hoveredSection === item.section;
        return (
          <div
            key={item.section}
            className="relative"
            onMouseEnter={() => { clear(); setHoveredSection(item.section); }}
            onMouseLeave={delayed}
          >
            <div className={`flex items-center justify-between px-4 py-2 text-sm cursor-default transition-colors ${
              isHov ? 'bg-gray-700 text-white' : 'text-gray-300'
            }`}>
              <span className="font-medium">{item.section}</span>
              <ChevronRight className="h-3.5 w-3.5 ml-4 flex-shrink-0" />
            </div>
            {isHov && (
              <div
                className="absolute left-full top-0 bg-gray-800 border border-gray-700 rounded-r-lg shadow-xl min-w-[210px] py-1 z-[60]"
                onMouseEnter={clear}
                onMouseLeave={delayed}
              >
                <SubFlyout items={item.items} asPath={asPath} onNavigate={onNavigate} />
              </div>
            )}
          </div>
        );
      })}

      {/* Flat items (no sections) */}
      {!hasSections && tab.items?.map(item => {
        if (isFlyout(item)) return null;
        return (
          <Link
            key={item.href}
            href={item.href}
            onClick={onNavigate}
            className={linkCls(isLinkActive(item.href, asPath))}
          >
            {item.label}
          </Link>
        );
      })}
    </>
  );
}

// ─── Fixed-position flyout wrapper ──────────────────────────────────────────

function FixedFlyout({
  tab,
  triggerRef,
  asPath,
  onNavigate,
  onMouseEnter,
  onMouseLeave,
}: {
  tab: Tab;
  triggerRef: React.RefObject<HTMLDivElement | null>;
  asPath: string;
  onNavigate: () => void;
  onMouseEnter: () => void;
  onMouseLeave: () => void;
}) {
  const [pos, setPos] = useState<{ top: number; left: number } | null>(null);

  useEffect(() => {
    if (triggerRef.current) {
      const rect = triggerRef.current.getBoundingClientRect();
      setPos({
        top: rect.top,
        left: rect.right,
      });
    }
  }, [triggerRef]);

  if (!pos) return null;

  // Clamp so the panel doesn't go off-screen bottom
  const maxTop = typeof window !== 'undefined' ? window.innerHeight - 400 : 200;
  const clampedTop = Math.min(pos.top, maxTop);

  return (
    <div
      className="fixed z-[9999] bg-gray-800 border border-gray-700 rounded-r-lg shadow-2xl min-w-[220px] py-1 max-h-[80vh] overflow-y-auto"
      style={{ top: clampedTop, left: pos.left }}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
    >
      <TabFlyoutContent tab={tab} asPath={asPath} onNavigate={onNavigate} />
    </div>
  );
}

// ─── Main sidebar nav ───────────────────────────────────────────────────────

interface SidebarNavProps {
  collapsed?: boolean;
}

export function SidebarNav({ collapsed }: SidebarNavProps) {
  const router = useRouter();
  const asPath = router.asPath;
  const activeTabId = getActiveTabId(router.pathname, router.query);

  const [hoveredTab, setHoveredTab] = useState<string | null>(null);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const tabRefs = useRef<Record<string, HTMLDivElement | null>>({});

  const clearTimer = useCallback(() => {
    if (timerRef.current) { clearTimeout(timerRef.current); timerRef.current = null; }
  }, []);

  const delayedClose = useCallback(() => {
    timerRef.current = setTimeout(() => setHoveredTab(null), 150);
  }, []);

  // Close flyout on route change
  useEffect(() => {
    setHoveredTab(null);
  }, [router.pathname]);

  useEffect(() => () => clearTimer(), [clearTimer]);

  const hoveredTabData = hoveredTab ? TABS.find(t => t.id === hoveredTab) : null;
  const hoveredTriggerRef = useRef<HTMLDivElement | null>(null);

  // Keep ref in sync
  useEffect(() => {
    hoveredTriggerRef.current = hoveredTab ? (tabRefs.current[hoveredTab] ?? null) : null;
  }, [hoveredTab]);

  return (
    <>
      <nav className="flex-1 overflow-y-auto py-2">
        {TABS.map(tab => {
          const active = activeTabId === tab.id;
          const hasItems = !!(tab.items?.length);
          const isHovered = hoveredTab === tab.id;

          // Simple link tab (no dropdown)
          if (tab.href && !hasItems) {
            return (
              <Link
                key={tab.id}
                href={tab.href}
                className={`
                  flex items-center px-4 py-2 text-sm font-medium transition-colors
                  ${active
                    ? 'text-teal-600 dark:text-teal-400 bg-teal-500/10 border-l-2 border-teal-500'
                    : 'text-gray-700 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 border-l-2 border-transparent'
                  }
                  ${collapsed ? 'justify-center px-0' : ''}
                `}
                title={collapsed ? tab.label : undefined}
              >
                {collapsed ? tab.label.slice(0, 2) : tab.label}
              </Link>
            );
          }

          // Tab with items — hover to show flyout
          return (
            <div
              key={tab.id}
              ref={el => { tabRefs.current[tab.id] = el; }}
              onMouseEnter={() => { clearTimer(); setHoveredTab(tab.id); }}
              onMouseLeave={delayedClose}
            >
              <div
                className={`
                  flex items-center justify-between px-4 py-2 text-sm font-medium cursor-pointer transition-colors
                  ${active || isHovered
                    ? 'text-teal-600 dark:text-teal-400 bg-teal-500/10 border-l-2 border-teal-500'
                    : 'text-gray-700 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 border-l-2 border-transparent'
                  }
                  ${collapsed ? 'justify-center px-0' : ''}
                `}
                title={collapsed ? tab.label : undefined}
              >
                <span>{collapsed ? tab.label.slice(0, 2) : tab.label}</span>
                {!collapsed && <ChevronRight className={`w-3.5 h-3.5 flex-shrink-0 transition-colors ${isHovered ? 'text-teal-400' : 'text-gray-500'}`} />}
              </div>
            </div>
          );
        })}
      </nav>

      {/* Fixed-position flyout rendered outside the scrollable nav */}
      {hoveredTabData && hoveredTabData.items?.length && (
        <FixedFlyout
          tab={hoveredTabData}
          triggerRef={hoveredTriggerRef}
          asPath={asPath}
          onNavigate={() => setHoveredTab(null)}
          onMouseEnter={clearTimer}
          onMouseLeave={delayedClose}
        />
      )}
    </>
  );
}

