// ─── Tab flyout content ─────────────────────────────────────────────────────

function TabFlyoutContent({ tab, asPath, onNav }: { tab: Tab; asPath: string; onNav: () => void }) {
  const hasSections = tab.items?.some(isFlyout) ?? false;
  const [hov, setHov] = useState<string | null>(null);
  const t = useRef<ReturnType<typeof setTimeout> | null>(null);
  const cl = () => { if (t.current) clearTimeout(t.current); };
  const dl = () => { t.current = setTimeout(() => setHov(null), 120); };
  useEffect(() => () => cl(), []);

  return (
    <>
      {tab.topItems?.map(item => (
        <Link key={item.href} href={item.href} onClick={onNav} className="block px-4 py-2 text-sm text-teal-400 hover:bg-gray-700/50 transition-colors whitespace-nowrap">
          + {item.label}
        </Link>
      ))}
      {tab.topItems && tab.topItems.length > 0 && <div className="border-t border-gray-700 my-1" />}

      {hasSections && tab.items?.map(item => {
        if (!isFlyout(item)) {
          return <Link key={item.href} href={item.href} onClick={onNav} className={linkCls(isLinkActive(item.href, asPath))}>{item.label}</Link>;
        }
        const open = hov === item.section;
        return (
          <div key={item.section} className="relative" onMouseEnter={() => { cl(); setHov(item.section); }} onMouseLeave={dl}>
            <div className={`flex items-center justify-between px-4 py-2 text-sm cursor-default transition-colors ${open ? 'bg-gray-700 text-white' : 'text-gray-300'}`}>
              <span className="font-medium">{item.section}</span>
              <ChevronRight className="h-3.5 w-3.5 ml-4 flex-shrink-0" />
            </div>
            {open && (
              <div className="absolute left-full top-0 bg-gray-800 border border-gray-700 rounded-r-lg shadow-xl min-w-[210px] py-1 z-[60]" onMouseEnter={cl} onMouseLeave={dl}>
                <SubFlyout items={item.items} asPath={asPath} onNav={onNav} />
              </div>
            )}
          </div>
        );
      })}

      {!hasSections && tab.items?.map(item => {
        if (isFlyout(item)) return null;
        return <Link key={item.href} href={item.href} onClick={onNav} className={linkCls(isLinkActive(item.href, asPath))}>{item.label}</Link>;
      })}
    </>
  );
}

// ─── Portal flyout (renders in document.body to escape overflow) ────────────

function FlyoutPortal({
  tab,
  top,
  left,
  asPath,
  onNav,
  onEnter,
  onLeave,
}: {
  tab: Tab;
  top: number;
  left: number;
  asPath: string;
  onNav: () => void;
  onEnter: () => void;
  onLeave: () => void;
}) {
  // Clamp so the panel doesn't overflow the bottom of the viewport
  const maxH = typeof window !== 'undefined' ? window.innerHeight - 20 : 600;
  const clampedTop = Math.max(4, Math.min(top, maxH - 300));

  return createPortal(
    <div
      style={{ position: 'fixed', top: clampedTop, left, zIndex: 99999 }}
      className="bg-gray-800 border border-gray-700 rounded-r-lg shadow-2xl min-w-[220px] py-1 max-h-[80vh] overflow-y-auto"
      onMouseEnter={onEnter}
      onMouseLeave={onLeave}
    >
      <TabFlyoutContent tab={tab} asPath={asPath} onNav={onNav} />
    </div>,
    document.body
  );
}

// ─── Main sidebar nav ───────────────────────────────────────────────────────

interface SidebarNavProps {
  collapsed?: boolean;
}

export function SidebarNav({ collapsed }: SidebarNavProps) {
  const router = useRouter();
  const asPath = router.asPath;
  const activeTabId = getActiveTabId(router.pathname, router.query);

  const [flyout, setFlyout] = useState<{ tabId: string; top: number; left: number } | null>(null);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const clearTimer = useCallback(() => {
    if (timerRef.current) { clearTimeout(timerRef.current); timerRef.current = null; }
  }, []);

  const delayedClose = useCallback(() => {
    timerRef.current = setTimeout(() => setFlyout(null), 180);
  }, []);

  useEffect(() => { setFlyout(null); }, [router.pathname]);
  useEffect(() => () => clearTimer(), [clearTimer]);

  const openFlyout = useCallback((tabId: string, el: HTMLElement) => {
    clearTimer();
    const rect = el.getBoundingClientRect();
    setFlyout({ tabId, top: rect.top, left: rect.right });
  }, [clearTimer]);

  const flyoutTab = flyout ? TABS.find(t => t.id === flyout.tabId) : null;

  return (
    <>
      <nav className="flex-1 overflow-y-auto py-2">
        {TABS.map(tab => {
          const active = activeTabId === tab.id;
          const hasItems = !!(tab.items?.length);
          const isOpen = flyout?.tabId === tab.id;

          // Simple link tab
          if (tab.href && !hasItems) {
            return (
              <Link
                key={tab.id}
                href={tab.href}
                className={`flex items-center px-4 py-2 text-sm font-medium transition-colors border-l-2 ${
                  active
                    ? 'text-teal-600 dark:text-teal-400 bg-teal-500/10 border-teal-500'
                    : 'text-gray-700 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 border-transparent'
                } ${collapsed ? 'justify-center px-0' : ''}`}
                title={collapsed ? tab.label : undefined}
              >
                {collapsed ? tab.label.slice(0, 2) : tab.label}
              </Link>
            );
          }

          // Tab with flyout
          return (
            <div
              key={tab.id}
              onMouseEnter={(e) => openFlyout(tab.id, e.currentTarget)}
              onMouseLeave={delayedClose}
              className={`flex items-center justify-between px-4 py-2 text-sm font-medium cursor-pointer transition-colors border-l-2 ${
                active || isOpen
                  ? 'text-teal-600 dark:text-teal-400 bg-teal-500/10 border-teal-500'
                  : 'text-gray-700 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 border-transparent'
              } ${collapsed ? 'justify-center px-0' : ''}`}
              title={collapsed ? tab.label : undefined}
            >
              <span>{collapsed ? tab.label.slice(0, 2) : tab.label}</span>
              {!collapsed && <ChevronRight className={`w-3.5 h-3.5 flex-shrink-0 ${isOpen ? 'text-teal-400' : 'text-gray-500'}`} />}
            </div>
          );
        })}
      </nav>

      {/* Flyout rendered via portal in document.body — escapes all overflow */}
      {flyoutTab && flyout && (
        <FlyoutPortal
          tab={flyoutTab}
          top={flyout.top}
          left={flyout.left}
          asPath={asPath}
          onNav={() => setFlyout(null)}
          onEnter={clearTimer}
          onLeave={delayedClose}
        />
      )}
    </>
  );
}
